// ΓöÇΓöÇΓöÇ Get Open Invoices ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function getOpenInvoices(companyId: string): Promise<Array<{
  id: string; invoiceNumber: string; type: string; contactName: string;
  date: string; dueDate: string; total: number; amountPaid: number; amountDue: number;
