  const { resources: invoices } = await containers.documents().items
    .query<Invoice>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.docType = 'invoice' AND c.status IN ('posted', 'partially_paid', 'overdue')",
      parameters: [{ name: "@cid", value: companyId }],
    })
