    dueDate: inv.dueDate,
    total: inv.total,
    amountPaid: inv.amountPaid,
    amountDue: roundCurrency(inv.total - inv.amountPaid),
  }));
}

// ΓöÇΓöÇΓöÇ Suggest Ledger Account ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export function suggestLedgerAccount(description: string): { accountCode: string; accountName: string } | null {
  const lower = description.toLowerCase();
  for (const entry of ACCOUNT_SUGGESTIONS) {
    if (entry.keywords.some(kw => lower.includes(kw))) {
      return { accountCode: entry.accountCode, accountName: entry.accountName };
    }
  }
  return null;
}

// ΓöÇΓöÇΓöÇ Match Statement Line to Invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface MatchInvoiceInput {
  companyId: string;
  reconciliationId: string;
  lineId: string;
  invoiceId: string;
  invoiceNumber: string;
  allocatedAmount: number;
  differenceAccountCode?: string;
  differenceAccountName?: string;
  createdBy: string;
}

export async function matchLineToInvoice(input: MatchInvoiceInput): Promise<BankReconciliation> {
  const { resource: recon } = await containers.documents()
    .item(input.reconciliationId, input.companyId).read<BankReconciliation>();
  if (!recon) throw new GLError("NOT_FOUND", "Reconciliation not found");

  const line = recon.lines.find(l => l.id === input.lineId);
  if (!line) throw new GLError("NOT_FOUND", "Statement line not found");
  if (line.status === "posted") throw new GLError("ALREADY_POSTED", "Line already posted");

  // Read the invoice to validate
  const { resource: invoice } = await containers.documents()
    .item(input.invoiceId, input.companyId).read<Invoice>();
  if (!invoice) throw new GLError("NOT_FOUND", "Invoice not found");

  const absAmount = Math.abs(line.amount);
  const allocated = roundCurrency(input.allocatedAmount);
  const invoiceDue = roundCurrency(invoice.total - invoice.amountPaid);

  // Calculate difference
  const difference = roundCurrency(absAmount - allocated);
  let differenceType: "overpayment" | "underpayment" | "exact" = "exact";
  if (difference > 0.005) differenceType = "overpayment";
  else if (difference < -0.005) differenceType = "underpayment";

  // If there's a difference, we need a GL account for it
  if (differenceType !== "exact" && !input.differenceAccountCode) {
    throw new GLError("MISSING_ACCOUNT", "A GL account is required for over/underpayment differences");
  }

  // Determine GL accounts based on invoice type
  const isIncoming = invoice.type === "sales";
  const arApCode = isIncoming ? "2210" : "4220";
  const arApName = isIncoming ? "Accounts receivable" : "Trade payables";

  // Build journal lines
  const journalLines: JournalLine[] = [];

  if (isIncoming) {
    // Customer payment received: Dr Bank, Cr AR
    journalLines.push(
      { accountCode: recon.bankAccountCode, accountName: "Bank accounts", debit: absAmount, credit: 0, description: `Received from ${invoice.contactName} ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
      { accountCode: arApCode, accountName: arApName, debit: 0, credit: allocated, description: `AR settlement ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
    );
    if (differenceType === "overpayment" && input.differenceAccountCode) {
      journalLines.push(
        { accountCode: input.differenceAccountCode, accountName: input.differenceAccountName || "", debit: 0, credit: roundCurrency(Math.abs(difference)), description: `Overpayment ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
      );
    } else if (differenceType === "underpayment" && input.differenceAccountCode) {
      journalLines.push(
        { accountCode: arApCode, accountName: arApName, debit: 0, credit: roundCurrency(Math.abs(difference)), description: `Write-off underpayment ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
        { accountCode: input.differenceAccountCode, accountName: input.differenceAccountName || "", debit: roundCurrency(Math.abs(difference)), credit: 0, description: `Underpayment write-off ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
      );
    }
  } else {
    // Vendor payment sent: Dr AP, Cr Bank
    journalLines.push(
      { accountCode: arApCode, accountName: arApName, debit: allocated, credit: 0, description: `AP settlement ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
      { accountCode: recon.bankAccountCode, accountName: "Bank accounts", debit: 0, credit: absAmount, description: `Paid to ${invoice.contactName} ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
    );
    if (differenceType === "overpayment" && input.differenceAccountCode) {
      journalLines.push(
        { accountCode: input.differenceAccountCode, accountName: input.differenceAccountName || "", debit: roundCurrency(Math.abs(difference)), credit: 0, description: `Overpayment ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
      );
    } else if (differenceType === "underpayment" && input.differenceAccountCode) {
      journalLines.push(
        { accountCode: input.differenceAccountCode, accountName: input.differenceAccountName || "", debit: 0, credit: roundCurrency(Math.abs(difference)), description: `Write-off underpayment ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
        { accountCode: arApCode, accountName: arApName, debit: roundCurrency(Math.abs(difference)), credit: 0, description: `Underpayment write-off ΓÇö ${input.invoiceNumber}`, contactId: invoice.contactId },
      );
    }
  }

  const entry = await postJournalEntry({
    companyId: input.companyId,
    date: line.date,
    description: `Bank recon: ${isIncoming ? "received from" : "paid to"} ${invoice.contactName} ΓÇö ${input.invoiceNumber}`,
    lines: journalLines,
    sourceType: "payment",
    createdBy: input.createdBy,
  });

  // Update invoice paid amount
  invoice.amountPaid = roundCurrency(invoice.amountPaid + allocated);
  if (invoice.amountPaid >= invoice.total) {
    invoice.status = "paid";
  } else if (invoice.amountPaid > 0) {
    invoice.status = "partially_paid";
  }
  invoice.paymentJournalEntryIds.push(entry.id);
  await containers.documents().item(invoice.id, input.companyId).replace(invoice);

  // Update statement line
  line.status = "posted";
  line.matchedJournalEntryId = entry.id;
  line.matchedInvoiceId = input.invoiceId;
  line.matchedInvoiceNumber = input.invoiceNumber;
  line.allocatedAmount = allocated;
  line.differenceAmount = difference;
  line.differenceType = differenceType;
  line.differenceAccountCode = input.differenceAccountCode;
  line.differenceAccountName = input.differenceAccountName;

  await containers.documents().item(recon.id, input.companyId).replace(recon);

  await emitEvent({
    companyId: input.companyId,
    type: "bank.line.matched",
    actor: input.createdBy,
    documentType: "bank-reconciliation",
    documentId: recon.id,
    journalEntryId: entry.id,
    data: { invoiceNumber: input.invoiceNumber, amount: absAmount, difference, differenceType },
  });

  return recon;
}

// ΓöÇΓöÇΓöÇ Add Manual Transaction ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface AddManualTransactionInput {
  companyId: string;
  reconciliationId: string;
  date: string;
  description: string;
  amount: number;
  accountCode: string;
  accountName: string;
  createdBy: string;
}

export async function addManualTransaction(input: AddManualTransactionInput): Promise<BankReconciliation> {
  const { resource: recon } = await containers.documents()
    .item(input.reconciliationId, input.companyId).read<BankReconciliation>();
  if (!recon) throw new GLError("NOT_FOUND", "Reconciliation not found");
  if (recon.status === "reconciled") throw new GLError("ALREADY_RECONCILED", "Cannot add to a reconciled statement");

  const amount = Math.abs(input.amount);
  const journalLines: JournalLine[] = input.amount < 0
    ? [
        // Expense/fee (negative = money out)
        { accountCode: input.accountCode, accountName: input.accountName, debit: amount, credit: 0, description: input.description },
        { accountCode: recon.bankAccountCode, accountName: "Bank accounts", debit: 0, credit: amount, description: input.description },
      ]
    : [
        // Income (positive = money in)
        { accountCode: recon.bankAccountCode, accountName: "Bank accounts", debit: amount, credit: 0, description: input.description },
        { accountCode: input.accountCode, accountName: input.accountName, debit: 0, credit: amount, description: input.description },
      ];

  const entry = await postJournalEntry({
    companyId: input.companyId,
    date: input.date,
    description: `Bank: ${input.description}`,
    lines: journalLines,
    sourceType: "adjustment",
    createdBy: input.createdBy,
  });

  const newLine: BankStatementLine = {
    id: uuidv4(),
    date: input.date,
    description: input.description,
    amount: input.amount,
    status: "posted",
    matchedJournalEntryId: entry.id,
    accountCode: input.accountCode,
    accountName: input.accountName,
    isManual: true,
  };

  recon.lines.push(newLine);
  await containers.documents().item(recon.id, input.companyId).replace(recon);

  return recon;
}

// Budget management ΓÇö create and compare budgets vs actuals
// Sprint 4 feature

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import type { Account } from "@shared/types";

function roundCurrency(n: number): number {
  return Math.round(n * 100) / 100;
}

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface BudgetEntry {
  id: string;
  companyId: string;
  fiscalYear: number;
  period: string;           // "2026-03"
  accountCode: string;
  accountName: string;
  amount: number;
  createdAt: string;
  createdBy: string;
}

export interface BudgetVsActual {
  accountCode: string;
  accountName: string;
  accountType: string;
  budget: number;
  actual: number;
  variance: number;
  variancePercent: number;
}

// ΓöÇΓöÇΓöÇ CRUD ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function setBudget(input: {
  companyId: string;
  fiscalYear: number;
  entries: Array<{ accountCode: string; accountName: string; period: string; amount: number }>;
  createdBy: string;
}): Promise<number> {
  const now = new Date().toISOString();
  let count = 0;
  for (const e of input.entries) {
    const id = `${input.companyId}-budget-${input.fiscalYear}-${e.period}-${e.accountCode}`;
    const entry: BudgetEntry = {
      id,
      companyId: input.companyId,
      fiscalYear: input.fiscalYear,
      period: e.period,
      accountCode: e.accountCode,
      accountName: e.accountName,
      amount: e.amount,
      createdAt: now,
      createdBy: input.createdBy,
    };
    try {
      await containers.ledger().items.upsert(entry);
      count++;
    } catch { /* skip */ }
  }
  return count;
}

export async function getBudgetVsActual(companyId: string, fiscalYear: number): Promise<BudgetVsActual[]> {
  // Get budget entries
  const { resources: budgets } = await containers.ledger().items
    .query<BudgetEntry>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.docType = 'budget' AND c.fiscalYear = @year",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@year", value: fiscalYear },
      ],
    })
    .fetchAll();

  // Get actual account balances (revenue + expense)
  const { resources: accounts } = await containers.ledger().items
    .query<Account>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'account' OR (IS_DEFINED(c.code) AND IS_DEFINED(c.normalSide))) AND c.isPostable = true AND (c.type = 'revenue' OR c.type = 'expense') ORDER BY c.code",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  // Aggregate budgets by account
  const budgetByAccount = new Map<string, number>();
  for (const b of budgets) {
    budgetByAccount.set(b.accountCode, (budgetByAccount.get(b.accountCode) || 0) + b.amount);
  }

  // Build comparison
  const result: BudgetVsActual[] = [];
  const allCodes = new Set([...budgetByAccount.keys(), ...accounts.map(a => a.code)]);

  for (const code of allCodes) {
    const acct = accounts.find(a => a.code === code);
    const budget = budgetByAccount.get(code) || 0;
    const actual = acct ? Math.abs(acct.balance) : 0;
    const variance = roundCurrency(budget - actual);

    result.push({
      accountCode: code,
      accountName: acct?.name || budgets.find(b => b.accountCode === code)?.accountName || code,
      accountType: acct?.type || "expense",
      budget: roundCurrency(budget),
      actual: roundCurrency(actual),
      variance,
      variancePercent: budget !== 0 ? roundCurrency((variance / budget) * 100) : 0,
    });
  }

  return result.sort((a, b) => a.accountCode.localeCompare(b.accountCode));
}

// Latvian Enterprise Register (Uz┼å─ômumu re─úistrs) ΓÇö company lookup
// Sources:
// 1. data.gov.lv CKAN Datastore API (open data, updated daily)
// 2. info.ur.gov.lv (official portal ΓÇö limited without auth)
//
// The data.gov.lv datastore has the "register" dataset with company details
// searchable via SQL-like queries on the CKAN datastore_search_sql endpoint.

const CKAN_BASE = "https://data.gov.lv/dati/api/3/action";

// Resource IDs from data.gov.lv for UR (Uz┼å─ômumu re─úistrs) datasets
// The main enterprise register resource (register dataset)
const UR_REGISTER_RESOURCE = "25e80bf3-f107-4ab4-89ef-251b5b9374e9";

interface URCompanyRecord {
  regcode: string;           // Registration number (11 digits)
  name: string;              // Company name
  type: string;              // Legal form (SIA, AS, IK, etc.)
  registered: string;        // Registration date
  address: string;           // Legal address
  status?: string;           // Active/liquidated etc.
}

export interface CompanyLookupResult {
  found: boolean;
  results: Array<{
    registrationNumber: string;
    name: string;
    legalForm: string;
    address: string;
    registeredDate: string;
  }>;
  source: string;
}

// ΓöÇΓöÇΓöÇ Search by name ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function searchCompanyByName(query: string): Promise<CompanyLookupResult> {
  try {
    // Try CKAN datastore search first
    const result = await ckanDatastoreSearch(query);
    if (result.found) return result;

    // Fallback: try the official info.ur.gov.lv search
    return await urGovSearch(query);
  } catch {
    return { found: false, results: [], source: "error ΓÇö could not reach Latvian registers" };
  }
}

// ΓöÇΓöÇΓöÇ Search by registration number ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function searchCompanyByRegNumber(regNumber: string): Promise<CompanyLookupResult> {
  try {
    const result = await ckanDatastoreSearchByRegCode(regNumber);
    if (result.found) return result;
    return await urGovSearch(regNumber);
  } catch {
    return { found: false, results: [], source: "error" };
  }
}

// ΓöÇΓöÇΓöÇ CKAN Datastore Search ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function ckanDatastoreSearch(query: string): Promise<CompanyLookupResult> {
  // Use datastore_search with full-text filter
  const url = new URL(`${CKAN_BASE}/datastore_search`);
  const params = {
    resource_id: UR_REGISTER_RESOURCE,
    q: query,
    limit: "10",
  };

  const res = await fetch(`${url}?${new URLSearchParams(params)}`, {
    headers: { "Accept": "application/json" },
    signal: AbortSignal.timeout(10000),
  });

  if (!res.ok) {
    // Resource ID might be wrong ΓÇö try alternative search
    return { found: false, results: [], source: "ckan-unavailable" };
  }

  const data = await res.json();
  if (!data.success || !data.result?.records?.length) {
    return { found: false, results: [], source: "data.gov.lv" };
  }

  return {
    found: true,
    results: data.result.records.map((r: Record<string, string>) => ({
      registrationNumber: r.regcode || "",
      name: r.name || "",
      legalForm: r.type_text || r.type || "",
      address: r.address || "",
      registeredDate: r.registered || "",
    })),
    source: "data.gov.lv (Uz┼å─ômumu re─úistrs)",
  };
}

async function ckanDatastoreSearchByRegCode(regCode: string): Promise<CompanyLookupResult> {
  const url = new URL(`${CKAN_BASE}/datastore_search`);
  const filters = JSON.stringify({ regcode: regCode });
  const params = {
    resource_id: UR_REGISTER_RESOURCE,
    filters,
    limit: "5",
  };

  const res = await fetch(`${url}?${new URLSearchParams(params)}`, {
    headers: { "Accept": "application/json" },
    signal: AbortSignal.timeout(10000),
  });

  if (!res.ok) return { found: false, results: [], source: "ckan-unavailable" };

  const data = await res.json();
  if (!data.success || !data.result?.records?.length) {
    return { found: false, results: [], source: "data.gov.lv" };
  }

  return {
    found: true,
    results: data.result.records.map((r: Record<string, string>) => ({
      registrationNumber: r.regcode || "",
      name: r.name || "",
      legalForm: r.type_text || r.type || "",
      address: r.address || "",
      registeredDate: r.registered || "",
    })),
    source: "data.gov.lv (Uz┼å─ômumu re─úistrs)",
  };
}

// ΓöÇΓöÇΓöÇ Fallback: info.ur.gov.lv search ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function urGovSearch(query: string): Promise<CompanyLookupResult> {
  // info.ur.gov.lv has a public search endpoint (no auth needed for basic info)
  // This returns HTML, but we can parse basic results from the JSON API
  try {
    const url = `https://info.ur.gov.lv/api/companies?query=${encodeURIComponent(query)}&limit=10`;
    const res = await fetch(url, {
      headers: { "Accept": "application/json" },
      signal: AbortSignal.timeout(10000),
    });

    if (!res.ok) {
      return { found: false, results: [], source: "info.ur.gov.lv ΓÇö unavailable" };
    }

    const data = await res.json();
    if (!data?.length) {
      return { found: false, results: [], source: "info.ur.gov.lv" };
    }

    return {
      found: true,
      results: data.map((r: Record<string, string>) => ({
        registrationNumber: r.regcode || r.registration_number || "",
        name: r.name || "",
        legalForm: r.type || "",
        address: r.address || "",
        registeredDate: r.registered || "",
      })),
      source: "info.ur.gov.lv (Uz┼å─ômumu re─úistrs)",
    };
  } catch {
    return { found: false, results: [], source: "info.ur.gov.lv ΓÇö unavailable" };
  }
}

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import { buildAccountsForCompany } from "./chart-of-accounts.js";
import { emitEvent } from "./events.js";
import type { Company, CompanySettings } from "@shared/types";

interface CreateCompanyInput {
  name: string;
  code?: string;
  registrationNumber: string;
  vatNumber?: string;
  legalAddress: Company["legalAddress"];
  createdBy: string;
}

// Generate a short code from company name (max 5 chars, uppercase)
// "SIA DAIS" ΓåÆ "DAIS", "Sabiedr─½ba ar ierobe┼╛otu atbild─½bu \"DAIS\"" ΓåÆ "DAIS"
function generateCode(name: string): string {
  // Try to extract quoted name first (common in LV register)
  const quoted = name.match(/[""]([^""]+)[""]/) || name.match(/"([^"]+)"/);
  const cleanName = quoted ? quoted[1] : name;

  // Remove common prefixes
  const stripped = cleanName
    .replace(/^(SIA|AS|IK|ZS|PS)\s+/i, "")
    .replace(/^Sabiedr─½ba ar ierobe┼╛otu atbild─½bu\s*/i, "")
    .trim();

  // Take first 5 meaningful characters, uppercase
  return stripped
    .replace(/[^a-zA-Z─ü─ì─ô─ú─½─╖─╝┼å┼í┼½┼╛─Ç─î─Æ─ó─¬─╢─╗┼à┼á┼¬┼╜0-9]/g, "")
    .slice(0, 5)
    .toUpperCase();
}

export async function createCompany(input: CreateCompanyInput): Promise<Company> {
  const id = uuidv4();
  const now = new Date().toISOString();
  const code = input.code || generateCode(input.name);

  const settings: CompanySettings = {
    isVatRegistered: !!input.vatNumber,
    vatRate: 21,
    defaultPaymentTermsDays: 30,
    invoiceNumberPrefix: "INV",
    nextInvoiceNumber: 1,
  };

  const company: Company = {
    id,
    code,
    name: input.name,
    registrationNumber: input.registrationNumber,
    vatNumber: input.vatNumber,
    legalAddress: input.legalAddress,
    bankAccounts: [],
    fiscalYearStart: 1,
    currency: "EUR",
    country: "LV",
    settings,
    createdAt: now,
    updatedAt: now,
  };

  // Create company
  await containers.companies().items.create(company);

  // Pre-populate Latvian Chart of Accounts
  const accounts = buildAccountsForCompany(id, input.createdBy);
  const ledgerContainer = containers.ledger();
  for (const account of accounts) {
    await ledgerContainer.items.create(account);
  }

  await emitEvent({
    companyId: id,
    type: "company.created",
    actor: input.createdBy,
    documentType: "company",
    documentId: id,
    data: { name: company.name, code: company.code },
  });

  return company;
}

export async function getCompany(id: string): Promise<Company | null> {
  try {
    const { resource } = await containers.companies().item(id, id).read<Company>();
    return resource ?? null;
  } catch {
    return null;
  }
}

export async function updateCompany(
  id: string,
  updates: Partial<Pick<Company, "code" | "name" | "vatNumber" | "settings" | "bankAccounts" | "legalAddress">>
): Promise<Company | null> {
  const company = await getCompany(id);
  if (!company) return null;

  Object.assign(company, updates, { updatedAt: new Date().toISOString() });
  const { resource } = await containers.companies().item(id, id).replace(company);
  return resource ?? null;
}

export async function getCompanyStats(id: string): Promise<{ transactionCount: number }> {
  const { resources: txns } = await containers.ledger().items
    .query<number>({
      query: "SELECT VALUE COUNT(1) FROM c WHERE c.companyId = @companyId AND c.docType != 'account'",
      parameters: [{ name: "@companyId", value: id }],
    })
    .fetchAll();
  return { transactionCount: txns[0] ?? 0 };
}

export async function deleteCompany(id: string): Promise<{ deleted: boolean }> {
  const company = await getCompany(id);
  if (!company) throw new Error("Company not found");

  // Delete all ledger items (accounts, journal entries, etc.)
  const { resources: ledgerItems } = await containers.ledger().items
    .query<{ id: string }>({
      query: "SELECT c.id FROM c WHERE c.companyId = @companyId",
      parameters: [{ name: "@companyId", value: id }],
    })
    .fetchAll();
  for (const item of ledgerItems) {
    await containers.ledger().item(item.id, id).delete();
  }

  // Delete documents (invoices)
  const { resources: docs } = await containers.documents().items
    .query<{ id: string }>({
      query: "SELECT c.id FROM c WHERE c.companyId = @companyId",
      parameters: [{ name: "@companyId", value: id }],
    })
    .fetchAll();
  for (const doc of docs) {
    await containers.documents().item(doc.id, id).delete();
  }

  // Delete contacts
  const { resources: contacts } = await containers.contacts().items
    .query<{ id: string }>({
      query: "SELECT c.id FROM c WHERE c.companyId = @companyId",
      parameters: [{ name: "@companyId", value: id }],
    })
    .fetchAll();
  for (const contact of contacts) {
    await containers.contacts().item(contact.id, id).delete();
  }

  // Delete inventory
  const { resources: items } = await containers.inventory().items
    .query<{ id: string }>({
      query: "SELECT c.id FROM c WHERE c.companyId = @companyId",
      parameters: [{ name: "@companyId", value: id }],
    })
    .fetchAll();
  for (const item of items) {
    await containers.inventory().item(item.id, id).delete();
  }

  // Delete events
  const { resources: events } = await containers.events().items
    .query<{ id: string }>({
      query: "SELECT c.id FROM c WHERE c.companyId = @companyId",
      parameters: [{ name: "@companyId", value: id }],
    })
    .fetchAll();
  for (const event of events) {
    await containers.events().item(event.id, id).delete();
  }

  // Delete the company itself
  await containers.companies().item(id, id).delete();

  return { deleted: true };
}

// Fixed assets ΓÇö acquisition, depreciation, disposal
// Sprint 4 feature

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import { postJournalEntry, GLError } from "./ledger.js";
import { emitEvent } from "./events.js";
import { getNextNumber } from "./sequences.js";
import type { JournalLine } from "@shared/types";

function roundCurrency(n: number): number {
  return Math.round(n * 100) / 100;
}

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface FixedAsset {
  id: string;
  companyId: string;
  docType: "fixed-asset";
  code: string;
  name: string;
  description?: string;
  assetAccountCode: string;       // e.g. "1210" Land and buildings
  depreciationAccountCode: string; // e.g. "1240" Accumulated depreciation
  expenseAccountCode: string;      // e.g. "6380" Depreciation expense
  acquisitionDate: string;
  acquisitionCost: number;
  residualValue: number;
  usefulLifeMonths: number;
  depreciationMethod: "straight-line";
  accumulatedDepreciation: number;
  netBookValue: number;
  status: "active" | "fully-depreciated" | "disposed";
  disposalDate?: string;
  disposalAmount?: number;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
  createdBy: string;
}

// ΓöÇΓöÇΓöÇ Acquire ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface AcquireAssetInput {
  companyId: string;
  code: string;
  name: string;
  description?: string;
  assetAccountCode: string;
  depreciationAccountCode: string;
  expenseAccountCode: string;
  acquisitionDate: string;
  acquisitionCost: number;
  residualValue: number;
  usefulLifeMonths: number;
  createdBy: string;
}

export async function acquireAsset(input: AcquireAssetInput): Promise<FixedAsset> {
  const code = input.code || await getNextNumber(input.companyId, "fixedAsset");
  const now = new Date().toISOString();
  const asset: FixedAsset = {
    id: uuidv4(),
    companyId: input.companyId,
    docType: "fixed-asset" as const,
    code,
    name: input.name,
    description: input.description,
    assetAccountCode: input.assetAccountCode,
    depreciationAccountCode: input.depreciationAccountCode,
    expenseAccountCode: input.expenseAccountCode,
    acquisitionDate: input.acquisitionDate,
    acquisitionCost: input.acquisitionCost,
    residualValue: input.residualValue,
    usefulLifeMonths: input.usefulLifeMonths,
    depreciationMethod: "straight-line",
    accumulatedDepreciation: 0,
    netBookValue: input.acquisitionCost,
    status: "active",
    isActive: true,
    createdAt: now,
    updatedAt: now,
    createdBy: input.createdBy,
  };

  // Post acquisition journal: DR Asset account, CR Bank/AP
  await postJournalEntry({
    companyId: input.companyId,
    date: input.acquisitionDate,
    description: `Acquire fixed asset: ${input.name}`,
    lines: [
      { accountCode: input.assetAccountCode, accountName: input.name, debit: input.acquisitionCost, credit: 0, description: `Acquisition - ${input.name}` },
      { accountCode: "2420", accountName: "Bank accounts", debit: 0, credit: input.acquisitionCost, description: `Payment for ${input.name}` },
    ],
    sourceType: "manual",
    sourceId: asset.id,
    createdBy: input.createdBy,
  });

  await containers.inventory().items.create(asset);

  await emitEvent({
    companyId: input.companyId,
    type: "asset.acquired",
    actor: input.createdBy,
    documentType: "fixed-asset",
    documentId: asset.id,
    data: { code: asset.code, name: asset.name, cost: asset.acquisitionCost },
  });

  return asset;
}

// ΓöÇΓöÇΓöÇ Depreciate ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function runDepreciation(
  companyId: string,
  period: string,
  createdBy: string
): Promise<{ assetsDepreciated: number; totalAmount: number; journalEntryId?: string; skipped?: boolean }> {
  const { resources: assets } = await containers.inventory().items
    .query<FixedAsset>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.docType = 'fixed-asset' AND c.status = 'active'",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  if (assets.length === 0) return { assetsDepreciated: 0, totalAmount: 0 };

  // Check if depreciation for this period already exists
  const depDescription = `Monthly depreciation - ${period}`;
  const { resources: existingEntries } = await containers.ledger().items
    .query<any>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.description = @desc AND c.status != 'reversed' AND (c.docType = 'journal-entry' OR IS_DEFINED(c.entryNumber))",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@desc", value: depDescription },
      ],
    })
    .fetchAll();

  const lines: JournalLine[] = [];
  let totalAmount = 0;

  for (const asset of assets) {
    const depreciableAmount = asset.acquisitionCost - asset.residualValue;
    const monthlyDepreciation = roundCurrency(depreciableAmount / asset.usefulLifeMonths);
    const remaining = roundCurrency(depreciableAmount - asset.accumulatedDepreciation);

    if (remaining <= 0) continue;

    const amount = Math.min(monthlyDepreciation, remaining);

    lines.push(
      { accountCode: asset.expenseAccountCode, accountName: `Depreciation - ${asset.name}`, debit: amount, credit: 0, description: `Monthly depreciation ${period}` },
      { accountCode: asset.depreciationAccountCode, accountName: `Accum. depreciation - ${asset.name}`, debit: 0, credit: amount, description: `Monthly depreciation ${period}` },
    );

    totalAmount += amount;
  }

  if (lines.length === 0) return { assetsDepreciated: 0, totalAmount: 0 };

  // If existing entry has the same total, skip (idempotent)
  if (existingEntries.length > 0) {
    const existingTotal = roundCurrency(
      existingEntries[0].lines?.reduce((s: number, l: any) => s + (l.debit || 0), 0) || 0
    );
    if (existingTotal === roundCurrency(totalAmount)) {
      return { assetsDepreciated: assets.length, totalAmount: roundCurrency(totalAmount), journalEntryId: existingEntries[0].id, skipped: true };
    }

    // Amounts differ - reverse the old entry and post a new one
    // First, reverse the asset accum depreciation from the old entry
    for (const asset of assets) {
      const oldLines = existingEntries[0].lines?.filter((l: any) =>
        l.accountName?.includes(asset.name) && l.credit > 0
      ) || [];
      const oldAmount = oldLines.reduce((s: number, l: any) => s + l.credit, 0);
      if (oldAmount > 0) {
        asset.accumulatedDepreciation = roundCurrency(asset.accumulatedDepreciation - oldAmount);
        asset.netBookValue = roundCurrency(asset.acquisitionCost - asset.accumulatedDepreciation);
        if (asset.status === "fully-depreciated") asset.status = "active";
      }
    }

    // Reverse the old journal entry
    const { reverseJournalEntry } = await import("./ledger.js");
    await reverseJournalEntry(companyId, existingEntries[0].id, createdBy);
  }

  // Update asset balances
  for (const asset of assets) {
    const depreciableAmount = asset.acquisitionCost - asset.residualValue;
    const monthlyDepreciation = roundCurrency(depreciableAmount / asset.usefulLifeMonths);
    const remaining = roundCurrency(depreciableAmount - asset.accumulatedDepreciation);
    if (remaining <= 0) continue;

    const amount = Math.min(monthlyDepreciation, remaining);
    asset.accumulatedDepreciation = roundCurrency(asset.accumulatedDepreciation + amount);
    asset.netBookValue = roundCurrency(asset.acquisitionCost - asset.accumulatedDepreciation);
    if (asset.accumulatedDepreciation >= depreciableAmount) asset.status = "fully-depreciated";
    asset.updatedAt = new Date().toISOString();
    await containers.inventory().item(asset.id, companyId).replace(asset);
  }

  const [y, m] = period.split("-").map(Number);
  const lastDay = new Date(y, m, 0).getDate();
  const entry = await postJournalEntry({
    companyId,
    date: `${period}-${lastDay}`,
    description: depDescription,
    lines,
    sourceType: "adjustment",
    createdBy,
  });

  return { assetsDepreciated: assets.filter(a => a.status === "active").length, totalAmount: roundCurrency(totalAmount), journalEntryId: entry.id };
}

// ΓöÇΓöÇΓöÇ Dispose ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function disposeAsset(
  companyId: string,
  assetId: string,
  disposalDate: string,
  disposalAmount: number,
  createdBy: string
): Promise<FixedAsset> {
  const { resource: asset } = await containers.inventory()
    .item(assetId, companyId).read<FixedAsset>();
  if (!asset) throw new GLError("NOT_FOUND", "Asset not found");
  if (asset.status === "disposed") throw new GLError("ALREADY_DISPOSED", "Asset already disposed");

  const gainOrLoss = roundCurrency(disposalAmount - asset.netBookValue);
  const lines: JournalLine[] = [
    // Remove accumulated depreciation
    { accountCode: asset.depreciationAccountCode, accountName: "Accum. depreciation", debit: asset.accumulatedDepreciation, credit: 0, description: "Remove accumulated depreciation" },
    // Remove asset cost
    { accountCode: asset.assetAccountCode, accountName: asset.name, debit: 0, credit: asset.acquisitionCost, description: "Remove asset cost" },
  ];

  if (disposalAmount > 0) {
    lines.push({ accountCode: "2420", accountName: "Bank accounts", debit: disposalAmount, credit: 0, description: `Disposal proceeds - ${asset.name}` });
  }

  if (gainOrLoss > 0) {
    lines.push({ accountCode: "5230", accountName: "Other operating income", debit: 0, credit: gainOrLoss, description: "Gain on disposal" });
  } else if (gainOrLoss < 0) {
    lines.push({ accountCode: "6390", accountName: "Other administrative expenses", debit: Math.abs(gainOrLoss), credit: 0, description: "Loss on disposal" });
  }

  await postJournalEntry({ companyId, date: disposalDate, description: `Dispose: ${asset.name}`, lines, sourceType: "adjustment", sourceId: assetId, createdBy });

  asset.status = "disposed";
  asset.disposalDate = disposalDate;
  asset.disposalAmount = disposalAmount;
  asset.netBookValue = 0;
  asset.updatedAt = new Date().toISOString();
  await containers.inventory().item(assetId, companyId).replace(asset);

  return asset;
}

// ΓöÇΓöÇΓöÇ List ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function listFixedAssets(companyId: string): Promise<FixedAsset[]> {
  const { resources } = await containers.inventory().items
    .query<FixedAsset>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.docType = 'fixed-asset' ORDER BY c.code",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();
  return resources;
}

// Invoice PDF generation ΓÇö Latvian-compliant invoice layout
// Uses PDFKit to generate server-side PDF

import PDFDocument from "pdfkit";
import { containers } from "./cosmos.js";
import { GLError } from "./ledger.js";
import type { Invoice, Company } from "@shared/types";

export async function generateInvoicePdf(
  companyId: string,
  invoiceId: string
): Promise<Buffer> {
  const [{ resource: invoice }, { resource: company }] = await Promise.all([
    containers.documents().item(invoiceId, companyId).read<Invoice>(),
    containers.companies().item(companyId, companyId).read<Company>(),
  ]);

  if (!invoice) throw new GLError("NOT_FOUND", "Invoice not found");
  if (!company) throw new GLError("COMPANY_NOT_FOUND", "Company not found");

  // Get contact details
  let contactAddress = "";
  let contactRegNumber = "";
  let contactVatNumber = "";
  try {
    const { resource: contact } = await containers.contacts()
      .item(invoice.contactId, companyId).read<any>();
    if (contact) {
      contactAddress = [contact.address?.line1, contact.address?.city, contact.address?.postalCode].filter(Boolean).join(", ");
      contactRegNumber = contact.registrationNumber || "";
      contactVatNumber = contact.vatNumber || "";
    }
  } catch { /* contact may not exist */ }

  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: "A4", margin: 50 });
    const chunks: Buffer[] = [];

    doc.on("data", (chunk: Buffer) => chunks.push(chunk));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);

    const isSales = invoice.type === "sales";
    const pageWidth = 595.28 - 100; // A4 width minus margins

    // ΓöÇΓöÇΓöÇ Header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    doc.fontSize(20).font("Helvetica-Bold").text(company.name, { align: "left" });
    doc.fontSize(9).font("Helvetica").fillColor("#666666");
    doc.text(`Reg. Nr. ${company.registrationNumber}`);
    if (company.vatNumber) doc.text(`PVN Nr. ${company.vatNumber}`);
    const addr = company.legalAddress;
    doc.text([addr.line1, addr.city, addr.postalCode, addr.country].filter(Boolean).join(", "));
    if (company.bankAccounts?.[0]) {
      doc.text(`IBAN: ${company.bankAccounts[0].iban}  SWIFT: ${company.bankAccounts[0].swift}`);
    }

    doc.moveDown(1.5);

    // ΓöÇΓöÇΓöÇ Invoice Title ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const title = (invoice as any).creditNoteFor
      ? `CREDIT NOTE / KRED─¬TNOTA`
      : isSales ? "INVOICE / R─Æ─╢INS" : "PURCHASE INVOICE";
    doc.fontSize(16).font("Helvetica-Bold").fillColor("#1C1C1C").text(title);
    doc.moveDown(0.5);

    // ΓöÇΓöÇΓöÇ Invoice Meta ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    doc.fontSize(10).font("Helvetica").fillColor("#333333");
    const metaY = doc.y;
    doc.text(`Nr: ${invoice.invoiceNumber}`, 50, metaY);
    doc.text(`Date: ${invoice.date}`, 50, metaY + 14);
    doc.text(`Due date: ${invoice.dueDate}`, 50, metaY + 28);

    const recipientLabel = isSales ? "Bill to:" : "From:";
    doc.font("Helvetica-Bold").text(recipientLabel, 300, metaY);
    doc.font("Helvetica").text(invoice.contactName, 300, metaY + 14);
    if (contactRegNumber) doc.text(`Reg. Nr. ${contactRegNumber}`, 300, metaY + 28);
    if (contactVatNumber) doc.text(`PVN Nr. ${contactVatNumber}`, 300, metaY + 42);
    if (contactAddress) doc.text(contactAddress, 300, metaY + 56);

    doc.y = Math.max(doc.y, metaY + 76);
    doc.moveDown(1);

    // ΓöÇΓöÇΓöÇ Line Items Table ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const tableTop = doc.y;
    const col = { desc: 50, qty: 300, price: 350, vat: 420, total: 470 };

    // Header row
    doc.fontSize(8).font("Helvetica-Bold").fillColor("#888888");
    doc.text("DESCRIPTION", col.desc, tableTop);
    doc.text("QTY", col.qty, tableTop, { width: 40, align: "right" });
    doc.text("PRICE", col.price, tableTop, { width: 60, align: "right" });
    doc.text("VAT %", col.vat, tableTop, { width: 40, align: "right" });
    doc.text("TOTAL", col.total, tableTop, { width: 75, align: "right" });

    doc.moveTo(50, tableTop + 14).lineTo(50 + pageWidth, tableTop + 14).strokeColor("#E0E0E0").stroke();

    let y = tableTop + 22;
    doc.fontSize(9).font("Helvetica").fillColor("#333333");

    for (const line of invoice.lines) {
      if (y > 720) {
        doc.addPage();
        y = 50;
      }
      doc.text(line.description, col.desc, y, { width: 240 });
      doc.text(String(line.quantity), col.qty, y, { width: 40, align: "right" });
      doc.text(`Γé¼${line.unitPrice.toFixed(2)}`, col.price, y, { width: 60, align: "right" });
      doc.text(`${line.vatRate}%`, col.vat, y, { width: 40, align: "right" });
      doc.text(`Γé¼${line.lineTotal.toFixed(2)}`, col.total, y, { width: 75, align: "right" });
      y += 18;
    }

    // ΓöÇΓöÇΓöÇ Totals ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    y += 8;
    doc.moveTo(350, y).lineTo(50 + pageWidth, y).strokeColor("#E0E0E0").stroke();
    y += 10;

    const subtotal = Math.abs(invoice.subtotal);
    const vatAmount = Math.abs(invoice.vatAmount);
    const total = Math.abs(invoice.total);
    const sign = invoice.total < 0 ? "-" : "";

    doc.fontSize(9).font("Helvetica");
    doc.text("Subtotal:", 350, y, { width: 100, align: "right" });
    doc.text(`${sign}Γé¼${subtotal.toFixed(2)}`, col.total, y, { width: 75, align: "right" });
    y += 16;

    doc.text(`VAT:`, 350, y, { width: 100, align: "right" });
    doc.text(`${sign}Γé¼${vatAmount.toFixed(2)}`, col.total, y, { width: 75, align: "right" });
    y += 16;

    doc.moveTo(350, y).lineTo(50 + pageWidth, y).strokeColor("#1C1C1C").lineWidth(1).stroke();
    y += 8;

    doc.fontSize(12).font("Helvetica-Bold");
    doc.text("Total:", 350, y, { width: 100, align: "right" });
    doc.text(`${sign}Γé¼${total.toFixed(2)}`, col.total, y, { width: 75, align: "right" });

    // ΓöÇΓöÇΓöÇ Footer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if ((invoice as any).creditNoteFor) {
      doc.moveDown(2);
      doc.fontSize(9).font("Helvetica").fillColor("#666666");
      doc.text(`Credit note for invoice: ${(invoice as any).creditNoteFor}`);
      if ((invoice as any).creditNoteReason) {
        doc.text(`Reason: ${(invoice as any).creditNoteReason}`);
      }
    }

    // Payment info for sales invoices
    if (isSales && company.bankAccounts?.[0]) {
      const bank = company.bankAccounts[0];
      doc.y = 730;
      doc.fontSize(8).font("Helvetica").fillColor("#888888");
      doc.text(`Payment: ${bank.bankName} | IBAN: ${bank.iban} | SWIFT: ${bank.swift}`, 50, doc.y, { align: "center", width: pageWidth });
    }

    doc.end();
  });
}

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import { postJournalEntry, GLError } from "./ledger.js";
import { emitEvent } from "./events.js";
import { getActiveRule, evaluateInvoiceRule } from "./posting-rules.js";
import { getNextNumber } from "./sequences.js";
import type { Invoice, InvoiceLine, JournalLine, Company } from "@shared/types";
import { VAT_RATES } from "@shared/constants";

// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function roundCurrency(n: number): number {
  return Math.round(n * 100) / 100;
}

function calcLineTotals(line: Omit<InvoiceLine, "vatAmount" | "lineTotal">): InvoiceLine {
  const net = roundCurrency(line.quantity * line.unitPrice);
  const vatAmount = roundCurrency(net * line.vatRate / 100);
  return {
    ...line,
    vatAmount,
    lineTotal: roundCurrency(net + vatAmount),
  };
}

async function nextInvoiceNumber(company: Company, type: "sales" | "purchase"): Promise<string> {
  const seqType = type === "sales" ? "salesInvoice" as const : "purchaseInvoice" as const;
  return getNextNumber(company.id, seqType);
}

// ΓöÇΓöÇΓöÇ Create Invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface CreateInvoiceInput {
  companyId: string;
  type: "sales" | "purchase";
  contactId: string;
  contactName: string;
  date: string;
  dueDate: string;
  vendorInvoiceNumber?: string;
  recognitionConfidence?: "high" | "medium" | "low";
  lines: Array<{
    description: string;
    quantity: number;
    unitPrice: number;
    vatRate: number;
    accountCode: string;
    itemId?: string;
  }>;
  createdBy: string;
}

export async function createInvoice(input: CreateInvoiceInput): Promise<Invoice> {
  // Get company
  const { resource: company } = await containers.companies()
    .item(input.companyId, input.companyId)
    .read<Company>();
  if (!company) throw new GLError("COMPANY_NOT_FOUND", "Company not found");

  // Validate VAT rates
  const validRates: readonly number[] = Object.values(VAT_RATES);
  for (const line of input.lines) {
    if (!validRates.includes(line.vatRate)) {
      throw new GLError("INVALID_VAT_RATE", `VAT rate ${line.vatRate}% is not valid. Use: ${validRates.join(", ")}`);
    }
  }

  // Calculate line totals
  const lines = input.lines.map(calcLineTotals);
  const subtotal = roundCurrency(lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0));
  const vatAmount = roundCurrency(lines.reduce((s, l) => s + l.vatAmount, 0));
  const total = roundCurrency(subtotal + vatAmount);

  const invoiceNumber = await nextInvoiceNumber(company, input.type);
  const now = new Date().toISOString();

  const invoice: Invoice = {
    id: uuidv4(),
    docType: "invoice" as const,
    companyId: input.companyId,
    invoiceNumber,
    type: input.type,
    contactId: input.contactId,
    contactName: input.contactName,
    date: input.date,
    dueDate: input.dueDate,
    lines,
    subtotal,
    vatAmount,
    total,
    amountPaid: 0,
    status: "draft",
    currency: "EUR",
    documentNumber: invoiceNumber,
    documentDate: input.date,
    vendorInvoiceNumber: input.vendorInvoiceNumber,
    recognitionConfidence: input.recognitionConfidence,
    paymentJournalEntryIds: [],
    isActive: true,
    createdAt: now,
    updatedAt: now,
    createdBy: input.createdBy,
  };

  await containers.documents().items.create(invoice);

  await emitEvent({
    companyId: input.companyId,
    type: "invoice.created",
    actor: input.createdBy,
    documentType: "invoice",
    documentId: invoice.id,
    data: { invoiceNumber: invoice.invoiceNumber, type: invoice.type, total: invoice.total },
  });

  return invoice;
}

// ΓöÇΓöÇΓöÇ Post Invoice (draft ΓåÆ posted, creates GL entries) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function postInvoice(
  companyId: string,
  invoiceId: string,
  createdBy: string
): Promise<Invoice> {
  const { resource: invoice } = await containers.documents()
    .item(invoiceId, companyId)
    .read<Invoice>();

  if (!invoice) throw new GLError("NOT_FOUND", "Invoice not found");
  if (invoice.status !== "draft") throw new GLError("NOT_DRAFT", "Only draft invoices can be posted");

  // Build GL journal lines ΓÇö try rule engine first, fall back to hardcoded
  const ruleType = invoice.type === "sales" ? "sales-invoice" as const : "purchase-invoice" as const;
  const rule = await getActiveRule("LV", ruleType);
  let journalLines: JournalLine[];
  if (rule) {
    const ruleResult = evaluateInvoiceRule(rule, invoice);
    journalLines = ruleResult ?? buildInvoiceJournalLines(invoice);
  } else {
    journalLines = buildInvoiceJournalLines(invoice);
  }

  // Post journal entry
  const journalEntry = await postJournalEntry({
    companyId,
    date: invoice.date,
    description: `${invoice.type === "sales" ? "Sales" : "Purchase"} invoice ${invoice.invoiceNumber} ΓÇö ${invoice.contactName}`,
    lines: journalLines,
    sourceType: "invoice",
    sourceId: invoiceId,
    createdBy,
  });

  // Update invoice status
  invoice.status = "posted";
  invoice.journalEntryId = journalEntry.id;
  invoice.updatedAt = new Date().toISOString();
  await containers.documents().item(invoiceId, companyId).replace(invoice);

  await emitEvent({
    companyId,
    type: "invoice.posted",
    actor: createdBy,
    documentType: "invoice",
    documentId: invoiceId,
    journalEntryId: journalEntry.id,
    data: { invoiceNumber: invoice.invoiceNumber, type: invoice.type, total: invoice.total },
  });

  return invoice;
}

// ΓöÇΓöÇΓöÇ Build GL lines for invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function buildInvoiceJournalLines(invoice: Invoice): JournalLine[] {
  const lines: JournalLine[] = [];

  if (invoice.type === "sales") {
    // Debit: Accounts Receivable (2210) for total
    lines.push({
      accountCode: "2210",
      accountName: "Accounts receivable",
      debit: invoice.total,
      credit: 0,
      description: `AR ΓÇö ${invoice.contactName}`,
      contactId: invoice.contactId,
    });

    // Credit: Revenue accounts per line (skip zero-amount lines)
    for (const invLine of invoice.lines) {
      const net = roundCurrency(invLine.quantity * invLine.unitPrice);
      if (net === 0) continue;
      lines.push({
        accountCode: invLine.accountCode,
        accountName: invLine.description,
        debit: 0,
        credit: net,
        description: invLine.description,
        contactId: invoice.contactId,
        itemId: invLine.itemId,
        taxCode: invLine.vatRate > 0 ? `LV-${invLine.vatRate}` : undefined,
      });
    }

    // Credit: VAT payable (4230) for total VAT
    if (invoice.vatAmount > 0) {
      lines.push({
        accountCode: "4230",
        accountName: "VAT payable",
        debit: 0,
        credit: invoice.vatAmount,
        description: "Output VAT",
        vatCode: "output",
        contactId: invoice.contactId,
        taxCode: `LV-${invoice.lines[0]?.vatRate ?? 21}`,
        taxAmount: invoice.vatAmount,
      });
    }
  } else {
    // Purchase invoice
    // Credit: Trade payables (4220) for total
    lines.push({
      accountCode: "4220",
      accountName: "Trade payables",
      debit: 0,
      credit: invoice.total,
      description: `AP ΓÇö ${invoice.contactName}`,
      contactId: invoice.contactId,
    });

    // Debit: Expense/asset accounts per line (skip zero-amount lines)
    for (const invLine of invoice.lines) {
      const net = roundCurrency(invLine.quantity * invLine.unitPrice);
      if (net === 0) continue;
      lines.push({
        accountCode: invLine.accountCode,
        accountName: invLine.description,
        debit: net,
        credit: 0,
        description: invLine.description,
        contactId: invoice.contactId,
        itemId: invLine.itemId,
        taxCode: invLine.vatRate > 0 ? `LV-${invLine.vatRate}` : undefined,
      });
    }

    // Debit: VAT receivable (2310) for total VAT
    if (invoice.vatAmount > 0) {
      lines.push({
        accountCode: "2310",
        accountName: "VAT receivable",
        debit: invoice.vatAmount,
        credit: 0,
        description: "Input VAT",
        vatCode: "input",
        contactId: invoice.contactId,
        taxCode: `LV-${invoice.lines[0]?.vatRate ?? 21}`,
        taxAmount: invoice.vatAmount,
      });
    }
  }

  return lines;
}

// ΓöÇΓöÇΓöÇ Get invoices ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function getInvoice(companyId: string, invoiceId: string): Promise<Invoice | null> {
  try {
    const { resource } = await containers.documents()
      .item(invoiceId, companyId)
      .read<Invoice>();
    return resource ?? null;
  } catch {
    return null;
  }
}

export async function listInvoices(
  companyId: string,
  type?: "sales" | "purchase"
): Promise<Invoice[]> {
  const typeFilter = type ? "AND c.type = @type" : "";
  const params: { name: string; value: string }[] = [
    { name: "@cid", value: companyId },
  ];
  if (type) params.push({ name: "@type", value: type });

  const { resources } = await containers.documents().items
    .query<Invoice>({
      query: `SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'invoice' OR IS_DEFINED(c.invoiceNumber)) ${typeFilter} ORDER BY c.date DESC`,
      parameters: params,
    })
    .fetchAll();

  return resources;
}

// ΓöÇΓöÇΓöÇ Duplicate Detection ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function findDuplicateInvoice(
  companyId: string,
  contactId: string,
  vendorInvoiceNumber: string
): Promise<Invoice | null> {
  if (!vendorInvoiceNumber) return null;

  const { resources } = await containers.documents().items
    .query<Invoice>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.contactId = @contactId AND c.vendorInvoiceNumber = @vnum AND c.status != 'cancelled'",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@contactId", value: contactId },
        { name: "@vnum", value: vendorInvoiceNumber },
      ],
    })
    .fetchAll();

  return resources.length > 0 ? resources[0] : null;
}

// ΓöÇΓöÇΓöÇ Cancel Invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function cancelInvoice(
  companyId: string,
  invoiceId: string,
  reason: string,
  createdBy: string
): Promise<Invoice> {
  const { resource: invoice } = await containers.documents()
    .item(invoiceId, companyId)
    .read<Invoice>();

  if (!invoice) throw new GLError("NOT_FOUND", "Invoice not found");
  if (invoice.status === "cancelled") throw new GLError("ALREADY_CANCELLED", "Invoice is already cancelled");
  if (invoice.amountPaid > 0) throw new GLError("HAS_PAYMENTS", "Cannot cancel invoice with payments. Reverse payments first.");

  // If posted, create reversing journal entry
  if (invoice.journalEntryId && invoice.status !== "draft") {
    const { reverseJournalEntry } = await import("./ledger.js");
    const reversalEntry = await reverseJournalEntry(companyId, invoice.journalEntryId, createdBy);
    invoice.reversalJournalEntryId = reversalEntry.id;
  }

  invoice.status = "cancelled";
  invoice.updatedAt = new Date().toISOString();
  await containers.documents().item(invoiceId, companyId).replace(invoice);

  return invoice;
}

// ΓöÇΓöÇΓöÇ Get GL entries for invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function getInvoicePostings(companyId: string, invoiceId: string) {
  const { resources } = await containers.ledger().items
    .query({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.sourceId = @sid AND (c.docType = 'journal-entry' OR IS_DEFINED(c.entryNumber))",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@sid", value: invoiceId },
      ],
    })
    .fetchAll();
  return resources;
}

// ΓöÇΓöÇΓöÇ Credit Notes ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface CreateCreditNoteInput {
  companyId: string;
  originalInvoiceId: string;
  reason: string;
  lines?: Array<{
    description: string;
    quantity: number;
    unitPrice: number;
    vatRate: number;
    accountCode: string;
    itemId?: string;
  }>;
  createdBy: string;
}

export async function createCreditNote(input: CreateCreditNoteInput): Promise<Invoice> {
  const { resource: original } = await containers.documents()
    .item(input.originalInvoiceId, input.companyId)
    .read<Invoice>();

  if (!original) throw new GLError("NOT_FOUND", "Original invoice not found");
  if (original.status === "draft" || original.status === "cancelled") {
    throw new GLError("INVALID_STATUS", "Cannot create credit note for draft or cancelled invoice");
  }

  const { resource: company } = await containers.companies()
    .item(input.companyId, input.companyId)
    .read<Company>();
  if (!company) throw new GLError("COMPANY_NOT_FOUND", "Company not found");

  // Use original lines if none provided (full credit)
  const creditLines = (input.lines || original.lines.map(l => ({
    description: l.description,
    quantity: l.quantity,
    unitPrice: l.unitPrice,
    vatRate: l.vatRate,
    accountCode: l.accountCode,
    itemId: l.itemId,
  }))).map(calcLineTotals);

  const subtotal = roundCurrency(creditLines.reduce((s, l) => s + l.quantity * l.unitPrice, 0));
  const vatAmount = roundCurrency(creditLines.reduce((s, l) => s + l.vatAmount, 0));
  const total = roundCurrency(subtotal + vatAmount);

  const invoiceNumber = await getNextNumber(input.companyId, "creditNote");
  const now = new Date().toISOString();

  const creditNote: Invoice = {
    id: uuidv4(),
    docType: "invoice" as const,
    companyId: input.companyId,
    invoiceNumber,
    type: original.type,
    contactId: original.contactId,
    contactName: original.contactName,
    date: now.slice(0, 10),
    dueDate: now.slice(0, 10),
    lines: creditLines,
    subtotal: -subtotal,
    vatAmount: -vatAmount,
    total: -total,
    amountPaid: 0,
    status: "draft",
    currency: "EUR",
    documentNumber: invoiceNumber,
    documentDate: now.slice(0, 10),
    paymentJournalEntryIds: [],
    isActive: true,
    createdAt: now,
    updatedAt: now,
    createdBy: input.createdBy,
    creditNoteFor: input.originalInvoiceId,
    creditNoteReason: input.reason,
  } as Invoice & { creditNoteFor: string; creditNoteReason: string };

  await containers.documents().items.create(creditNote);

  // Auto-post the credit note (reverses the original GL entries)
  const journalLines = buildInvoiceJournalLines({
    ...creditNote,
    subtotal: Math.abs(subtotal),
    vatAmount: Math.abs(vatAmount),
    total: Math.abs(total),
    lines: creditLines,
  } as Invoice);

  // Flip all debits/credits for the credit note
  const reversedLines = journalLines.map(l => ({
    ...l,
    debit: l.credit,
    credit: l.debit,
  }));

  const journalEntry = await postJournalEntry({
    companyId: input.companyId,
    date: creditNote.date,
    description: `Credit note ${invoiceNumber} for ${original.invoiceNumber} ΓÇö ${input.reason}`,
    lines: reversedLines,
    sourceType: "adjustment",
    sourceId: creditNote.id,
    createdBy: input.createdBy,
  });

  creditNote.status = "posted";
  (creditNote as any).journalEntryId = journalEntry.id;
  creditNote.updatedAt = new Date().toISOString();
  await containers.documents().item(creditNote.id, input.companyId).replace(creditNote);

  // Update original invoice's amountPaid (credit note reduces outstanding)
  original.amountPaid = roundCurrency(original.amountPaid + total);
  if (original.amountPaid >= original.total) original.status = "paid";
  else if (original.amountPaid > 0) original.status = "partially_paid";
  original.updatedAt = new Date().toISOString();
  await containers.documents().item(original.id, input.companyId).replace(original);

  await emitEvent({
    companyId: input.companyId,
    type: "creditnote.posted",
    actor: input.createdBy,
    documentType: "invoice",
    documentId: creditNote.id,
    journalEntryId: journalEntry.id,
    data: { creditNoteNumber: invoiceNumber, originalInvoice: original.invoiceNumber, total: -total, reason: input.reason },
  });

  return creditNote;
}

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import { emitEvent } from "./events.js";
import type { JournalEntry, JournalLine, Account } from "@shared/types";

// ΓöÇΓöÇΓöÇ Validation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export class GLError extends Error {
  constructor(public code: string, message: string) {
    super(message);
    this.name = "GLError";
  }
}

function validateEntry(entry: { lines: JournalLine[]; date: string; description: string }) {
  if (!entry.lines || entry.lines.length < 2) {
    throw new GLError("MIN_LINES", "Journal entry must have at least 2 lines");
  }
  if (!entry.date) {
    throw new GLError("MISSING_DATE", "Journal entry must have a date");
  }
  if (!entry.description?.trim()) {
    throw new GLError("MISSING_DESC", "Journal entry must have a description");
  }

  const totalDebit = roundCurrency(entry.lines.reduce((sum, l) => sum + l.debit, 0));
  const totalCredit = roundCurrency(entry.lines.reduce((sum, l) => sum + l.credit, 0));

  if (totalDebit !== totalCredit) {
    throw new GLError(
      "UNBALANCED",
      `Debits (${totalDebit}) must equal credits (${totalCredit})`
    );
  }
  if (totalDebit === 0) {
    throw new GLError("ZERO_ENTRY", "Journal entry total must be greater than zero");
  }

  for (const line of entry.lines) {
    if (line.debit < 0 || line.credit < 0) {
      throw new GLError("NEGATIVE_AMOUNT", "Amounts must be non-negative");
    }
    if (line.debit > 0 && line.credit > 0) {
      throw new GLError("BOTH_SIDES", "A line cannot have both debit and credit");
    }
    if (line.debit === 0 && line.credit === 0) {
      throw new GLError("ZERO_LINE", "A line must have either a debit or credit amount");
    }
    if (!line.accountCode) {
      throw new GLError("MISSING_ACCOUNT", "Each line must reference an account code");
    }
  }
}

function roundCurrency(n: number): number {
  return Math.round(n * 100) / 100;
}

// ΓöÇΓöÇΓöÇ Generate entry number ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function nextEntryNumber(companyId: string, period: string): Promise<string> {
  const { resources } = await containers.ledger().items
    .query<{ entryNumber: string }>({
      query: "SELECT c.entryNumber FROM c WHERE c.companyId = @cid AND c.period = @period AND (c.docType = 'journal-entry' OR IS_DEFINED(c.entryNumber)) ORDER BY c.entryNumber DESC OFFSET 0 LIMIT 1",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@period", value: period },
      ],
    })
    .fetchAll();

  if (resources.length === 0) {
    return `${period}-0001`;
  }
  const lastNum = parseInt(resources[0].entryNumber.split("-").pop()!, 10);
  return `${period}-${String(lastNum + 1).padStart(4, "0")}`;
}

// ΓöÇΓöÇΓöÇ Post journal entry ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface PostEntryInput {
  companyId: string;
  date: string;
  description: string;
  lines: JournalLine[];
  sourceType?: JournalEntry["sourceType"];
  sourceId?: string;
  createdBy: string;
}

export async function postJournalEntry(input: PostEntryInput): Promise<JournalEntry> {
  validateEntry(input);

  const period = input.date.slice(0, 7); // "2026-03"
  const entryNumber = await nextEntryNumber(input.companyId, period);
  const now = new Date().toISOString();

  const totalDebit = roundCurrency(input.lines.reduce((sum, l) => sum + l.debit, 0));
  const totalCredit = roundCurrency(input.lines.reduce((sum, l) => sum + l.credit, 0));

  const entry: JournalEntry = {
    id: uuidv4(),
    docType: "journal-entry" as const,
    companyId: input.companyId,
    entryNumber,
    date: input.date,
    description: input.description,
    lines: input.lines,
    status: "posted",
    period,
    sourceType: input.sourceType || "manual",
    sourceId: input.sourceId,
    totalDebit,
    totalCredit,
    isActive: true,
    createdAt: now,
    updatedAt: now,
    createdBy: input.createdBy,
  };

  // Save journal entry
  await containers.ledger().items.create(entry);

  // Update account balances
  await updateAccountBalances(input.companyId, input.lines);

  // Emit event
  await emitEvent({
    companyId: input.companyId,
    type: "entry.posted",
    actor: input.createdBy,
    documentType: "journal-entry",
    documentId: entry.id,
    journalEntryId: entry.id,
    data: { entryNumber: entry.entryNumber, sourceType: entry.sourceType, totalDebit: entry.totalDebit },
  });

  return entry;
}

// ΓöÇΓöÇΓöÇ Update account balances ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function updateAccountBalances(companyId: string, lines: JournalLine[]) {
  // Group by account code (a single entry might have multiple lines for the same account)
  const deltas = new Map<string, number>();
  for (const line of lines) {
    const current = deltas.get(line.accountCode) || 0;
    deltas.set(line.accountCode, current + line.debit - line.credit);
  }

  for (const [accountCode, delta] of deltas) {
    const accountId = `${companyId}-acct-${accountCode}`;
    try {
      const { resource: account, etag } = await containers.ledger()
        .item(accountId, companyId)
        .read<Account>();

      if (account) {
        // For accounts with credit normal side, flip the sign
        const signedDelta = account.normalSide === "credit" ? -delta : delta;
        account.balance = roundCurrency(account.balance + signedDelta);
        account.updatedAt = new Date().toISOString();
        await containers.ledger().item(accountId, companyId).replace(account, {
          accessCondition: { type: "IfMatch", condition: etag! },
        });
      }
    } catch {
      // Account not found or etag conflict ΓÇö skip (validation should catch this upstream)
    }
  }
}

// ΓöÇΓöÇΓöÇ Reverse journal entry ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function reverseJournalEntry(
  companyId: string,
  entryId: string,
  createdBy: string
): Promise<JournalEntry> {
  const { resource: original } = await containers.ledger()
    .item(entryId, companyId)
    .read<JournalEntry>();

  if (!original) throw new GLError("NOT_FOUND", "Journal entry not found");
  if (original.status === "reversed") throw new GLError("ALREADY_REVERSED", "Entry already reversed");

  // Mark original as reversed
  original.status = "reversed";
  original.updatedAt = new Date().toISOString();
  await containers.ledger().item(entryId, companyId).replace(original);

  // Emit reversal event
  await emitEvent({
    companyId,
    type: "entry.reversed",
    actor: createdBy,
    documentType: "journal-entry",
    documentId: entryId,
    journalEntryId: entryId,
    data: { entryNumber: original.entryNumber },
  });

  // Create reversing entry with flipped debits/credits
  const reversedLines: JournalLine[] = original.lines.map((l) => ({
    ...l,
    debit: l.credit,
    credit: l.debit,
  }));

  return postJournalEntry({
    companyId,
    date: new Date().toISOString().slice(0, 10),
    description: `Reversal of ${original.entryNumber}: ${original.description}`,
    lines: reversedLines,
    sourceType: "adjustment",
    sourceId: entryId,
    createdBy,
  });
}

// ΓöÇΓöÇΓöÇ Trial Balance ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface TrialBalanceLine {
  accountCode: string;
  accountName: string;
  accountType: string;
  openingBalance: number;
  periodDebit: number;
  periodCredit: number;
  closingBalance: number;
}

export async function getTrialBalance(companyId: string, from?: string, to?: string): Promise<{
  lines: TrialBalanceLine[];
  periodStart: string;
  periodEnd: string;
  totalOpeningBalance: number;
  totalPeriodDebit: number;
  totalPeriodCredit: number;
  totalClosingBalance: number;
}> {
  const periodStart = from || `${new Date().getFullYear()}-01-01`;
  const periodEnd = to || new Date().toISOString().slice(0, 10);

  // Get all postable accounts
  const { resources: accounts } = await containers.ledger().items
    .query<Account>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'account' OR (IS_DEFINED(c.code) AND IS_DEFINED(c.normalSide))) AND (c.isPostable = true OR c.isPostable = false) ORDER BY c.code",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  // Get all posted journal entries
  const { resources: allEntries } = await containers.ledger().items
    .query<any>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'journal-entry' OR IS_DEFINED(c.entryNumber)) AND c.status = 'posted'",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  // Calculate opening balances (entries before period start) and period movements
  const openingDebits = new Map<string, number>();
  const openingCredits = new Map<string, number>();
  const periodDebits = new Map<string, number>();
  const periodCredits = new Map<string, number>();

  for (const entry of allEntries) {
    const isBefore = entry.date < periodStart;
    const isInPeriod = entry.date >= periodStart && entry.date <= periodEnd;

    for (const line of (entry.lines || [])) {
      const code = line.accountCode;
      if (!code) continue;

      if (isBefore) {
        openingDebits.set(code, (openingDebits.get(code) || 0) + (line.debit || 0));
        openingCredits.set(code, (openingCredits.get(code) || 0) + (line.credit || 0));
      } else if (isInPeriod) {
        periodDebits.set(code, (periodDebits.get(code) || 0) + (line.debit || 0));
        periodCredits.set(code, (periodCredits.get(code) || 0) + (line.credit || 0));
      }
    }
  }

  const lines: TrialBalanceLine[] = [];
  let totalOpeningBalance = 0;
  let totalPeriodDebit = 0;
  let totalPeriodCredit = 0;
  let totalClosingBalance = 0;

  for (const account of accounts) {
    const od = roundCurrency(openingDebits.get(account.code) || 0);
    const oc = roundCurrency(openingCredits.get(account.code) || 0);
    const pd = roundCurrency(periodDebits.get(account.code) || 0);
    const pc = roundCurrency(periodCredits.get(account.code) || 0);

    // Opening balance: net of all entries before period
    const openingNet = account.normalSide === "credit" ? (oc - od) : (od - oc);
    const periodNet = account.normalSide === "credit" ? (pc - pd) : (pd - pc);
    const closingBalance = roundCurrency(openingNet + periodNet);

    // Skip accounts with no activity and no balance
    if (od === 0 && oc === 0 && pd === 0 && pc === 0) continue;

    lines.push({
      accountCode: account.code,
      accountName: account.name,
      accountType: account.type,
      openingBalance: roundCurrency(openingNet),
      periodDebit: pd,
      periodCredit: pc,
      closingBalance,
    });

    totalOpeningBalance += openingNet;
    totalPeriodDebit += pd;
    totalPeriodCredit += pc;
    totalClosingBalance += closingBalance;
  }

  return {
    lines,
    periodStart,
    periodEnd,
    totalOpeningBalance: roundCurrency(totalOpeningBalance),
    totalPeriodDebit: roundCurrency(totalPeriodDebit),
    totalPeriodCredit: roundCurrency(totalPeriodCredit),
    totalClosingBalance: roundCurrency(totalClosingBalance),
  };
}

// ΓöÇΓöÇΓöÇ Account balance query ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function getAccountBalance(companyId: string, accountCode: string): Promise<number> {
  const accountId = `${companyId}-acct-${accountCode}`;
  try {
    const { resource } = await containers.ledger()
      .item(accountId, companyId)
      .read<Account>();
    return resource?.balance ?? 0;
  } catch {
    return 0;
  }
}

// Period management & year-end close
// Handles fiscal period locking and year-end closing journals

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import { postJournalEntry, GLError } from "./ledger.js";
import { emitEvent } from "./events.js";
import type { Account, JournalLine } from "@shared/types";

function roundCurrency(n: number): number {
  return Math.round(n * 100) / 100;
}

// ΓöÇΓöÇΓöÇ Fiscal Period Management ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface FiscalPeriod {
  id: string;
  companyId: string;
  period: string;           // "2026-03"
  year: number;
  month: number;
  status: "open" | "closed" | "on-hold";
  closedAt?: string;
  closedBy?: string;
}

export async function getPeriodStatus(companyId: string, period: string): Promise<FiscalPeriod | null> {
  try {
    const { resources } = await containers.ledger().items
      .query<FiscalPeriod>({
        query: "SELECT * FROM c WHERE c.companyId = @cid AND c.period = @period AND (c.docType = 'fiscal-period' OR (IS_DEFINED(c.status) AND IS_DEFINED(c.period) AND NOT IS_DEFINED(c.entryNumber) AND NOT IS_DEFINED(c.code)))",
        parameters: [
          { name: "@cid", value: companyId },
          { name: "@period", value: period },
        ],
      })
      .fetchAll();
    return resources[0] ?? null;
  } catch {
    return null;
  }
}

export async function closePeriod(companyId: string, period: string, closedBy: string): Promise<FiscalPeriod> {
  let fp = await getPeriodStatus(companyId, period);
  const now = new Date().toISOString();

  if (fp) {
    if (fp.status === "closed") throw new GLError("ALREADY_CLOSED", `Period ${period} is already closed`);
    fp.status = "closed";
    fp.closedAt = now;
    fp.closedBy = closedBy;
    await containers.ledger().item(fp.id, companyId).replace(fp);
  } else {
    const [y, m] = period.split("-").map(Number);
    fp = {
      id: `${companyId}-period-${period}`,
      companyId,
      period,
      year: y,
      month: m,
      status: "closed",
      closedAt: now,
      closedBy,
    };
    await containers.ledger().items.create(fp);
  }

  await emitEvent({
    companyId,
    type: "period.closed",
    actor: closedBy,
    data: { period },
  });

  return fp;
}

export async function reopenPeriod(companyId: string, period: string, openedBy: string): Promise<FiscalPeriod> {
  const fp = await getPeriodStatus(companyId, period);
  if (!fp) throw new GLError("NOT_FOUND", `Period ${period} not found`);
  if (fp.status === "open") throw new GLError("ALREADY_OPEN", `Period ${period} is already open`);

  fp.status = "open";
  fp.closedAt = undefined;
  fp.closedBy = undefined;
  await containers.ledger().item(fp.id, companyId).replace(fp);

  await emitEvent({
    companyId,
    type: "period.reopened",
    actor: openedBy,
    data: { period },
  });

  return fp;
}

// ΓöÇΓöÇΓöÇ Year-End Close ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function yearEndClose(
  companyId: string,
  fiscalYear: number,
  createdBy: string
): Promise<{ closingEntry: any; periodsClosedCount: number }> {
  // 1. Get all revenue and expense accounts with balances
  const { resources: accounts } = await containers.ledger().items
    .query<Account>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'account' OR (IS_DEFINED(c.code) AND IS_DEFINED(c.normalSide))) AND c.isPostable = true AND c.balance != 0 AND (c.type = 'revenue' OR c.type = 'expense')",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  if (accounts.length === 0) {
    throw new GLError("NO_BALANCES", "No revenue or expense balances to close");
  }

  // 2. Build closing journal lines ΓÇö zero out each revenue/expense account
  const lines: JournalLine[] = [];
  let netResult = 0;

  for (const acct of accounts) {
    const balance = acct.balance;
    if (balance === 0) continue;

    // Revenue accounts (credit-normal): debit to zero out
    // Expense accounts (debit-normal): credit to zero out
    if (acct.type === "revenue") {
      lines.push({
        accountCode: acct.code,
        accountName: acct.name,
        debit: Math.abs(balance),
        credit: 0,
        description: `Year-end close ΓÇö ${acct.name}`,
      });
      netResult += Math.abs(balance); // Revenue is positive
    } else {
      lines.push({
        accountCode: acct.code,
        accountName: acct.name,
        debit: 0,
        credit: Math.abs(balance),
        description: `Year-end close ΓÇö ${acct.name}`,
      });
      netResult -= Math.abs(balance); // Expenses reduce result
    }
  }

  // 3. Transfer net result to retained earnings (3310)
  const retainedEarningsCode = "3310";
  if (netResult > 0) {
    // Profit ΓÇö credit retained earnings
    lines.push({
      accountCode: retainedEarningsCode,
      accountName: "Retained earnings prior years",
      debit: 0,
      credit: roundCurrency(netResult),
      description: `FY${fiscalYear} net profit transferred`,
    });
  } else if (netResult < 0) {
    // Loss ΓÇö debit retained earnings
    lines.push({
      accountCode: retainedEarningsCode,
      accountName: "Retained earnings prior years",
      debit: roundCurrency(Math.abs(netResult)),
      credit: 0,
      description: `FY${fiscalYear} net loss transferred`,
    });
  }

  // 4. Post closing journal entry
  const lastDay = `${fiscalYear}-12-31`;
  const closingEntry = await postJournalEntry({
    companyId,
    date: lastDay,
    description: `Year-end closing ΓÇö FY${fiscalYear}`,
    lines,
    sourceType: "closing",
    createdBy,
  });

  // 5. Close all periods for the fiscal year
  let periodsClosedCount = 0;
  for (let m = 1; m <= 12; m++) {
    const period = `${fiscalYear}-${String(m).padStart(2, "0")}`;
    try {
      await closePeriod(companyId, period, createdBy);
      periodsClosedCount++;
    } catch {
      // Already closed ΓÇö skip
    }
  }

  await emitEvent({
    companyId,
    type: "year-end.closed",
    actor: createdBy,
    journalEntryId: closingEntry.id,
    data: { fiscalYear, netResult: roundCurrency(netResult), periodsClosedCount },
  });

  return { closingEntry, periodsClosedCount };
}

// Posting Rule Engine ΓÇö evaluates country-specific rules to produce GL journal lines
// Falls back gracefully: if no rule is found, callers use hardcoded logic

import { containers } from "./cosmos.js";
import type { PostingRule, PostingRuleLine, JournalLine, Invoice, Payment } from "@shared/types";

// ΓöÇΓöÇΓöÇ Fetch active rule ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function getActiveRule(
  country: string,
  documentType: PostingRule["documentType"]
): Promise<PostingRule | null> {
  const today = new Date().toISOString().slice(0, 10);
  try {
    const { resources } = await containers.rules().items
      .query<PostingRule>({
        query: `SELECT * FROM c WHERE c.country = @country AND c.documentType = @docType AND c.isActive = true AND c.effectiveFrom <= @today AND (NOT IS_DEFINED(c.effectiveTo) OR c.effectiveTo = null OR c.effectiveTo >= @today) ORDER BY c.version DESC OFFSET 0 LIMIT 1`,
        parameters: [
          { name: "@country", value: country },
          { name: "@docType", value: documentType },
          { name: "@today", value: today },
        ],
      })
      .fetchAll();
    return resources[0] ?? null;
  } catch {
    return null;
  }
}

// ΓöÇΓöÇΓöÇ Evaluate rule against a document ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface InvoiceContext {
  type: "invoice";
  invoice: Invoice;
}

interface PaymentContext {
  type: "payment";
  payment: Payment;
}

type DocumentContext = InvoiceContext | PaymentContext;

function resolveAmount(expr: string, ctx: DocumentContext): number {
  if (ctx.type === "invoice") {
    const inv = ctx.invoice;
    switch (expr) {
      case "invoice.total": return inv.total;
      case "invoice.subtotal": return inv.subtotal;
      case "invoice.vatAmount": return inv.vatAmount;
      default: return 0;
    }
  }
  if (ctx.type === "payment") {
    const pmt = ctx.payment;
    switch (expr) {
      case "payment.amount": return pmt.amount;
      default: return 0;
    }
  }
  return 0;
}

function resolveLineAmount(expr: string, invLine: { quantity: number; unitPrice: number; vatAmount: number; vatRate: number }): number {
  const net = Math.round(invLine.quantity * invLine.unitPrice * 100) / 100;
  switch (expr) {
    case "line.netAmount": return net;
    case "line.vatAmount": return invLine.vatAmount;
    case "line.total": return Math.round((net + invLine.vatAmount) * 100) / 100;
    default: return 0;
  }
}

export function evaluateInvoiceRule(rule: PostingRule, invoice: Invoice): JournalLine[] | null {
  const ctx: InvoiceContext = { type: "invoice", invoice };
  const journalLines: JournalLine[] = [];

  for (const rl of rule.lines) {
    // Check if this rule line uses per-invoice-line expansion
    if (rl.amountExpr.startsWith("line.")) {
      // Expand per invoice line
      for (const invLine of invoice.lines) {
        const amount = resolveLineAmount(rl.amountExpr, invLine);
        if (amount === 0) continue;
        journalLines.push({
          accountCode: rl.accountCode === "{{line.accountCode}}" ? invLine.accountCode : rl.accountCode,
          accountName: rl.accountCode === "{{line.accountCode}}" ? invLine.description : rl.accountName,
          debit: rl.side === "debit" ? amount : 0,
          credit: rl.side === "credit" ? amount : 0,
          description: rl.description || invLine.description,
          contactId: invoice.contactId,
          itemId: invLine.itemId,
          taxCode: rl.taxCode,
          taxAmount: rl.amountExpr === "line.vatAmount" ? amount : undefined,
          vatCode: rl.taxCode?.includes("output") ? "output" : rl.taxCode?.includes("input") ? "input" : undefined,
        });
      }
    } else {
      // Document-level amount
      const amount = resolveAmount(rl.amountExpr, ctx);
      if (amount === 0) continue;
      journalLines.push({
        accountCode: rl.accountCode,
        accountName: rl.accountName,
        debit: rl.side === "debit" ? amount : 0,
        credit: rl.side === "credit" ? amount : 0,
        description: rl.description || rule.name,
        contactId: invoice.contactId,
        taxCode: rl.taxCode,
        taxAmount: rl.amountExpr.includes("vat") || rl.amountExpr.includes("Vat") ? amount : undefined,
        vatCode: rl.taxCode?.includes("output") ? "output" : rl.taxCode?.includes("input") ? "input" : undefined,
      });
    }
  }

  // Validate: debits must equal credits
  const totalDebit = Math.round(journalLines.reduce((s, l) => s + l.debit, 0) * 100) / 100;
  const totalCredit = Math.round(journalLines.reduce((s, l) => s + l.credit, 0) * 100) / 100;
  if (totalDebit !== totalCredit || totalDebit === 0) {
    return null; // Rule produced invalid output ΓÇö fall back to hardcoded
  }

  return journalLines;
}

export function evaluatePaymentRule(rule: PostingRule, payment: Payment): JournalLine[] | null {
  const ctx: PaymentContext = { type: "payment", payment };
  const journalLines: JournalLine[] = [];

  for (const rl of rule.lines) {
    const amount = resolveAmount(rl.amountExpr, ctx);
    if (amount === 0) continue;
    journalLines.push({
      accountCode: rl.accountCode,
      accountName: rl.accountName,
      debit: rl.side === "debit" ? amount : 0,
      credit: rl.side === "credit" ? amount : 0,
      description: rl.description || rule.name,
      contactId: payment.contactId,
    });
  }

  const totalDebit = Math.round(journalLines.reduce((s, l) => s + l.debit, 0) * 100) / 100;
  const totalCredit = Math.round(journalLines.reduce((s, l) => s + l.credit, 0) * 100) / 100;
  if (totalDebit !== totalCredit || totalDebit === 0) {
    return null;
  }

  return journalLines;
}

// ΓöÇΓöÇΓöÇ Seed rules from TypeScript definitions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function seedRules(rules: PostingRule[]): Promise<number> {
  let count = 0;
  for (const rule of rules) {
    try {
      // Check if rule already exists by country + documentType + version
      const { resources } = await containers.rules().items
        .query<PostingRule>({
          query: "SELECT c.id FROM c WHERE c.country = @country AND c.documentType = @docType AND c.version = @version",
          parameters: [
            { name: "@country", value: rule.country },
            { name: "@docType", value: rule.documentType },
            { name: "@version", value: rule.version },
          ],
        })
        .fetchAll();

      if (resources.length === 0) {
        await containers.rules().items.create(rule);
        count++;
      }
    } catch {
      // Skip duplicates
    }
  }
  return count;
}

// Recurring journal entry templates
// Save, list, and execute recurring entries

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import { postJournalEntry } from "./ledger.js";
import { emitEvent } from "./events.js";
import type { JournalLine, JournalEntry } from "@shared/types";

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface RecurringTemplate {
  id: string;
  companyId: string;
  name: string;
  description: string;
  lines: JournalLine[];
  frequency: "monthly" | "quarterly" | "yearly";
  nextRunDate?: string;
  lastRunDate?: string;
  isActive: boolean;
  createdAt: string;
  createdBy: string;
}

// ΓöÇΓöÇΓöÇ CRUD ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function createRecurringTemplate(input: {
  companyId: string;
  name: string;
  description: string;
  lines: JournalLine[];
  frequency: RecurringTemplate["frequency"];
  nextRunDate?: string;
  createdBy: string;
}): Promise<RecurringTemplate> {
  const now = new Date().toISOString();
  const template: RecurringTemplate = {
    id: uuidv4(),
    companyId: input.companyId,
    docType: "recurring-template" as any,
    name: input.name,
    description: input.description,
    lines: input.lines,
    frequency: input.frequency,
    nextRunDate: input.nextRunDate,
    isActive: true,
    createdAt: now,
    createdBy: input.createdBy,
  };
  await containers.documents().items.create(template);
  return template;
}

export async function listRecurringTemplates(companyId: string): Promise<RecurringTemplate[]> {
  const { resources } = await containers.documents().items
    .query<RecurringTemplate>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND c.docType = 'recurring-template' ORDER BY c.name",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();
  return resources;
}

// ΓöÇΓöÇΓöÇ Execute Template ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function executeRecurringTemplate(
  companyId: string,
  templateId: string,
  date: string,
  createdBy: string
): Promise<JournalEntry> {
  const { resource: template } = await containers.documents()
    .item(templateId, companyId).read<RecurringTemplate>();

  if (!template) throw new Error("Template not found");
  if (!template.isActive) throw new Error("Template is inactive");

  const entry = await postJournalEntry({
    companyId,
    date,
    description: `${template.name} ΓÇö recurring`,
    lines: template.lines,
    sourceType: "manual",
    sourceId: templateId,
    createdBy,
  });

  // Update last/next run dates
  template.lastRunDate = date;
  const next = new Date(date);
  if (template.frequency === "monthly") next.setMonth(next.getMonth() + 1);
  else if (template.frequency === "quarterly") next.setMonth(next.getMonth() + 3);
  else next.setFullYear(next.getFullYear() + 1);
  template.nextRunDate = next.toISOString().slice(0, 10);
  await containers.documents().item(templateId, companyId).replace(template);

  await emitEvent({
    companyId,
    type: "recurring.executed",
    actor: createdBy,
    documentType: "journal-entry",
    documentId: entry.id,
    data: { templateName: template.name, templateId },
  });

  return entry;
}

import { v4 as uuidv4 } from "uuid";
import { containers } from "./cosmos.js";
import type { VatReturn, VatReturnLine, Invoice, Account, JournalEntry } from "@shared/types";

function roundCurrency(n: number): number {
  return Math.round(n * 100) / 100;
}

// ΓöÇΓöÇΓöÇ Generate VAT Return ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function generateVatReturn(
  companyId: string,
  year: number,
  month: number,
  createdBy: string
): Promise<VatReturn> {
  const period = `${year}-${String(month).padStart(2, "0")}`;
  const startDate = `${period}-01`;
  const lastDay = new Date(year, month, 0).getDate();
  const endDate = `${period}-${lastDay}`;

  // Get all posted invoices in this period
  const { resources: invoices } = await containers.documents().items
    .query<Invoice>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'invoice' OR IS_DEFINED(c.invoiceNumber)) AND c.status != 'draft' AND c.status != 'cancelled' AND c.date >= @start AND c.date <= @end",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@start", value: startDate },
        { name: "@end", value: endDate },
      ],
    })
    .fetchAll();

  // Aggregate by VAT rate and type
  const vatMap = new Map<string, VatReturnLine>();

  for (const inv of invoices) {
    for (const line of inv.lines) {
      const type = inv.type === "sales" ? "output" : "input";
      const key = `${type}-${line.vatRate}`;
      const existing = vatMap.get(key);
      const net = roundCurrency(line.quantity * line.unitPrice);

      if (existing) {
        existing.taxableAmount = roundCurrency(existing.taxableAmount + net);
        existing.vatAmount = roundCurrency(existing.vatAmount + line.vatAmount);
      } else {
        vatMap.set(key, {
          vatRate: line.vatRate,
          taxableAmount: net,
          vatAmount: line.vatAmount,
          type,
        });
      }
    }
  }

  const lines = Array.from(vatMap.values());
  const outputVat = roundCurrency(
    lines.filter((l) => l.type === "output").reduce((s, l) => s + l.vatAmount, 0)
  );
  const inputVat = roundCurrency(
    lines.filter((l) => l.type === "input").reduce((s, l) => s + l.vatAmount, 0)
  );

  const now = new Date().toISOString();
  const vatReturn: VatReturn = {
    id: uuidv4(),
    docType: "vat-return" as const,
    companyId,
    period,
    startDate,
    endDate,
    outputVat,
    inputVat,
    vatPayable: roundCurrency(outputVat - inputVat),
    status: "draft",
    lines,
    isActive: true,
    createdAt: now,
    updatedAt: now,
    createdBy,
  };

  await containers.documents().items.create(vatReturn);
  return vatReturn;
}

// ΓöÇΓöÇΓöÇ Financial Statements ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface BalanceSheetReport {
  date: string;
  assets: { code: string; name: string; balance: number }[];
  liabilities: { code: string; name: string; balance: number }[];
  equity: { code: string; name: string; balance: number }[];
  totalAssets: number;
  totalLiabilities: number;
  totalEquity: number;
}

export interface ProfitLossReport {
  periodStart: string;
  periodEnd: string;
  revenue: { code: string; name: string; amount: number }[];
  expenses: { code: string; name: string; amount: number }[];
  totalRevenue: number;
  totalExpenses: number;
  netProfit: number;
}

export async function getBalanceSheet(companyId: string): Promise<BalanceSheetReport> {
  const { resources: accounts } = await containers.ledger().items
    .query<Account>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'account' OR (IS_DEFINED(c.code) AND IS_DEFINED(c.normalSide))) AND c.isPostable = true AND c.balance != 0 ORDER BY c.code",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  const assets = accounts
    .filter((a) => a.type === "asset")
    .map((a) => ({ code: a.code, name: a.name, balance: Math.abs(a.balance) }));
  const liabilities = accounts
    .filter((a) => a.type === "liability")
    .map((a) => ({ code: a.code, name: a.name, balance: Math.abs(a.balance) }));
  const equity = accounts
    .filter((a) => a.type === "equity")
    .map((a) => ({ code: a.code, name: a.name, balance: Math.abs(a.balance) }));

  // Add current year P&L to equity
  const revenueTotal = accounts
    .filter((a) => a.type === "revenue")
    .reduce((s, a) => s + Math.abs(a.balance), 0);
  const expenseTotal = accounts
    .filter((a) => a.type === "expense")
    .reduce((s, a) => s + Math.abs(a.balance), 0);
  const currentYearResult = roundCurrency(revenueTotal - expenseTotal);

  if (currentYearResult !== 0) {
    equity.push({ code: "3320", name: "Current year result", balance: currentYearResult });
  }

  return {
    date: new Date().toISOString().slice(0, 10),
    assets,
    liabilities,
    equity,
    totalAssets: roundCurrency(assets.reduce((s, a) => s + a.balance, 0)),
    totalLiabilities: roundCurrency(liabilities.reduce((s, a) => s + a.balance, 0)),
    totalEquity: roundCurrency(equity.reduce((s, a) => s + a.balance, 0)),
  };
}

export async function getProfitAndLoss(companyId: string, from?: string, to?: string): Promise<ProfitLossReport> {
  const periodStart = from || `${new Date().getFullYear()}-01-01`;
  const periodEnd = to || new Date().toISOString().slice(0, 10);

  // Query posted journal entries within the period
  const { resources: entries } = await containers.ledger().items
    .query<any>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'journal-entry' OR IS_DEFINED(c.entryNumber)) AND c.status = 'posted' AND c.date >= @from AND c.date <= @to",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@from", value: periodStart },
        { name: "@to", value: periodEnd },
      ],
    })
    .fetchAll();

  // Aggregate by account code
  const accountTotals = new Map<string, { code: string; name: string; type: string; amount: number }>();

  for (const entry of entries) {
    for (const line of (entry.lines || [])) {
      const code = line.accountCode;
      if (!code) continue;

      // Determine if this is a revenue or expense account by code prefix
      let type = "";
      if (code.startsWith("5")) type = "revenue";
      else if (code.startsWith("6")) type = "expense";
      else continue; // skip non-P&L accounts

      const existing = accountTotals.get(code);
      const amount = type === "revenue" ? (line.credit - line.debit) : (line.debit - line.credit);

      if (existing) {
        existing.amount = roundCurrency(existing.amount + amount);
      } else {
        accountTotals.set(code, { code, name: line.accountName || code, type, amount: roundCurrency(amount) });
      }
    }
  }

  const revenue = Array.from(accountTotals.values())
    .filter((a) => a.type === "revenue" && a.amount !== 0)
    .sort((a, b) => a.code.localeCompare(b.code));
  const expenses = Array.from(accountTotals.values())
    .filter((a) => a.type === "expense" && a.amount !== 0)
    .sort((a, b) => a.code.localeCompare(b.code));

  const totalRevenue = roundCurrency(revenue.reduce((s, r) => s + r.amount, 0));
  const totalExpenses = roundCurrency(expenses.reduce((s, e) => s + e.amount, 0));

  return {
    periodStart,
    periodEnd,
    revenue,
    expenses,
    totalRevenue,
    totalExpenses,
    netProfit: roundCurrency(totalRevenue - totalExpenses),
  };
}

// ΓöÇΓöÇΓöÇ VAT Declaration Export (VID-compatible) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface VatDeclaration {
  companyName: string;
  registrationNumber: string;
  vatNumber: string;
  period: string;
  year: number;
  month: number;
  // PVN deklar─ücija fields
  outputVatStandard: number;      // 21% output VAT
  outputVatReduced: number;       // 12% output VAT
  outputVatSuperReduced: number;  // 5% output VAT
  taxableStandard: number;
  taxableReduced: number;
  taxableSuperReduced: number;
  totalOutputVat: number;
  totalInputVat: number;
  vatPayable: number;             // positive = owe VID, negative = refund
  lines: VatReturnLine[];
}

export async function generateVatDeclaration(
  companyId: string,
  year: number,
  month: number
): Promise<VatDeclaration> {
  const { resource: company } = await containers.companies()
    .item(companyId, companyId).read<any>();
  if (!company) throw new Error("Company not found");

  const period = `${year}-${String(month).padStart(2, "0")}`;
  const startDate = `${period}-01`;
  const lastDay = new Date(year, month, 0).getDate();
  const endDate = `${period}-${lastDay}`;

  const { resources: invoices } = await containers.documents().items
    .query<Invoice>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'invoice' OR IS_DEFINED(c.invoiceNumber)) AND c.status != 'draft' AND c.status != 'cancelled' AND c.date >= @start AND c.date <= @end",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@start", value: startDate },
        { name: "@end", value: endDate },
      ],
    })
    .fetchAll();

  const vatMap = new Map<string, VatReturnLine>();
  for (const inv of invoices) {
    for (const line of inv.lines) {
      const type = inv.type === "sales" ? "output" : "input";
      const key = `${type}-${line.vatRate}`;
      const net = roundCurrency(line.quantity * line.unitPrice);
      const existing = vatMap.get(key);
      if (existing) {
        existing.taxableAmount = roundCurrency(existing.taxableAmount + net);
        existing.vatAmount = roundCurrency(existing.vatAmount + line.vatAmount);
      } else {
        vatMap.set(key, { vatRate: line.vatRate, taxableAmount: net, vatAmount: line.vatAmount, type });
      }
    }
  }

  const lines = Array.from(vatMap.values());
  const get = (type: string, rate: number) => lines.find(l => l.type === type && l.vatRate === rate);

  return {
    companyName: company.name,
    registrationNumber: company.registrationNumber,
    vatNumber: company.vatNumber || "",
    period,
    year,
    month,
    taxableStandard: get("output", 21)?.taxableAmount ?? 0,
    taxableReduced: get("output", 12)?.taxableAmount ?? 0,
    taxableSuperReduced: get("output", 5)?.taxableAmount ?? 0,
    outputVatStandard: get("output", 21)?.vatAmount ?? 0,
    outputVatReduced: get("output", 12)?.vatAmount ?? 0,
    outputVatSuperReduced: get("output", 5)?.vatAmount ?? 0,
    totalOutputVat: roundCurrency(lines.filter(l => l.type === "output").reduce((s, l) => s + l.vatAmount, 0)),
    totalInputVat: roundCurrency(lines.filter(l => l.type === "input").reduce((s, l) => s + l.vatAmount, 0)),
    vatPayable: roundCurrency(
      lines.filter(l => l.type === "output").reduce((s, l) => s + l.vatAmount, 0) -
      lines.filter(l => l.type === "input").reduce((s, l) => s + l.vatAmount, 0)
    ),
    lines,
  };
}

// ΓöÇΓöÇΓöÇ Annual Financial Statements (Latvian format) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface AnnualReport {
  companyName: string;
  registrationNumber: string;
  fiscalYear: number;
  periodStart: string;
  periodEnd: string;
  balanceSheet: BalanceSheetReport;
  profitAndLoss: ProfitLossReport;
  // Latvian format groupings
  balanceSheetLv: {
    longTermAssets: number;
    currentAssets: number;
    totalAssets: number;
    equity: number;
    longTermLiabilities: number;
    currentLiabilities: number;
    totalEquityAndLiabilities: number;
  };
  profitAndLossLv: {
    netTurnover: number;
    costOfGoodsSold: number;
    grossProfit: number;
    sellingExpenses: number;
    administrativeExpenses: number;
    otherIncome: number;
    financialExpenses: number;
    profitBeforeTax: number;
    corporateIncomeTax: number;
    netProfit: number;
  };
}

export async function generateAnnualReport(companyId: string, fiscalYear: number): Promise<AnnualReport> {
  const { resource: company } = await containers.companies()
    .item(companyId, companyId).read<any>();
  if (!company) throw new Error("Company not found");

  const bs = await getBalanceSheet(companyId);
  const pl = await getProfitAndLoss(companyId);

  // Group accounts by Latvian CoA classes for annual report
  const { resources: allAccounts } = await containers.ledger().items
    .query<Account>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'account' OR (IS_DEFINED(c.code) AND IS_DEFINED(c.normalSide))) AND c.isPostable = true AND c.balance != 0 ORDER BY c.code",
      parameters: [{ name: "@cid", value: companyId }],
    })
    .fetchAll();

  const sumByCodeRange = (from: string, to: string): number =>
    roundCurrency(allAccounts.filter(a => a.code >= from && a.code <= to).reduce((s, a) => s + Math.abs(a.balance), 0));

  return {
    companyName: company.name,
    registrationNumber: company.registrationNumber,
    fiscalYear,
    periodStart: `${fiscalYear}-01-01`,
    periodEnd: `${fiscalYear}-12-31`,
    balanceSheet: bs,
    profitAndLoss: pl,
    balanceSheetLv: {
      longTermAssets: sumByCodeRange("1000", "1999"),
      currentAssets: sumByCodeRange("2000", "2999"),
      totalAssets: bs.totalAssets,
      equity: sumByCodeRange("3000", "3999") + (pl.netProfit || 0),
      longTermLiabilities: sumByCodeRange("4100", "4199"),
      currentLiabilities: sumByCodeRange("4200", "4999"),
      totalEquityAndLiabilities: bs.totalLiabilities + bs.totalEquity,
    },
    profitAndLossLv: {
      netTurnover: sumByCodeRange("5100", "5199"),
      costOfGoodsSold: sumByCodeRange("6100", "6199"),
      grossProfit: roundCurrency(sumByCodeRange("5100", "5199") - sumByCodeRange("6100", "6199")),
      sellingExpenses: sumByCodeRange("6200", "6299"),
      administrativeExpenses: sumByCodeRange("6300", "6399"),
      otherIncome: sumByCodeRange("5200", "5299"),
      financialExpenses: sumByCodeRange("6400", "6499"),
      profitBeforeTax: pl.netProfit,
      corporateIncomeTax: sumByCodeRange("6500", "6599"),
      netProfit: roundCurrency(pl.netProfit - sumByCodeRange("6500", "6599")),
    },
  };
}

// ΓöÇΓöÇΓöÇ AR/AP Aging Reports ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface AgingBucket {
  contactId: string;
  contactName: string;
  current: number;
  days30: number;
  days60: number;
  days90plus: number;
  total: number;
}

export interface AgingReport {
  type: "ar" | "ap";
  date: string;
  buckets: AgingBucket[];
  totalCurrent: number;
  totalDays30: number;
  totalDays60: number;
  totalDays90plus: number;
  grandTotal: number;
}

export async function getAgingReport(companyId: string, type: "ar" | "ap"): Promise<AgingReport> {
  // Get all posted, unpaid/partially-paid invoices
  const invType = type === "ar" ? "sales" : "purchase";
  const { resources: invoices } = await containers.documents().items
    .query<Invoice>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'invoice' OR IS_DEFINED(c.invoiceNumber)) AND c.type = @type AND (c.status = 'posted' OR c.status = 'partially_paid' OR c.status = 'overdue')",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@type", value: invType },
      ],
    })
    .fetchAll();

  const today = new Date();
  const contactMap = new Map<string, AgingBucket>();

  for (const inv of invoices) {
    const outstanding = roundCurrency(inv.total - inv.amountPaid);
    if (outstanding <= 0) continue;

    const dueDate = new Date(inv.dueDate);
    const daysOverdue = Math.floor((today.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24));

    let bucket = contactMap.get(inv.contactId);
    if (!bucket) {
      bucket = { contactId: inv.contactId, contactName: inv.contactName, current: 0, days30: 0, days60: 0, days90plus: 0, total: 0 };
      contactMap.set(inv.contactId, bucket);
    }

    if (daysOverdue <= 0) bucket.current = roundCurrency(bucket.current + outstanding);
    else if (daysOverdue <= 30) bucket.days30 = roundCurrency(bucket.days30 + outstanding);
    else if (daysOverdue <= 60) bucket.days60 = roundCurrency(bucket.days60 + outstanding);
    else bucket.days90plus = roundCurrency(bucket.days90plus + outstanding);

    bucket.total = roundCurrency(bucket.total + outstanding);
  }

  const buckets = Array.from(contactMap.values()).sort((a, b) => b.total - a.total);
  return {
    type,
    date: today.toISOString().slice(0, 10),
    buckets,
    totalCurrent: roundCurrency(buckets.reduce((s, b) => s + b.current, 0)),
    totalDays30: roundCurrency(buckets.reduce((s, b) => s + b.days30, 0)),
    totalDays60: roundCurrency(buckets.reduce((s, b) => s + b.days60, 0)),
    totalDays90plus: roundCurrency(buckets.reduce((s, b) => s + b.days90plus, 0)),
    grandTotal: roundCurrency(buckets.reduce((s, b) => s + b.total, 0)),
  };
}

// ΓöÇΓöÇΓöÇ Mark Overdue Invoices ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export async function markOverdueInvoices(companyId: string): Promise<number> {
  const today = new Date().toISOString().slice(0, 10);
  const { resources: invoices } = await containers.documents().items
    .query<Invoice>({
      query: "SELECT * FROM c WHERE c.companyId = @cid AND (c.docType = 'invoice' OR IS_DEFINED(c.invoiceNumber)) AND (c.status = 'posted' OR c.status = 'partially_paid') AND c.dueDate < @today",
      parameters: [
        { name: "@cid", value: companyId },
        { name: "@today", value: today },
      ],
    })
    .fetchAll();

  let count = 0;
  for (const inv of invoices) {
    if (inv.status !== "overdue") {
      inv.status = "overdue";
      inv.updatedAt = new Date().toISOString();
      await containers.documents().item(inv.id, companyId).replace(inv);
      count++;
    }
  }
  return count;
}

