            </div>
          </div>
        )}
      </div>
    );
  }

  // ΓöÇΓöÇΓöÇ List view ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  return (
    <div>
      <h2 className="page-title">Bank</h2>

      {/* Bank balance dashboard */}
      <div className="dashboard-grid" style={{ marginBottom: 20 }}>
        <div className="metric-card">
