        </div>
        <div className="form-hint">Paste semicolon-separated CSV with headers: date;description;reference;amount;counterparty</div>
        <textarea
          value={csvText}
          onChange={e => setCsvText(e.target.value)}
          rows={6}
          placeholder={"date;description;reference;amount;counterparty\n2026-03-01;Office rent;R-001;-1200.00;SIA Landlord\n2026-03-05;Customer payment;INV-00001;4840.00;SIA Client"}
          style={{ width: "100%", padding: 12, fontFamily: "ui-monospace, Consolas, monospace", fontSize: "var(--text-sm)", border: "1px solid var(--border)", borderRadius: "var(--radius-sm)", resize: "vertical", background: "var(--bg-page)" }}
          aria-label="Bank statement CSV"
        />
        <button className="btn-primary" style={{ marginTop: 8 }} onClick={handleImport} disabled={importing || !csvText.trim()}>
          {importing ? "Importing..." : "Import & auto-match"}
        </button>
      </div>

      {loading ? <p style={{ color: "var(--text-tertiary)" }}>Loading...</p> : recons.length === 0 ? (
        <div className="empty-state"><div className="icon">≡ƒÅª</div><h3>No reconciliations</h3><p>Import a bank statement to start reconciling.</p></div>
      ) : (
        <table className="data-table">
          <thead><tr><th>Date</th><th>Bank account</th><th>Lines</th><th style={{ textAlign: "right" }}>Statement balance</th><th>Status</th></tr></thead>
          <tbody>
            {recons.map(r => {
              const unm = r.lines?.filter(l => l.status === "unmatched").length || 0;
              return (
                <tr key={r.id} onClick={() => selectRecon(r)} style={{ cursor: "pointer" }}>
                  <td className="mono">{r.statementDate}</td>
                  <td className="mono">{r.bankAccountCode}</td>
                  <td>
                    {r.lines?.length || 0}
                    {unm > 0 && <span style={{ marginLeft: 6, fontSize: 11, color: "var(--warning)" }}>{unm} unmatched</span>}
                  </td>
                  <td className="num">{formatMoney(r.statementBalance, fmt)}</td>
                  <td><span className={badgeClass(r.status)}>{r.status}</span></td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { useLocation } from "react-router-dom";
import { useApp } from "../utils/context";
import { api } from "../utils/api";

interface Message {
  id: string;
  role: "user" | "assistant" | "system";
  content: string;
}

const API_BASE = "/api";
const AUTH_TOKEN = "dev-bypass";

// Simple markdown ΓåÆ HTML renderer (bold, newlines, numbered lists)
function FormattedMessage({ content }: { content: string }) {
  const html = content
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\n(\d+)\.\s/g, '\n<br/><span class="list-num">$1.</span> ')
    .replace(/\n-\s/g, '\n<br/>ΓÇó ')
    .replace(/\n/g, '<br/>');
  return <div dangerouslySetInnerHTML={{ __html: html }} />;
}

export function Chat() {
  const { companyId, setCompanyId, companies } = useApp();
  const activeCompany = companies.find((c) => c.id === companyId);
  const location = useLocation();
  const prefillHandled = useRef(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [historyLoaded, setHistoryLoaded] = useState(false);

  // Load chat history from server when company changes
  useEffect(() => {
    setHistoryLoaded(false);
    if (!companyId) {
      setMessages([{
        id: "1",
        role: "system",
        content: "ERA agent is ready. Ask me to create a company, invoices, record payments, or check your finances.",
      }]);
      setHistoryLoaded(true);
      return;
    }
    api.chatHistory(companyId).then((history: any[]) => {
      const systemMsg: Message = {
        id: "1",
        role: "system",
        content: "ERA agent is ready. Ask me to create a company, invoices, record payments, or check your finances.",
      };
      if (history && history.length > 0) {
        const loaded: Message[] = [systemMsg, ...history.map((m: any) => ({
          id: m.id,
          role: m.role as "user" | "assistant",
          content: m.content,
        }))];
        setMessages(loaded);
      } else {
        setMessages([systemMsg]);
      }
      setHistoryLoaded(true);
    }).catch(() => {
      setMessages([{
        id: "1",
        role: "system",
        content: "ERA agent is ready. Ask me to create a company, invoices, record payments, or check your finances.",
      }]);
      setHistoryLoaded(true);
    });
  }, [companyId]);

  // Handle prefilled message from navigation state (e.g., dashboard checklist)
  useEffect(() => {
    const state = location.state as { prefill?: string } | null;
    if (state?.prefill && !prefillHandled.current) {
      prefillHandled.current = true;
      setInput(state.prefill);
      // Clear the state so it doesn't re-trigger on re-render
      window.history.replaceState({}, "");
    }
  }, [location.state]);

  async function handleSend() {
    if (!input.trim() || loading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: "user",
      content: input.trim(),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setLoading(true);

    try {
      const history = messages
        .filter((m) => m.role !== "system")
        .map((m) => ({ role: m.role as "user" | "assistant", content: m.content }));

      const res = await fetch(`${API_BASE}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${AUTH_TOKEN}`,
        },
        body: JSON.stringify({
          companyId: companyId || undefined,
          message: userMsg.content,
          history,
        }),
      });

      const json = await res.json();
      const responseText = json.data?.response || json.error?.message || "No response from agent";

      // Try to extract companyId from response if a company was created
      if (!companyId && responseText.includes("company") && json.data?.response) {
        const match = responseText.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
        if (match) setCompanyId(match[0]);
      }

      const assistantMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: "assistant",
        content: responseText,
      };

      setMessages((prev) => [...prev, assistantMsg]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          id: (Date.now() + 1).toString(),
          role: "assistant",
          content: `Connection error: ${err instanceof Error ? err.message : "Could not reach the backend. Is it running on port 3000?"}`,
        },
      ]);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div>
      <h2 className="page-title">Agent chat</h2>
      {activeCompany && (
        <div style={{ fontSize: "12px", color: "#A0A0A0", marginBottom: 8 }}>
          {activeCompany.name}
        </div>
      )}
      <div className="chat-container">
        <div className="chat-header">ERA orchestrator agent</div>
        <div className="chat-messages">
          {messages.map((msg) => (
            <div key={msg.id} className={`chat-message ${msg.role}`}>
              <FormattedMessage content={msg.content} />
            </div>
          ))}
          {loading && (
            <div className="chat-message assistant" style={{ opacity: 0.5 }}>
              Thinking...
            </div>
          )}
        </div>
        <div className="chat-input-area">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSend()}
            placeholder="Create a company, invoice, record payment..."
            disabled={loading}
          />
          <button className="btn-primary" onClick={handleSend} disabled={loading}>
            {loading ? "..." : "Send"}
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { formatMoney, formatMoneyOr } from "../utils/format";

type ContactSortKey = "name" | "type" | "registrationNumber" | "vatNumber" | "city" | "paymentTermsDays";
type SortDir = "asc" | "desc";

export function Contacts() {
  const { companyId, numberFormat: fmt } = useApp();
  const [contacts, setContacts] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<any>(null);
  const [txns, setTxns] = useState<any>(null);
  const [loadingTxns, setLoadingTxns] = useState(false);
  const [filter, setFilter] = useState<"" | "customer" | "vendor">("");
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState<ContactSortKey>("name");
  const [sortDir, setSortDir] = useState<SortDir>("asc");

  useEffect(() => {
    if (!companyId) { setLoading(false); return; }
    api.contacts(companyId).then((data: any) => { setContacts(data); setLoading(false); }).catch(() => setLoading(false));
  }, [companyId]);

  async function handleSelect(c: any) {
    setSelected(c);
    setLoadingTxns(true);
    try {
      const data = await api.contactTransactions(companyId, c.id);
      setTxns(data);
    } catch { setTxns(null); }
    setLoadingTxns(false);
  }

  function handleSort(key: ContactSortKey) {
    if (sortKey === key) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  }

  const filtered = useMemo(() => {
    const q = search.toLowerCase().trim();
    let list = filter ? contacts.filter((c) => c.type === filter || c.type === "both") : contacts;
    if (q) {
      list = list.filter(c =>
        c.name?.toLowerCase().includes(q) ||
        c.registrationNumber?.toLowerCase().includes(q) ||
        c.vatNumber?.toLowerCase().includes(q) ||
        c.address?.city?.toLowerCase().includes(q)
      );
    }
    list = [...list].sort((a, b) => {
      let av = sortKey === "city" ? (a.address?.city ?? "") : (a[sortKey] ?? "");
      let bv = sortKey === "city" ? (b.address?.city ?? "") : (b[sortKey] ?? "");
      if (typeof av === "number" && typeof bv === "number") {
        return sortDir === "asc" ? av - bv : bv - av;
      }
      av = String(av).toLowerCase();
      bv = String(bv).toLowerCase();
      if (av < bv) return sortDir === "asc" ? -1 : 1;
      if (av > bv) return sortDir === "asc" ? 1 : -1;
      return 0;
    });
    return list;
  }, [contacts, filter, search, sortKey, sortDir]);

  if (!companyId) return (
    <div className="empty-state"><div className="icon">≡ƒÅó</div><h3>No company selected</h3></div>
  );

  // Detail view
  if (selected) {
    return (
      <div>
        <button className="btn-secondary" style={{ marginBottom: 16 }} onClick={() => setSelected(null)}>ΓåÉ Back to list</button>
        <h2 className="page-title">{selected.name}</h2>

        <div className="detail-layout">
          <div className="detail-sidebar">
            <div className="settings-card">
              <div className="onboarding-details">
                <div className="detail-row"><span className="detail-label">Type</span><span className="badge">{selected.type}</span></div>
                <div className="detail-row"><span className="detail-label">Reg. number</span><span className="mono">{selected.registrationNumber || "ΓÇö"}</span></div>
                <div className="detail-row"><span className="detail-label">VAT number</span><span className="mono">{selected.vatNumber || "ΓÇö"}</span></div>
                <div className="detail-row"><span className="detail-label">Email</span><span>{selected.email || "ΓÇö"}</span></div>
                <div className="detail-row"><span className="detail-label">Phone</span><span>{selected.phone || "ΓÇö"}</span></div>
                <div className="detail-row" style={{ alignItems: "flex-start" }}>
                  <span className="detail-label">Address</span>
                  <span style={{ textAlign: "right", lineHeight: 1.5 }}>
                    {selected.address?.line1 || selected.address?.city ? (
                      <>
                        {selected.address?.line1 && <span>{selected.address.line1}</span>}
                        {selected.address?.city && <><br />{[selected.address.city, selected.address.postalCode].filter(Boolean).join(", ")}</>}
                        {selected.address?.country && <><br />{selected.address.country}</>}
                      </>
                    ) : "ΓÇö"}
                  </span>
                </div>
                <div className="detail-row"><span className="detail-label">Payment terms</span><span>{selected.paymentTermsDays} days</span></div>
              </div>
            </div>

            {txns && (
              <div className="settings-card" style={{ marginTop: 16 }}>
                <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>Balance</h3>
                <div className="onboarding-details">
                  <div className="detail-row"><span className="detail-label">Total invoiced</span><span>{formatMoney(txns.totalInvoiced, fmt)}</span></div>
                  <div className="detail-row"><span className="detail-label">Total paid</span><span>{formatMoney(txns.totalPaid, fmt)}</span></div>
                  <div className="detail-row" style={{ fontWeight: 600 }}>
                    <span className="detail-label">Balance</span>
                    <span style={{ color: txns.balance > 0 ? "#FF3B30" : "#34C759" }}>{formatMoney(txns.balance, fmt)}</span>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div style={{ flex: 1 }}>
            {loadingTxns ? <p style={{ color: "#A0A0A0" }}>Loading transactions...</p> : txns && (
              <>
                <div className="settings-card">
                  <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>
                    Invoices ({txns.invoices?.length || 0})
                  </h3>
                  {txns.invoices?.length > 0 ? (
                    <table className="data-table">
                      <thead><tr><th>Number</th><th>Date</th><th>Net</th><th>VAT</th><th>Total</th><th>Status</th></tr></thead>
                      <tbody>
                        {txns.invoices.map((inv: any) => (
                          <tr key={inv.id}>
                            <td className="mono">{inv.invoiceNumber}</td>
                            <td>{inv.date}</td>
                            <td className="num">{formatMoney(inv.subtotal, fmt)}</td>
                            <td className="num">{formatMoney(inv.vatAmount, fmt)}</td>
                            <td className="num" style={{ fontWeight: 500 }}>{formatMoney(inv.total, fmt)}</td>
                            <td><span className={`badge badge-${inv.status}`}>{inv.status}</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <p style={{ color: "#A0A0A0", fontSize: 13 }}>No invoices</p>
                  )}
                </div>

                <div className="settings-card" style={{ marginTop: 16 }}>
                  <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>
                    Payments ({txns.payments?.length || 0})
                  </h3>
                  {txns.payments?.length > 0 ? (
                    <table className="data-table">
                      <thead><tr><th>Date</th><th>Reference</th><th>Amount</th><th>Type</th></tr></thead>
                      <tbody>
                        {txns.payments.map((p: any) => (
                          <tr key={p.id}>
                            <td>{p.date}</td>
                            <td>{p.reference}</td>
                            <td className="num" style={{ fontWeight: 500 }}>{formatMoney(p.amount, fmt)}</td>
                            <td><span className="badge">{p.type}</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <p style={{ color: "#A0A0A0", fontSize: 13 }}>No payments</p>
                  )}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header-bar">
        <h2 className="page-title" style={{ marginBottom: 0 }}>Contacts</h2>
        <div style={{ display: "flex", gap: 6 }}>
          <button className={!filter ? "btn-primary" : "btn-secondary"} onClick={() => setFilter("")}>All</button>
          <button className={filter === "vendor" ? "btn-primary" : "btn-secondary"} onClick={() => setFilter("vendor")}>Vendors</button>
          <button className={filter === "customer" ? "btn-primary" : "btn-secondary"} onClick={() => setFilter("customer")}>Customers</button>
        </div>
      </div>
      <div className="filter-bar">
        <input
          type="text"
          placeholder="Search contacts..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="table-search-input"
          aria-label="Search contacts"
        />
        {(search || filter) && (
          <span style={{ fontSize: "var(--text-sm)", color: "var(--text-tertiary)" }}>
            {filtered.length} result{filtered.length !== 1 ? "s" : ""}
          </span>
        )}
      </div>

      {loading ? <p style={{ color: "#A0A0A0" }}>Loading...</p> : filtered.length === 0 ? (
        contacts.length === 0 ? (
          <div className="empty-state">
            <div className="icon">≡ƒæÑ</div>
            <h3>No contacts yet</h3>
            <p>Upload an invoice or use the agent chat to add contacts.</p>
          </div>
        ) : (
          <div className="empty-state">
            <div className="icon">≡ƒöì</div>
            <h3>No matching contacts</h3>
            <p>Try adjusting your search or filters.</p>
          </div>
        )
      ) : (
        <table className="data-table">
          <thead>
            <tr>
              {([
                ["name", "Name"],
                ["type", "Type"],
                ["registrationNumber", "Reg. number"],
                ["vatNumber", "VAT number"],
                ["city", "City"],
                ["paymentTermsDays", "Payment terms"],
              ] as [ContactSortKey, string][]).map(([key, label]) => (
                <th
                  key={key}
                  className={`sortable-th ${sortKey === key ? "sorted" : ""}`}
                  onClick={() => handleSort(key)}
                  aria-sort={sortKey === key ? (sortDir === "asc" ? "ascending" : "descending") : "none"}
                >
                  {label}
                  {sortKey === key && (
                    <span className="sort-indicator">{sortDir === "asc" ? " Γåæ" : " Γåô"}</span>
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((c: any) => (
              <tr key={c.id} onClick={() => handleSelect(c)} style={{ cursor: "pointer" }}>
                <td style={{ fontWeight: 500 }}>{c.name}</td>
                <td><span className="badge">{c.type}</span></td>
                <td className="mono">{c.registrationNumber || "ΓÇö"}</td>
                <td className="mono">{c.vatNumber || "ΓÇö"}</td>
                <td>{c.address?.city || "ΓÇö"}</td>
                <td>{c.paymentTermsDays} days</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

