import React, { useEffect, useMemo, useState } from "react";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { formatDateTime } from "../utils/format";

// Map technical event types to user-friendly labels and icons
const EVENT_DISPLAY: Record<string, { label: string; icon: string }> = {
  "entry.posted":           { label: "Journal entry posted",     icon: "≡ƒô¥" },
  "entry.reversed":         { label: "Journal entry reversed",   icon: "Γå⌐∩╕Å" },
  "invoice.created":        { label: "Invoice created",          icon: "≡ƒôä" },
  "invoice.posted":         { label: "Invoice posted",           icon: "Γ£à" },
  "invoice.cancelled":      { label: "Invoice cancelled",        icon: "Γ¥î" },
  "payment.posted":         { label: "Payment recorded",         icon: "≡ƒÆ░" },
  "creditnote.posted":      { label: "Credit note posted",       icon: "≡ƒôï" },
  "month-end.completed":    { label: "Month-end completed",      icon: "≡ƒôà" },
  "year-end.closed":        { label: "Year-end closed",          icon: "≡ƒùô∩╕Å" },
  "contact.created":        { label: "Contact created",          icon: "≡ƒæñ" },
  "item.created":           { label: "Item created",             icon: "≡ƒôª" },
  "company.created":        { label: "Company created",          icon: "≡ƒÅó" },
  "bank.statement.imported":{ label: "Bank statement imported",  icon: "≡ƒÅª" },
  "asset.acquired":         { label: "Fixed asset acquired",     icon: "≡ƒÅù∩╕Å" },
  "asset.depreciated":      { label: "Depreciation posted",      icon: "≡ƒôë" },
  "asset.disposed":         { label: "Fixed asset disposed",     icon: "≡ƒùæ∩╕Å" },
  "recurring.executed":     { label: "Recurring entry executed",  icon: "≡ƒöä" },
  "period.closed":          { label: "Period closed",            icon: "≡ƒöÆ" },
  "period.reopened":        { label: "Period reopened",           icon: "≡ƒöô" },
  "vat.return.generated":   { label: "VAT return generated",    icon: "≡ƒôè" },
};

function getEventLabel(type: string): string {
  return EVENT_DISPLAY[type]?.label || type.replace(/\./g, " ").replace(/\b\w/g, c => c.toUpperCase());
}

function getEventIcon(type: string): string {
  return EVENT_DISPLAY[type]?.icon || "≡ƒôî";
}

// Build a human-readable summary from event data
function summarizeData(type: string, data: Record<string, any> | undefined): string {
  if (!data) return "";
  const parts: string[] = [];

  if (data.invoiceNumber) parts.push(data.invoiceNumber);
  if (data.contactName) parts.push(data.contactName);
  if (data.amount) parts.push(`Γé¼${Number(data.amount).toFixed(2)}`);
  if (data.total) parts.push(`Γé¼${Number(data.total).toFixed(2)}`);
  if (data.period) parts.push(`Period ${data.period}`);
  if (data.fiscalYear) parts.push(`FY ${data.fiscalYear}`);
  if (data.description && !data.invoiceNumber) parts.push(data.description);
  if (data.entryNumber) parts.push(`#${data.entryNumber}`);
  if (data.name && !data.contactName) parts.push(data.name);
  if (data.stepsCompleted !== null) parts.push(`${data.stepsCompleted} step${data.stepsCompleted !== 1 ? "s" : ""} completed`);

  if (parts.length === 0) {
    // Fallback: show key-value pairs but with readable keys
    return Object.entries(data)
      .filter(([k]) => !["companyId", "id", "docType", "documentId"].includes(k))
      .slice(0, 3)
      .map(([k, v]) => `${k.replace(/([A-Z])/g, " $1").toLowerCase().trim()}: ${v}`)
      .join(" ┬╖ ");
  }
  return parts.join(" ┬╖ ");
}

type SortField = "timestamp" | "type";
type SortDir = "asc" | "desc";

export function EventLog() {
  const { companyId, dateFormat, dateTimeFormat } = useApp();
  const [events, setEvents] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState<string>("");
  const [sortField, setSortField] = useState<SortField>("timestamp");
  const [sortDir, setSortDir] = useState<SortDir>("desc");

  useEffect(() => {
    if (!companyId) return;
    api.events(companyId, 200).then((d: any) => setEvents(d as any[])).catch(() => {}).finally(() => setLoading(false));
  }, [companyId]);

  if (!companyId) return <div className="empty-state"><div className="icon">≡ƒÅó</div><h3>No company selected</h3></div>;

  const typeColors: Record<string, string> = {
    "entry.posted": "badge-posted", "entry.reversed": "badge-cancelled",
    "invoice.created": "badge-draft", "invoice.posted": "badge-posted",
    "payment.posted": "badge-paid", "creditnote.posted": "badge-overdue",
    "month-end.completed": "badge-paid", "year-end.closed": "badge-paid",
    "contact.created": "badge-posted", "item.created": "badge-posted",
    "company.created": "badge-posted", "bank.statement.imported": "badge-posted",
    "asset.acquired": "badge-posted", "recurring.executed": "badge-posted",
    "period.closed": "badge-paid",
  };

  const eventTypes = useMemo(() => {
    const types = new Set(events.map(e => e.type));
    return Array.from(types).sort();
  }, [events]);

  const filteredEvents = useMemo(() => {
    const q = search.toLowerCase().trim();
    let list = events;
    if (q) {
      list = list.filter(e =>
        getEventLabel(e.type).toLowerCase().includes(q) ||
        e.type?.toLowerCase().includes(q) ||
        summarizeData(e.type, e.data).toLowerCase().includes(q)
      );
    }
    if (typeFilter) {
      list = list.filter(e => e.type === typeFilter);
    }
    // Sort
    list = [...list].sort((a, b) => {
      let cmp = 0;
      if (sortField === "timestamp") {
        cmp = (a.timestamp || "").localeCompare(b.timestamp || "");
      } else {
        cmp = (a.type || "").localeCompare(b.type || "");
      }
      return sortDir === "desc" ? -cmp : cmp;
    });
    return list;
  }, [events, search, typeFilter, sortField, sortDir]);

  function toggleSort(field: SortField) {
    if (sortField === field) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortField(field);
      setSortDir("desc");
    }
  }

  const sortIndicator = (field: SortField) =>
    sortField === field ? (sortDir === "asc" ? " Γåæ" : " Γåô") : "";

  return (
    <div>
      <h2 className="page-title">Event log</h2>

      <div style={{ display: "flex", gap: 10, marginBottom: 16, alignItems: "center" }}>
        <input
          type="text"
          placeholder="Search events..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="table-search-input"
          aria-label="Search events"
        />
        <select
          value={typeFilter}
          onChange={e => setTypeFilter(e.target.value)}
          className="table-filter-select"
          aria-label="Filter by event type"
        >
          <option value="">All events</option>
          {eventTypes.map(t => (
            <option key={t} value={t}>{getEventLabel(t)}</option>
          ))}
        </select>
        {(search || typeFilter) && (
          <span style={{ fontSize: "var(--text-sm)", color: "var(--text-tertiary)" }}>
            {filteredEvents.length} result{filteredEvents.length !== 1 ? "s" : ""}
          </span>
        )}
      </div>

      {loading ? <p style={{ color: "#A0A0A0" }}>Loading...</p> : filteredEvents.length === 0 ? (
        events.length === 0 ? (
          <div className="empty-state"><div className="icon">≡ƒôï</div><h3>No events yet</h3><p>Actions like posting invoices and payments will appear here.</p></div>
        ) : (
          <div className="empty-state"><div className="icon">≡ƒöì</div><h3>No matching events</h3><p>Try adjusting your search or filters.</p></div>
        )
      ) : (
        <table className="data-table">
          <thead><tr>
            <th style={{ cursor: "pointer", userSelect: "none" }} onClick={() => toggleSort("timestamp")}>Time{sortIndicator("timestamp")}</th>
            <th style={{ cursor: "pointer", userSelect: "none" }} onClick={() => toggleSort("type")}>Event{sortIndicator("type")}</th>
            <th>Details</th>
          </tr></thead>
          <tbody>
            {filteredEvents.map((e: any) => (
              <tr key={e.id}>
                <td style={{ fontSize: "var(--text-sm)", whiteSpace: "nowrap", color: "var(--text-secondary)" }}>
                  {formatDateTime(e.timestamp, dateFormat, dateTimeFormat)}
                </td>
                <td>
                  <span style={{ marginRight: 6 }}>{getEventIcon(e.type)}</span>
                  <span className={`badge ${typeColors[e.type] || ""}`}>{getEventLabel(e.type)}</span>
                </td>
                <td style={{ fontSize: "var(--text-sm)", color: "var(--text-secondary)" }}>
                  {summarizeData(e.type, e.data)}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { formatMoney, formatMoneyOr } from "../utils/format";
import { GlPostings } from "../components/GlPostings";

type SortKey = "code" | "name" | "assetAccountCode" | "acquisitionCost" | "accumulatedDepreciation" | "netBookValue" | "status";
type SortDir = "asc" | "desc";

export function FixedAssets() {
  const { companyId, numberFormat: fmt } = useApp();
  const [assets, setAssets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ code: "", name: "", assetAccountCode: "1220", acquisitionDate: new Date().toISOString().slice(0, 10), acquisitionCost: "", residualValue: "0", usefulLifeMonths: "60" });
  const [depPeriod, setDepPeriod] = useState(new Date().toISOString().slice(0, 7));
  const [depResult, setDepResult] = useState<any>(null);
  const [selected, setSelected] = useState<any>(null);
  const [glEntries, setGlEntries] = useState<any[]>([]);
  const [loadingGl, setLoadingGl] = useState(false);
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState<SortKey>("code");
  const [sortDir, setSortDir] = useState<SortDir>("asc");
  const [statusFilter, setStatusFilter] = useState<string>("");
  const [disposeTarget, setDisposeTarget] = useState<any>(null);
  const [disposeAmount, setDisposeAmount] = useState("0");
  const [disposing, setDisposing] = useState(false);

  useEffect(() => {
    if (!companyId) return;
    loadAssets();
  }, [companyId]);

  function loadAssets() {
    setLoading(true);
    api.fixedAssets(companyId).then((d: any) => setAssets(d as any[])).catch(() => {}).finally(() => setLoading(false));
  }

  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  function handleSort(key: SortKey) {
    if (sortKey === key) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  }

  const filteredAssets = useMemo(() => {
    const q = search.toLowerCase().trim();
    let list = assets;
    if (q) {
      list = list.filter(a =>
        a.code?.toLowerCase().includes(q) ||
        a.name?.toLowerCase().includes(q)
      );
    }
    if (statusFilter) {
      list = list.filter(a => a.status === statusFilter);
    }
    // Period filter: show assets acquired in/before the selected period
    if (depPeriod) {
      const periodEnd = depPeriod + "-31"; // rough last day
      list = list.filter(a => a.acquisitionDate <= periodEnd);
    }
    list = [...list].sort((a, b) => {
      let av = a[sortKey] ?? "";
      let bv = b[sortKey] ?? "";
      if (typeof av === "number" && typeof bv === "number") {
        return sortDir === "asc" ? av - bv : bv - av;
      }
      av = String(av).toLowerCase();
      bv = String(bv).toLowerCase();
      if (av < bv) return sortDir === "asc" ? -1 : 1;
      if (av > bv) return sortDir === "asc" ? 1 : -1;
      return 0;
    });
    return list;
  }, [assets, search, statusFilter, sortKey, sortDir, depPeriod]);

  async function handleSelect(asset: any) {
    setSelected(asset);
    setLoadingGl(true);
    try {
      const entries = await api.assetTransactions(companyId, asset.id);
      setGlEntries(entries as any[]);
    } catch { setGlEntries([]); }
    setLoadingGl(false);
  }

  async function handleAcquire() {
    if (!form.code || !form.name || !form.acquisitionCost) return;
    setError(null);
    setSaving(true);
    try {
      await api.acquireAsset(companyId, {
        code: form.code, name: form.name, assetAccountCode: form.assetAccountCode,
        depreciationAccountCode: "1240", expenseAccountCode: "6380",
        acquisitionDate: form.acquisitionDate, acquisitionCost: parseFloat(form.acquisitionCost),
        residualValue: parseFloat(form.residualValue || "0"), usefulLifeMonths: parseInt(form.usefulLifeMonths),
      });
      setShowForm(false);
      setForm({ code: "", name: "", assetAccountCode: "1220", acquisitionDate: new Date().toISOString().slice(0, 10), acquisitionCost: "", residualValue: "0", usefulLifeMonths: "60" });
      loadAssets();
    } catch (err: any) {
      setError(err.message || "Failed to acquire asset");
    } finally {
      setSaving(false);
    }
  }

  async function handleDepreciate() {
    setDepResult(null);
    const result = await api.depreciate(companyId, depPeriod);
    setDepResult(result);
    loadAssets();
    if (selected) handleSelect(selected); // Refresh GL entries
  }

  function startDispose(asset: any) {
    setDisposeTarget(asset);
    setDisposeAmount("0");
  }

  async function confirmDispose() {
    if (!disposeTarget) return;
    setDisposing(true);
    try {
      await api.disposeAsset(companyId, disposeTarget.id, parseFloat(disposeAmount || "0"));
      setDisposeTarget(null);
      loadAssets();
      if (selected?.id === disposeTarget.id) setSelected(null);
    } catch { /* ignore */ }
    setDisposing(false);
  }

  if (!companyId) return <div className="empty-state"><div className="icon">≡ƒÅó</div><h3>No company selected</h3></div>;

  // Detail view
  if (selected) {
    return (
      <div>
        <button className="btn-secondary" style={{ marginBottom: 16 }} onClick={() => setSelected(null)}>ΓåÉ Back to list</button>
        <h2 className="page-title">{selected.name}</h2>

        <div className="detail-layout">
          <div className="detail-sidebar">
            <div className="settings-card">
              <div className="onboarding-details">
                <div className="detail-row"><span className="detail-label">Code</span><span className="mono">{selected.code}</span></div>
                <div className="detail-row"><span className="detail-label">Asset account</span><span className="mono">{selected.assetAccountCode}</span></div>
                <div className="detail-row"><span className="detail-label">Depreciation account</span><span className="mono">{selected.depreciationAccountCode}</span></div>
                <div className="detail-row"><span className="detail-label">Expense account</span><span className="mono">{selected.expenseAccountCode}</span></div>
                <div className="detail-row"><span className="detail-label">Acquisition date</span><span>{selected.acquisitionDate}</span></div>
                <div className="detail-row"><span className="detail-label">Cost</span><span>{formatMoney(selected.acquisitionCost, fmt)}</span></div>
                <div className="detail-row"><span className="detail-label">Residual value</span><span>{formatMoney(selected.residualValue, fmt)}</span></div>
                <div className="detail-row"><span className="detail-label">Useful life</span><span>{selected.usefulLifeMonths} months</span></div>
                <div className="detail-row"><span className="detail-label">Method</span><span>{selected.depreciationMethod}</span></div>
                <div className="detail-row"><span className="detail-label">Accum. depreciation</span><span>{formatMoney(selected.accumulatedDepreciation, fmt)}</span></div>
                <div className="detail-row" style={{ fontWeight: 600 }}><span className="detail-label">Net book value</span><span>{formatMoney(selected.netBookValue, fmt)}</span></div>
                <div className="detail-row"><span className="detail-label">Status</span><span className={`badge ${selected.status === "active" ? "badge-posted" : selected.status === "disposed" ? "badge-cancelled" : "badge-paid"}`}>{selected.status}</span></div>
                {selected.disposalDate && (
                  <>
                    <div className="detail-row"><span className="detail-label">Disposal date</span><span>{selected.disposalDate}</span></div>
                    <div className="detail-row"><span className="detail-label">Disposal proceeds</span><span>{formatMoney(selected.disposalAmount, fmt)}</span></div>
                  </>
                )}
              </div>
              {selected.status === "active" && (
                <button className="btn-secondary" style={{ marginTop: 16, color: "#FF3B30" }} onClick={() => startDispose(selected)}>Dispose asset</button>
              )}
            </div>
          </div>

          <div style={{ flex: 1 }}>
            <div className="settings-card">
              <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>GL postings</h3>
              <GlPostings entries={glEntries} loading={loadingGl} emptyMessage="No GL entries found" formatMoney={formatMoney} fmt={fmt} />
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="coa-header">
        <h2 className="page-title">Fixed assets</h2>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
          <input type="month" value={depPeriod} onChange={(e) => setDepPeriod(e.target.value)} className="form-input" />
          <button className="btn-secondary" onClick={handleDepreciate}>Run depreciation</button>
          <button className="btn-primary" onClick={() => setShowForm(!showForm)}>{showForm ? "Cancel" : "+ Acquire asset"}</button>
        </div>
      </div>

      {depResult && (
        <div className="metric-card" style={{ marginBottom: 16, background: depResult.skipped ? "var(--bg-subtle, #F5F5F4)" : "var(--success-bg)" }}>
          <span style={{ color: depResult.skipped ? "var(--text-secondary)" : "#1A7F37", fontSize: "var(--text-sm)" }}>
            {depResult.skipped
              ? `Depreciation for ${depPeriod} already posted (${formatMoney(depResult.totalAmount, fmt)}). No changes needed.`
              : `Depreciation posted: ${depResult.assetsDepreciated} asset${depResult.assetsDepreciated !== 1 ? "s" : ""}, ${formatMoney(depResult.totalAmount, fmt)} total`}
          </span>
        </div>
      )}

      {showForm && (
        <div className="settings-card" style={{ marginBottom: 20, maxWidth: 720 }}>
          <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 8 }}>Acquire new asset</h3>
          <div className="form-hint"><span className="required-dot">*</span> Fill in code, name, and cost. Other fields have sensible defaults you can adjust.</div>
          <div className="form-grid-3">
            <div><div className="detail-label required">Code</div><input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="e.g. FA-001" className="settings-input" /></div>
            <div><div className="detail-label required">Name</div><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Office equipment" className="settings-input" /></div>
            <div><div className="detail-label">GL account</div>
              <select value={form.assetAccountCode} onChange={(e) => setForm({ ...form, assetAccountCode: e.target.value })} className="settings-input">
                <option value="1210">1210 ΓÇö Land and buildings</option>
                <option value="1220">1220 ΓÇö Equipment and machinery</option>
                <option value="1230">1230 ΓÇö Other fixed assets</option>
              </select>
            </div>
            <div><div className="detail-label">Acquisition date</div><input type="date" value={form.acquisitionDate} onChange={(e) => setForm({ ...form, acquisitionDate: e.target.value })} className="settings-input" /></div>
            <div><div className="detail-label required">Cost (Γé¼)</div><input type="number" value={form.acquisitionCost} onChange={(e) => setForm({ ...form, acquisitionCost: e.target.value })} placeholder="e.g. 10000" className="settings-input" /></div>
            <div><div className="detail-label">Residual value (Γé¼)</div><input type="number" value={form.residualValue} onChange={(e) => setForm({ ...form, residualValue: e.target.value })} className="settings-input" /><span className="field-hint">Default: 0</span></div>
            <div><div className="detail-label">Useful life (months)</div><input type="number" value={form.usefulLifeMonths} onChange={(e) => setForm({ ...form, usefulLifeMonths: e.target.value })} className="settings-input" /><span className="field-hint">Default: 60 (5 years)</span></div>
          </div>
          {error && <div style={{ marginTop: 12, padding: "8px 12px", background: "var(--error-bg)", color: "var(--error)", borderRadius: "var(--radius-sm)", fontSize: "var(--text-sm)" }}>{error}</div>}
          <button className="btn-primary" style={{ marginTop: 16 }} onClick={handleAcquire} disabled={saving}>{saving ? "Posting..." : "Acquire & post to GL"}</button>
        </div>
      )}

      {loading ? <p style={{ color: "#A0A0A0" }}>Loading...</p> : assets.length === 0 && !search && !statusFilter ? (
        <div className="empty-state"><div className="icon">≡ƒÅù∩╕Å</div><h3>No fixed assets</h3><p>Acquire your first asset to start tracking depreciation.</p></div>
      ) : (
        <>
          <div className="filter-bar">
            <input
              type="text"
              placeholder="Search assets..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="table-search-input"
              aria-label="Search assets"
            />
            <select
              value={statusFilter}
              onChange={e => setStatusFilter(e.target.value)}
              className="table-filter-select"
              aria-label="Filter by status"
            >
              <option value="">All statuses</option>
              <option value="active">Active</option>
              <option value="fully-depreciated">Fully depreciated</option>
              <option value="disposed">Disposed</option>
            </select>
            {(search || statusFilter) && (
              <span style={{ fontSize: "var(--text-sm)", color: "var(--text-tertiary)" }}>
                {filteredAssets.length} result{filteredAssets.length !== 1 ? "s" : ""}
              </span>
            )}
          </div>
          {filteredAssets.length === 0 ? (
            <div className="empty-state"><div className="icon">≡ƒöì</div><h3>No matching assets</h3><p>Try adjusting your search or filters.</p></div>
          ) : (
            <>
            {/* Desktop table */}
            <table className="data-table desktop-only-table">
              <thead>
                <tr>
                  {([
                    ["code", "Code"],
                    ["name", "Name"],
                    ["acquisitionCost", "Cost"],
                    ["netBookValue", "NBV"],
                    ["status", "Status"],
                  ] as [SortKey, string][]).map(([key, label]) => (
                    <th
                      key={key}
                      className={`sortable-th ${sortKey === key ? "sorted" : ""}`}
                      onClick={() => handleSort(key)}
                      aria-sort={sortKey === key ? (sortDir === "asc" ? "ascending" : "descending") : "none"}
                    >
                      {label}
                      {sortKey === key && (
                        <span className="sort-indicator">{sortDir === "asc" ? " Γåæ" : " Γåô"}</span>
                      )}
                    </th>
                  ))}
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {filteredAssets.map((a: any) => (
                  <tr key={a.id} onClick={() => handleSelect(a)} style={{ cursor: "pointer" }}>
                    <td className="mono">{a.code}</td>
                    <td>{a.name}</td>
                    <td className="num">{formatMoney(a.acquisitionCost, fmt)}</td>
                    <td className="num" style={{ fontWeight: 500 }}>{formatMoney(a.netBookValue, fmt)}</td>
                    <td><span className={`badge ${a.status === "active" ? "badge-posted" : a.status === "disposed" ? "badge-cancelled" : "badge-paid"}`}>{a.status}</span></td>
                    <td onClick={e => e.stopPropagation()}>{a.status === "active" && <button className="btn-secondary" style={{ padding: "2px 8px", fontSize: 12 }} onClick={() => startDispose(a)}>Dispose</button>}</td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Mobile card view */}
            <div className="mobile-card-list">
              {filteredAssets.map((a: any) => (
                <div key={a.id} className="mobile-card" onClick={() => handleSelect(a)}>
                  <div className="mobile-card-header">
                    <span className="mobile-card-title">{a.name}</span>
                    <span className="mobile-card-amount">{formatMoney(a.netBookValue, fmt)}</span>
                  </div>
                  <div className="mobile-card-meta">
                    <span className="mono">{a.code}</span>
                    <span>Cost: {formatMoney(a.acquisitionCost, fmt)}</span>
                    <span className={`badge ${a.status === "active" ? "badge-posted" : a.status === "disposed" ? "badge-cancelled" : "badge-paid"}`}>{a.status}</span>
                  </div>
                </div>
              ))}
            </div>
            </>
          )}
        </>
      )}

      {/* Disposal modal */}
      {disposeTarget && (
        <div style={{
          position: "fixed", top: 0, left: 0, right: 0, bottom: 0,
          background: "rgba(0,0,0,0.3)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100,
        }} onClick={() => setDisposeTarget(null)}>
          <div style={{
            background: "#fff", borderRadius: 12, padding: 24, width: 400, maxWidth: "90vw",
            boxShadow: "0 8px 32px rgba(0,0,0,0.12)",
          }} onClick={e => e.stopPropagation()}>
            <h3 style={{ fontSize: 16, fontWeight: 600, marginBottom: 4 }}>Dispose asset</h3>
            <p style={{ fontSize: 13, color: "var(--text-secondary)", marginBottom: 16 }}>
              Disposing <strong>{disposeTarget.name}</strong> (net book value: {formatMoney(disposeTarget.netBookValue, fmt)})
            </p>
            <div className="detail-label">Disposal proceeds (Γé¼)</div>
            <input
              type="number"
              value={disposeAmount}
              onChange={e => setDisposeAmount(e.target.value)}
              className="settings-input"
              style={{ marginBottom: 8 }}
              min="0"
              step="0.01"
              autoFocus
            />
            <span className="field-hint" style={{ display: "block", marginBottom: 16 }}>
              Enter 0 if the asset is scrapped with no proceeds
            </span>
            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
              <button className="btn-secondary" onClick={() => setDisposeTarget(null)}>Cancel</button>
              <button
                className="btn-primary"
                onClick={confirmDispose}
                disabled={disposing}
                style={{ background: "#FF3B30" }}
              >
                {disposing ? "Disposing..." : "Dispose asset"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useEffect, useMemo, useState, useRef, useCallback } from "react";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { formatMoney, formatMoneyOr } from "../utils/format";
import { GlPostings } from "../components/GlPostings";
import { AiInput } from "../components/AiInput";

type SortKey = "invoiceNumber" | "vendorInvoiceNumber" | "type" | "contactName" | "date" | "subtotal" | "vatAmount" | "total" | "status";
type SortDir = "asc" | "desc";

const TOKEN = "dev-bypass";

// ΓöÇΓöÇΓöÇ PDF rendering helpers (from UploadInvoice) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

async function pdfToImage(file: File): Promise<{ base64: string; dataUrl: string }> {
  const pdfjsLib = await loadPdfJs();
  const arrayBuffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
  const page = await pdf.getPage(1);
  const scale = 2;
  const viewport = page.getViewport({ scale });
  const canvas = document.createElement("canvas");
  canvas.width = viewport.width;
  canvas.height = viewport.height;
  const ctx = canvas.getContext("2d")!;
  await page.render({ canvasContext: ctx, viewport }).promise;
  const dataUrl = canvas.toDataURL("image/png");
  const base64 = dataUrl.split(",")[1];
  return { base64, dataUrl };
}

let pdfJsPromise: Promise<any> | null = null;
function loadPdfJs(): Promise<any> {
  if (pdfJsPromise) return pdfJsPromise;
  pdfJsPromise = new Promise((resolve, reject) => {
    if ((window as any).pdfjsLib) { resolve((window as any).pdfjsLib); return; }
    const scriptClassic = document.createElement("script");
    scriptClassic.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
    scriptClassic.onload = () => {
      const lib = (window as any).pdfjsLib;
      if (lib) {
        lib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
        resolve(lib);
      } else { reject(new Error("pdf.js failed to load")); }
    };
    scriptClassic.onerror = () => reject(new Error("Failed to load pdf.js"));
    document.head.appendChild(scriptClassic);
  });
  return pdfJsPromise;
}

// ΓöÇΓöÇΓöÇ Label style ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const labelStyle: React.CSSProperties = {
  display: "block", fontSize: 11, fontWeight: 500, color: "var(--text-tertiary)",
  textTransform: "uppercase", letterSpacing: "0.02em", marginBottom: 4,
};

export function Invoices() {
  const { companyId, numberFormat: fmt } = useApp();
  const [invoices, setInvoices] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<any>(null);
  const [postings, setPostings] = useState<any[]>([]);
  const [loadingPostings, setLoadingPostings] = useState(false);
  const [filter, setFilter] = useState<"" | "sales" | "purchase">("");
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState<SortKey>("date");
  const [sortDir, setSortDir] = useState<SortDir>("desc");
  const [statusFilter, setStatusFilter] = useState<string>("");

  // Action panels
  const [activePanel, setActivePanel] = useState<"" | "create" | "upload" | "pay">("");

  // Create invoice state
  const [aiPrompt, setAiPrompt] = useState("");
  const [aiLoading, setAiLoading] = useState(false);
  const [parsedInvoice, setParsedInvoice] = useState<any>(null);
  const [creating, setCreating] = useState(false);
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Upload invoice state
  const [dragging, setDragging] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<"idle" | "processing" | "done" | "error">("idle");
  const [uploadResult, setUploadResult] = useState<any>(null);
  const [uploadError, setUploadError] = useState("");
  const [uploadPreview, setUploadPreview] = useState<string | null>(null);

  // Pay invoice state
  const [payInvoice, setPayInvoice] = useState<any>(null);
  const [payAmount, setPayAmount] = useState("");
  const [payDate, setPayDate] = useState(new Date().toISOString().slice(0, 10));
  const [payReference, setPayReference] = useState("");
  const [paying, setPaying] = useState(false);

  useEffect(() => {
    if (!companyId) { setLoading(false); return; }
    loadInvoices();
  }, [companyId, filter]);

  function loadInvoices() {
    setLoading(true);
    api.invoices(companyId, filter || undefined).then((data: any) => { setInvoices(data); setLoading(false); }).catch(() => setLoading(false));
  }

  function handleSort(key: SortKey) {
    if (sortKey === key) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir(key === "date" ? "desc" : "asc");
    }
  }

  const filteredInvoices = useMemo(() => {
    const q = search.toLowerCase().trim();
    let list = invoices;

    if (q) {
      list = list.filter(inv =>
        inv.invoiceNumber?.toLowerCase().includes(q) ||
        inv.vendorInvoiceNumber?.toLowerCase().includes(q) ||
        inv.contactName?.toLowerCase().includes(q)
      );
    }

    if (statusFilter) {
      list = list.filter(inv => inv.status === statusFilter);
    }

    list = [...list].sort((a, b) => {
      let av = a[sortKey] ?? "";
      let bv = b[sortKey] ?? "";
      if (typeof av === "number" && typeof bv === "number") {
        return sortDir === "asc" ? av - bv : bv - av;
      }
      av = String(av).toLowerCase();
      bv = String(bv).toLowerCase();
      if (av < bv) return sortDir === "asc" ? -1 : 1;
      if (av > bv) return sortDir === "asc" ? 1 : -1;
      return 0;
    });

    return list;
  }, [invoices, search, statusFilter, sortKey, sortDir]);

  async function handleSelect(inv: any) {
    setSelected(inv);
    setLoadingPostings(true);
    try {
      const p = await api.invoicePostings(companyId, inv.id);
      setPostings(p as any[]);
    } catch { setPostings([]); }
    setLoadingPostings(false);
  }

  async function handlePost(inv: any) {
    try {
      await api.postInvoice(companyId, inv.id);
      loadInvoices();
      if (selected?.id === inv.id) handleSelect(inv);
    } catch (e: any) { console.error(e.message); }
  }

  async function handleCancel(inv: any) {
    if (!confirm(`Cancel invoice ${inv.invoiceNumber}? This will reverse the GL entries.`)) return;
    try {
      await api.cancelInvoice(companyId, inv.id, "Cancelled by user");
      loadInvoices();
      setSelected(null);
    } catch (e: any) { console.error(e.message); }
  }

  // Credit note state
  const [creditNoteInv, setCreditNoteInv] = useState<any>(null);
  const [creditReason, setCreditReason] = useState("");
  const [creditCorrect, setCreditCorrect] = useState(false);
  const [creditProcessing, setCreditProcessing] = useState(false);

  async function handleCreditNote(inv: any) {
    setCreditNoteInv(inv);
    setCreditReason("");
    setCreditCorrect(false);
  }

  async function submitCreditNote() {
    if (!creditNoteInv || !creditReason.trim()) return;
    setCreditProcessing(true);
    try {
      await api.createCreditNote(companyId, creditNoteInv.id, creditReason);

      // If "create corrected invoice" is checked, create a new invoice with AI from the reason
      if (creditCorrect) {
        try {
          const fields = await api.parseInvoiceDescription(companyId,
            `Corrected invoice for ${creditNoteInv.contactName}, originally ${creditNoteInv.invoiceNumber}. ${creditReason}`
          ) as any;
          if (fields?.lines?.length > 0) {
            const contactId = creditNoteInv.contactId || "";
            const corrected = await api.createInvoice(companyId, {
              type: creditNoteInv.type,
              contactId,
              contactName: fields.contactName || creditNoteInv.contactName,
              date: new Date().toISOString().slice(0, 10),
              dueDate: fields.dueDate,
              lines: fields.lines,
            }) as any;
            try { await api.postInvoice(companyId, corrected.id); } catch { /* ok */ }
          }
        } catch { /* corrected invoice creation is best-effort */ }
      }

      loadInvoices();
      setSelected(null);
      setCreditNoteInv(null);
    } catch (e: any) { alert(e.message); }
    finally { setCreditProcessing(false); }
  }

  // ΓöÇΓöÇΓöÇ Toggle panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  function togglePanel(panel: "create" | "upload" | "pay") {
    setActivePanel(prev => prev === panel ? "" : panel);
    // Reset states when closing
    if (activePanel === panel) return;
    setParsedInvoice(null);
    setAiPrompt("");
    setUploadStatus("idle");
    setUploadResult(null);
    setUploadError("");
    setUploadPreview(null);
    setPayInvoice(null);
  }

  // ΓöÇΓöÇΓöÇ Create invoice via AI ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  async function handleAiDescribe(text?: string) {
    const desc = text || aiPrompt;
    if (!desc.trim() || !companyId) return;
    setAiLoading(true);
    try {
      const fields = await api.parseInvoiceDescription(companyId, desc) as any;
      setParsedInvoice(fields);
    } catch (err: any) {
      alert(err.message || "Failed to parse description");
    } finally {
      setAiLoading(false);
    }
  }

  function toggleVoice() {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser. Please use Chrome or Edge.");
      return;
    }
    if (listening && recognitionRef.current) {
      recognitionRef.current.stop();
      setListening(false);
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = "en-US";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setAiPrompt(transcript);
      setListening(false);
      handleAiDescribe(transcript);
    };
    recognition.onerror = () => setListening(false);
    recognition.onend = () => setListening(false);
    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  }

  async function handleCreateInvoice() {
    if (!parsedInvoice || !companyId) return;
    setCreating(true);
    try {
      // Auto-create contact if contactName is provided
      let contactId = "";
      if (parsedInvoice.contactName) {
        try {
          const contact = await api.createContact(companyId, {
            type: parsedInvoice.type === "sales" ? "customer" : "vendor",
            name: parsedInvoice.contactName,
            address: { line1: "", city: "", postalCode: "", country: "LV" },
          }) as any;
          contactId = contact.id;
        } catch { /* contact may already exist, proceed without id */ }
      }
      const invoice = await api.createInvoice(companyId, {
        type: parsedInvoice.type,
        contactId,
        contactName: parsedInvoice.contactName,
        date: parsedInvoice.date,
        dueDate: parsedInvoice.dueDate,
        lines: parsedInvoice.lines,
      }) as any;
      // Auto-post
      try { await api.postInvoice(companyId, invoice.id); } catch { /* draft is fine */ }
      setActivePanel("");
      setParsedInvoice(null);
      setAiPrompt("");
      loadInvoices();
    } catch (err: any) {
      alert(err.message || "Failed to create invoice");
    } finally {
      setCreating(false);
    }
  }

  // ΓöÇΓöÇΓöÇ Upload invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const processFile = useCallback(async (file: File) => {
    if (!companyId) { setUploadError("No company selected"); return; }
    const supportedImages = ["image/jpeg", "image/png", "image/gif", "image/webp"];
    const isPdf = file.type === "application/pdf";
    if (!supportedImages.includes(file.type) && !isPdf) {
      setUploadError("Please upload an image (JPG, PNG, WebP) or PDF file");
      return;
    }
    setUploadStatus("processing");
    setUploadError("");
    setUploadResult(null);
    let base64: string;
    let mimeType: string;
    if (isPdf) {
      try {
        const pdfData = await pdfToImage(file);
        base64 = pdfData.base64;
        mimeType = "image/png";
        setUploadPreview(pdfData.dataUrl);
      } catch {
        setUploadError("Could not render PDF. Try uploading a photo of the invoice instead.");
        setUploadStatus("error");
        return;
      }
    } else {
      const buffer = await file.arrayBuffer();
      base64 = btoa(new Uint8Array(buffer).reduce((data, byte) => data + String.fromCharCode(byte), ""));
      mimeType = file.type;
      setUploadPreview(URL.createObjectURL(file));
    }
    try {
      const res = await fetch(`/api/companies/${companyId}/invoices/upload`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${TOKEN}` },
        body: JSON.stringify({ image: base64, mimeType }),
      });
      const json = await res.json();
      if (json.error) { setUploadError(json.error.message); setUploadStatus("error"); }
      else { setUploadResult(json.data); setUploadStatus("done"); loadInvoices(); }
    } catch (err) {
      setUploadError(err instanceof Error ? err.message : "Upload failed");
      setUploadStatus("error");
    }
  }, [companyId]);

  // ΓöÇΓöÇΓöÇ Pay invoice ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  function startPay(inv: any) {
    setPayInvoice(inv);
    setPayAmount(String(Math.round(((inv.total || 0) - (inv.amountPaid || 0)) * 100) / 100));
    setPayDate(new Date().toISOString().slice(0, 10));
    setPayReference("");
    setActivePanel("pay");
  }

  async function handlePayInvoice() {
    if (!payInvoice || !companyId) return;
    const amount = parseFloat(payAmount);
    if (isNaN(amount) || amount <= 0) return;
    setPaying(true);
    try {
      await api.createPayment(companyId, {
        type: payInvoice.type === "sales" ? "incoming" : "outgoing",
        contactId: payInvoice.contactId,
        contactName: payInvoice.contactName,
        date: payDate,
        amount,
        bankAccountIban: "",
        reference: payReference || `Payment for ${payInvoice.invoiceNumber}`,
        invoiceAllocations: [{
          invoiceId: payInvoice.id,
          invoiceNumber: payInvoice.invoiceNumber,
          amount,
        }],
      });
      setActivePanel("");
      setPayInvoice(null);
      loadInvoices();
    } catch (err: any) {
      alert(err.message || "Failed to record payment");
    } finally {
      setPaying(false);
    }
  }

  if (!companyId) return <NoCompany />;

  // Detail view
  if (selected) {
    return (
      <div>
        <button className="btn-secondary" style={{ marginBottom: 16 }} onClick={() => setSelected(null)}>ΓåÉ Back to list</button>
        <h2 className="page-title">Invoice {selected.invoiceNumber}</h2>

        <div className="detail-layout">
          <div style={{ flex: 1 }}>
            <div className="settings-card">
              <div className="onboarding-details">
                <div className="detail-row"><span className="detail-label">ERA number</span><span className="mono">{selected.invoiceNumber}</span></div>
                {selected.vendorInvoiceNumber && (
                  <div className="detail-row"><span className="detail-label">Vendor invoice #</span><span className="mono">{selected.vendorInvoiceNumber}</span></div>
                )}
                <div className="detail-row"><span className="detail-label">Type</span><span className="badge">{selected.type}</span></div>
                <div className="detail-row"><span className="detail-label">Contact</span><span>{selected.contactName}</span></div>
                <div className="detail-row"><span className="detail-label">Date</span><span>{selected.date}</span></div>
                <div className="detail-row"><span className="detail-label">Due date</span><span>{selected.dueDate}</span></div>
                <div className="detail-row"><span className="detail-label">Subtotal</span><span>{formatMoney(selected.subtotal, fmt)}</span></div>
                <div className="detail-row"><span className="detail-label">VAT</span><span>{formatMoney(selected.vatAmount, fmt)}</span></div>
                <div className="detail-row" style={{ fontWeight: 600 }}><span className="detail-label">Total</span><span>{formatMoney(selected.total, fmt)}</span></div>
                <div className="detail-row"><span className="detail-label">Paid</span><span>{formatMoney(selected.amountPaid, fmt)}</span></div>
                <div className="detail-row"><span className="detail-label">Status</span><span className={`badge badge-${selected.status}`}>{selected.status}</span></div>
                {selected.recognitionConfidence && (
                  <div className="detail-row"><span className="detail-label">AI confidence</span><span className={`badge badge-${selected.recognitionConfidence === "high" ? "paid" : "posted"}`}>{selected.recognitionConfidence}</span></div>
                )}
              </div>

              <div className="btn-row" style={{ marginTop: 16 }}>
                {selected.status === "draft" && (
                  <button className="btn-primary" onClick={() => handlePost(selected)}>Post to ledger</button>
                )}
                {(selected.status === "posted" || selected.status === "overdue") && (
                  <button className="btn-primary" onClick={() => startPay(selected)}>Record payment</button>
                )}
                {selected.status !== "cancelled" && selected.status !== "draft" && (
                  <button className="btn-secondary" onClick={() => handleCreditNote(selected)}>Credit note</button>
                )}
                <a href={api.invoicePdfUrl(companyId, selected.id)} target="_blank" rel="noopener noreferrer" className="btn-secondary" style={{ display: "inline-flex", alignItems: "center", textDecoration: "none" }}>
                  PDF Γåô
                </a>
                {selected.status !== "cancelled" && (
                  <button className="btn-secondary" style={{ color: "#FF3B30" }} onClick={() => handleCancel(selected)}>Cancel invoice</button>
                )}
              </div>
            </div>
          </div>

          <div style={{ flex: 1 }}>
            {selected.lines?.length > 0 && (
              <div className="settings-card">
                <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>Line items</h3>
                <table className="data-table">
                  <thead><tr><th>Description</th><th>Qty</th><th>Price</th><th>VAT</th><th>Total</th></tr></thead>
                  <tbody>
                    {selected.lines.map((l: any, i: number) => (
                      <tr key={i}>
                        <td>{l.description}</td>
                        <td className="num">{l.quantity}</td>
                        <td className="num">{formatMoney(l.unitPrice, fmt)}</td>
                        <td>{l.vatRate}%</td>
                        <td className="num">{formatMoney(l.lineTotal, fmt)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

            <div className="settings-card" style={{ marginTop: 16 }}>
              <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>GL postings</h3>
              <GlPostings entries={postings} loading={loadingPostings} emptyMessage="No GL entries (invoice not yet posted)" formatMoney={formatMoney} fmt={fmt} />
            </div>

            {/* Pay invoice inline panel (from detail view) */}
            {activePanel === "pay" && payInvoice?.id === selected.id && (
              <div className="settings-card" style={{ marginTop: 16 }}>
                <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>Record payment</h3>
                <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12 }}>
                  <div>
                    <label style={labelStyle}>Amount</label>
                    <input type="number" step="0.01" value={payAmount} onChange={e => setPayAmount(e.target.value)} className="form-input" style={{ width: "100%" }} aria-label="Payment amount" />
                  </div>
                  <div>
                    <label style={labelStyle}>Date</label>
                    <input type="date" value={payDate} onChange={e => setPayDate(e.target.value)} className="form-input" style={{ width: "100%" }} aria-label="Payment date" />
                  </div>
                  <div style={{ gridColumn: "span 2" }}>
                    <label style={labelStyle}>Reference</label>
                    <input type="text" value={payReference} onChange={e => setPayReference(e.target.value)} placeholder="Bank reference or note" className="form-input" style={{ width: "100%" }} aria-label="Payment reference" />
                  </div>
                </div>
                <div style={{ marginTop: 12, display: "flex", gap: 8 }}>
                  <button className="btn-primary" onClick={handlePayInvoice} disabled={paying || !payAmount}>
                    {paying ? "Processing..." : "Record payment"}
                  </button>
                  <button className="btn-secondary" onClick={() => { setActivePanel(""); setPayInvoice(null); }}>Cancel</button>
                </div>
              </div>
            )}

            {/* Credit note dialog */}
            {creditNoteInv?.id === selected.id && (
              <div className="settings-card" style={{ marginTop: 16 }}>
                <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>Credit note for {creditNoteInv.invoiceNumber}</h3>
                <div style={{ marginBottom: 12 }}>
                  <label style={labelStyle}>Reason for credit note</label>
                  <AiInput
                    placeholder="Describe the reason, e.g. 'Price was incorrect, should be Γé¼100 instead of Γé¼120'"
                    buttonLabel="Γ£¿ Generate corrected"
                    loadingLabel="Processing..."
                    onSubmit={async (text) => { setCreditReason(text); }}
                  />
                  {creditReason && (
                    <div style={{ marginTop: 8, padding: 10, background: "var(--bg-subtle)", borderRadius: "var(--radius-sm)", fontSize: "var(--text-sm)" }}>
                      {creditReason}
                    </div>
                  )}
                </div>
                <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: "var(--text-sm)", marginBottom: 12 }}>
                  <input type="checkbox" checked={creditCorrect} onChange={e => setCreditCorrect(e.target.checked)} />
                  Also create a corrected invoice based on the description
                </label>
                <div style={{ display: "flex", gap: 8 }}>
                  <button className="btn-primary" onClick={submitCreditNote} disabled={creditProcessing || !creditReason.trim()}>
                    {creditProcessing ? "Processing..." : creditCorrect ? "Issue credit note + corrected invoice" : "Issue credit note"}
                  </button>
                  <button className="btn-secondary" onClick={() => setCreditNoteInv(null)}>Cancel</button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div>
      <div className="page-header-bar">
        <h2 className="page-title" style={{ marginBottom: 0 }}>Invoices</h2>
        <div className="action-buttons" style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
          <button className={`btn-primary ${activePanel === "create" ? "active" : ""}`} onClick={() => togglePanel("create")}>
            {activePanel === "create" ? "Cancel" : "+ Create invoice"}
          </button>
          <button className={`btn-secondary ${activePanel === "upload" ? "active" : ""}`} onClick={() => togglePanel("upload")}>
            {activePanel === "upload" ? "Cancel" : "≡ƒôä Upload"}
          </button>
        </div>
      </div>

      {/* ΓöÇΓöÇΓöÇ Create Invoice Panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {activePanel === "create" && (
        <div className="settings-card" style={{ marginBottom: 20 }}>
          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Describe the invoice you want to create</label>
            <div style={{ display: "flex", gap: 8, alignItems: "stretch", flexWrap: "wrap" }}>
              <input
                type="text"
                value={aiPrompt}
                onChange={e => setAiPrompt(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter") handleAiDescribe(); }}
                placeholder='e.g. "Sales invoice for SIA Klient, consulting 10h at Γé¼120/h"'
                className="form-input"
                style={{ flex: 1, minWidth: 0, fontSize: 16 }}
                aria-label="Describe invoice"
              />
              <button className="btn-primary" onClick={() => handleAiDescribe()} disabled={aiLoading || !aiPrompt.trim()} style={{ whiteSpace: "nowrap" }}>
                {aiLoading ? "Thinking..." : "Γ£¿ Generate"}
              </button>
              <button
                className={listening ? "btn-primary" : "btn-secondary"}
                onClick={toggleVoice}
                title={listening ? "Stop listening" : "Voice input"}
                aria-label={listening ? "Stop voice input" : "Start voice input"}
                style={{
                  width: 40, minWidth: 40, padding: 0,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 18,
                  ...(listening ? { animation: "pulse 1.5s ease-in-out infinite" } : {}),
                }}
              >
                ≡ƒÄÖ
              </button>
            </div>
            {listening && (
              <p style={{ fontSize: "var(--text-sm)", color: "var(--accent)", marginTop: 4, marginBottom: 0 }}>
                Listening... speak now
              </p>
            )}
          </div>

          {parsedInvoice && (
            <div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12, marginBottom: 12 }}>
                <div>
                  <label style={labelStyle}>Type</label>
                  <select
                    value={parsedInvoice.type}
                    onChange={e => setParsedInvoice((p: any) => ({ ...p, type: e.target.value }))}
                    className="table-filter-select"
                    aria-label="Invoice type"
                  >
                    <option value="sales">Sales</option>
                    <option value="purchase">Purchase</option>
                  </select>
                </div>
                <div style={{ gridColumn: "span 2" }}>
                  <label style={labelStyle}>Contact</label>
                  <input type="text" value={parsedInvoice.contactName} onChange={e => setParsedInvoice((p: any) => ({ ...p, contactName: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Contact name" />
                </div>
                <div>
                  <label style={labelStyle}>Date</label>
                  <input type="date" value={parsedInvoice.date} onChange={e => setParsedInvoice((p: any) => ({ ...p, date: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Invoice date" />
                </div>
                <div>
                  <label style={labelStyle}>Due date</label>
                  <input type="date" value={parsedInvoice.dueDate} onChange={e => setParsedInvoice((p: any) => ({ ...p, dueDate: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Due date" />
                </div>
              </div>

              {parsedInvoice.lines?.length > 0 && (
                <table className="data-table" style={{ marginBottom: 12 }}>
                  <thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>VAT %</th><th>Account</th></tr></thead>
                  <tbody>
                    {parsedInvoice.lines.map((l: any, i: number) => (
                      <tr key={i}>
                        <td>
                          <input type="text" value={l.description} onChange={e => {
                            const lines = [...parsedInvoice.lines];
                            lines[i] = { ...lines[i], description: e.target.value };
                            setParsedInvoice((p: any) => ({ ...p, lines }));
                          }} className="form-input" style={{ width: "100%", minWidth: 120 }} aria-label={`Line ${i + 1} description`} />
                        </td>
                        <td>
                          <input type="number" value={l.quantity} onChange={e => {
                            const lines = [...parsedInvoice.lines];
                            lines[i] = { ...lines[i], quantity: Number(e.target.value) };
                            setParsedInvoice((p: any) => ({ ...p, lines }));
                          }} className="form-input" style={{ width: 70 }} aria-label={`Line ${i + 1} quantity`} />
                        </td>
                        <td>
                          <input type="number" step="0.01" value={l.unitPrice} onChange={e => {
                            const lines = [...parsedInvoice.lines];
                            lines[i] = { ...lines[i], unitPrice: Number(e.target.value) };
                            setParsedInvoice((p: any) => ({ ...p, lines }));
                          }} className="form-input" style={{ width: 100 }} aria-label={`Line ${i + 1} unit price`} />
                        </td>
                        <td>
                          <input type="number" value={l.vatRate} onChange={e => {
                            const lines = [...parsedInvoice.lines];
                            lines[i] = { ...lines[i], vatRate: Number(e.target.value) };
                            setParsedInvoice((p: any) => ({ ...p, lines }));
                          }} className="form-input" style={{ width: 60 }} aria-label={`Line ${i + 1} VAT rate`} />
                        </td>
                        <td className="mono" style={{ fontSize: "var(--text-sm)" }}>{l.accountCode}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}

              <div style={{ display: "flex", gap: 8 }}>
                <button className="btn-primary" onClick={handleCreateInvoice} disabled={creating || !parsedInvoice.contactName}>
                  {creating ? "Creating..." : "Create & post invoice"}
                </button>
                <button className="btn-secondary" onClick={() => setParsedInvoice(null)}>Reset</button>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ Upload Invoice Panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {activePanel === "upload" && (
        <div className="settings-card" style={{ marginBottom: 20 }}>
          <div
            className={`drop-zone ${dragging ? "active" : ""} ${uploadStatus === "processing" ? "processing" : ""}`}
            onDragOver={e => { e.preventDefault(); setDragging(true); }}
            onDragLeave={() => setDragging(false)}
            onDrop={e => { e.preventDefault(); setDragging(false); const file = e.dataTransfer.files[0]; if (file) processFile(file); }}
            onClick={() => document.getElementById("invoice-file-input")?.click()}
          >
            <input id="invoice-file-input" type="file" accept="image/*,application/pdf" onChange={e => { const file = e.target.files?.[0]; if (file) processFile(file); }} style={{ display: "none" }} />
            {uploadStatus === "processing" ? (
              <div className="drop-zone-content">
                <div className="drop-zone-icon">ΓÅ│</div>
                <div className="drop-zone-title">Recognizing invoice...</div>
                <div className="drop-zone-subtitle">GPT-4o is extracting data from your document</div>
              </div>
            ) : (
              <div className="drop-zone-content">
                <div className="drop-zone-icon">≡ƒôä</div>
                <div className="drop-zone-title">Drop invoice here or click to upload</div>
                <div className="drop-zone-subtitle">Supports JPG, PNG, or PDF</div>
              </div>
            )}
          </div>
          {uploadError && <p style={{ color: "#FF3B30", fontSize: 13, marginTop: 12 }}>{uploadError}</p>}
          {uploadStatus === "done" && uploadResult && (
            <div style={{ marginTop: 16 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, color: "var(--success)", fontSize: 13, marginBottom: 12 }}>
                <span>Γ£à</span> {uploadResult.message}
                {uploadResult.invoice?.invoiceNumber && (
                  <span className="mono" style={{ color: "var(--text-secondary)" }}>ΓÇö {uploadResult.invoice.invoiceNumber}</span>
                )}
              </div>
              <button className="btn-secondary" onClick={() => { setUploadStatus("idle"); setUploadResult(null); setUploadPreview(null); }}>
                Upload another
              </button>
            </div>
          )}
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ Type Filter ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <div className="coa-level-controls">
          <button className={`coa-level-btn ${!filter ? "active" : ""}`} onClick={() => setFilter("")}>All</button>
          <button className={`coa-level-btn ${filter === "purchase" ? "active" : ""}`} onClick={() => setFilter("purchase")}>Purchase</button>
          <button className={`coa-level-btn ${filter === "sales" ? "active" : ""}`} onClick={() => setFilter("sales")}>Sales</button>
        </div>
      </div>

      <div className="filter-bar">
        <input
          type="text"
          placeholder="Search invoices..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="table-search-input"
          aria-label="Search invoices"
        />
        <select
          value={statusFilter}
          onChange={e => setStatusFilter(e.target.value)}
          className="table-filter-select"
          aria-label="Filter by status"
        >
          <option value="">All statuses</option>
          <option value="draft">Draft</option>
          <option value="posted">Posted</option>
          <option value="paid">Paid</option>
          <option value="overdue">Overdue</option>
          <option value="cancelled">Cancelled</option>
        </select>
        {(search || statusFilter) && (
          <span style={{ fontSize: "var(--text-sm)", color: "var(--text-tertiary)" }}>
            {filteredInvoices.length} result{filteredInvoices.length !== 1 ? "s" : ""}
          </span>
        )}
      </div>

      {loading ? <p style={{ color: "#A0A0A0" }}>Loading...</p> : filteredInvoices.length === 0 ? (
        invoices.length === 0 ? (
          <div className="empty-state">
            <div className="icon">≡ƒôä</div>
            <h3>No invoices yet</h3>
            <p>Create an invoice, upload a document, or use the agent chat.</p>
          </div>
        ) : (
          <div className="empty-state">
            <div className="icon">≡ƒöì</div>
            <h3>No matching invoices</h3>
            <p>Try adjusting your search or filters.</p>
          </div>
        )
      ) : (
        <>
        {/* Desktop table */}
        <table className="data-table desktop-only-table">
          <thead>
            <tr>
              {([
                ["invoiceNumber", "Number"],
                ["type", "Type"],
                ["contactName", "Contact"],
                ["date", "Date"],
                ["total", "Total"],
                ["status", "Status"],
              ] as [SortKey, string][]).map(([key, label]) => (
                <th
                  key={key}
                  className={`sortable-th ${sortKey === key ? "sorted" : ""}`}
                  onClick={() => handleSort(key)}
                  aria-sort={sortKey === key ? (sortDir === "asc" ? "ascending" : "descending") : "none"}
                >
                  {label}
                  {sortKey === key && (
                    <span className="sort-indicator">{sortDir === "asc" ? " Γåæ" : " Γåô"}</span>
                  )}
                </th>
              ))}
              <th></th>
            </tr>
          </thead>
          <tbody>
            {filteredInvoices.map((inv: any) => (
              <tr key={inv.id} onClick={() => handleSelect(inv)} style={{ cursor: "pointer" }}>
                <td className="mono">{inv.invoiceNumber}</td>
                <td><span className="badge">{inv.type}</span></td>
                <td>{inv.contactName}</td>
                <td>{inv.date}</td>
                <td className="num" style={{ fontWeight: 500 }}>{formatMoney(inv.total, fmt)}</td>
                <td><span className={`badge badge-${inv.status}`}>{inv.status}</span></td>
                <td>
                  {(inv.status === "posted" || inv.status === "overdue") && (
                    <button className="btn-secondary" style={{ fontSize: 11, padding: "2px 8px" }} onClick={e => { e.stopPropagation(); startPay(inv); }} aria-label={`Pay ${inv.invoiceNumber}`}>
                      Pay
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Mobile card view */}
        <div className="mobile-card-list">
          {filteredInvoices.map((inv: any) => (
            <div key={inv.id} className="mobile-card" onClick={() => handleSelect(inv)}>
              <div className="mobile-card-header">
                <span className="mobile-card-title">{inv.contactName || inv.invoiceNumber}</span>
                <span className="mobile-card-amount">{formatMoney(inv.total, fmt)}</span>
              </div>
              <div className="mobile-card-meta">
                <span className="mono">{inv.invoiceNumber}</span>
                <span className="badge">{inv.type}</span>
                <span>{inv.date}</span>
                <span className={`badge badge-${inv.status}`}>{inv.status}</span>
              </div>
            </div>
          ))}
        </div>
        </>
      )}
    </div>
  );
}

function NoCompany() {
  return (
    <div className="empty-state">
      <div className="icon">≡ƒÅó</div>
      <h3>No company selected</h3>
      <p>Use the agent chat to create a company first.</p>
    </div>
  );
}

import React, { useEffect, useMemo, useState, useRef } from "react";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { formatMoney } from "../utils/format";

type ItemSortKey = "code" | "name" | "type" | "sellingPrice" | "vatRate" | "quantityOnHand";
type SortDir = "asc" | "desc";

interface ItemForm {
  name: string;
  description: string;
  type: "product" | "service";
  unitOfMeasure: string;
  costPrice: string;
  sellingPrice: string;
  vatRate: string;
  purchaseAccountCode: string;
  salesAccountCode: string;
}

const EMPTY_FORM: ItemForm = {
  name: "", description: "", type: "product", unitOfMeasure: "pcs",
  costPrice: "0", sellingPrice: "0", vatRate: "21",
  purchaseAccountCode: "6110", salesAccountCode: "5110",
};

export function Items() {
  const { companyId, numberFormat: fmt } = useApp();
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState<ItemSortKey>("code");
  const [sortDir, setSortDir] = useState<SortDir>("asc");
  const [typeFilter, setTypeFilter] = useState<string>("");

  // Add form
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState<ItemForm>(EMPTY_FORM);
  const [aiPrompt, setAiPrompt] = useState("");
  const [aiLoading, setAiLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [listening, setListening] = useState(false);
  const recognitionRef = useRef<any>(null);

  // Detail view
  const [selected, setSelected] = useState<any>(null);

  useEffect(() => {
    if (!companyId) { setLoading(false); return; }
    loadItems();
  }, [companyId]);

  function loadItems() {
    setLoading(true);
    api.items(companyId).then((data: any) => { setItems(data); setLoading(false); }).catch(() => setLoading(false));
  }

  function handleSort(key: ItemSortKey) {
    if (sortKey === key) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  }

  const filteredItems = useMemo(() => {
    const q = search.toLowerCase().trim();
    let list = items;
    if (q) {
      list = list.filter(item =>
        item.code?.toLowerCase().includes(q) ||
        item.name?.toLowerCase().includes(q)
      );
    }
    if (typeFilter) {
      list = list.filter(item => item.type === typeFilter);
    }
    list = [...list].sort((a, b) => {
      let av = a[sortKey] ?? "";
      let bv = b[sortKey] ?? "";
      if (typeof av === "number" && typeof bv === "number") {
        return sortDir === "asc" ? av - bv : bv - av;
      }
      av = String(av).toLowerCase();
      bv = String(bv).toLowerCase();
      if (av < bv) return sortDir === "asc" ? -1 : 1;
      if (av > bv) return sortDir === "asc" ? 1 : -1;
      return 0;
    });
    return list;
  }, [items, search, typeFilter, sortKey, sortDir]);

  // ΓöÇΓöÇΓöÇ AI Describe ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  async function handleAiDescribe(text?: string) {
    const desc = text || aiPrompt;
    if (!desc.trim() || !companyId) return;
    setAiLoading(true);
    try {
      const fields = await api.parseItemDescription(companyId, desc) as any;
      setForm({
        name: fields.name || "",
        description: fields.description || "",
        type: fields.type || "product",
        unitOfMeasure: fields.unitOfMeasure || "pcs",
        costPrice: String(fields.costPrice ?? 0),
        sellingPrice: String(fields.sellingPrice ?? 0),
        vatRate: String(fields.vatRate ?? 21),
        purchaseAccountCode: fields.purchaseAccountCode || "6110",
        salesAccountCode: fields.salesAccountCode || "5110",
      });
    } catch (err: any) {
      alert(err.message || "Failed to parse description");
    } finally {
      setAiLoading(false);
    }
  }

  // ΓöÇΓöÇΓöÇ Voice Input ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  function toggleVoice() {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      alert("Speech recognition is not supported in this browser. Please use Chrome or Edge.");
      return;
    }

    if (listening && recognitionRef.current) {
      recognitionRef.current.stop();
      setListening(false);
      return;
    }

    const recognition = new SpeechRecognition();
    recognition.lang = "en-US";
    recognition.interimResults = false;
    recognition.maxAlternatives = 1;

    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setAiPrompt(transcript);
      setListening(false);
      handleAiDescribe(transcript);
    };

    recognition.onerror = () => {
      setListening(false);
    };

    recognition.onend = () => {
      setListening(false);
    };

    recognitionRef.current = recognition;
    recognition.start();
    setListening(true);
  }

  // ΓöÇΓöÇΓöÇ Save Item ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  async function handleSave() {
    if (!form.name.trim() || !companyId) return;
    setSaving(true);
    try {
      await api.createItem(companyId, {
        code: "",
        name: form.name,
        description: form.description,
        type: form.type,
        unitOfMeasure: form.unitOfMeasure,
        costPrice: parseFloat(form.costPrice) || 0,
        sellingPrice: parseFloat(form.sellingPrice) || 0,
        vatRate: parseInt(form.vatRate) || 21,
        purchaseAccountCode: form.purchaseAccountCode,
        salesAccountCode: form.salesAccountCode,
      });
      setForm(EMPTY_FORM);
      setAiPrompt("");
      setShowForm(false);
      loadItems();
    } catch (err: any) {
      alert(err.message || "Failed to create item");
    } finally {
      setSaving(false);
    }
  }

  // ΓöÇΓöÇΓöÇ Label style ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const labelStyle: React.CSSProperties = {
    display: "block", fontSize: 11, fontWeight: 500, color: "var(--text-tertiary)",
    textTransform: "uppercase", letterSpacing: "0.02em", marginBottom: 4,
  };

  if (!companyId) return (
    <div className="empty-state">
      <div className="icon">≡ƒÅó</div>
      <h3>No company selected</h3>
      <p>Use the agent chat to create a company first.</p>
    </div>
  );

  return (
    <div>
      <div className="coa-header">
        <h2 className="page-title">Items</h2>
        <button className="btn-primary" onClick={() => setShowForm(f => !f)}>
          {showForm ? "Cancel" : "+ Add item"}
        </button>
      </div>

      {/* ΓöÇΓöÇΓöÇ Add Item Form ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {showForm && (
        <div className="settings-card" style={{ marginBottom: 20 }}>
          {/* AI description bar */}
          <div style={{ marginBottom: 16 }}>
            <label style={labelStyle}>Describe the item you want to add</label>
            <div style={{ display: "flex", gap: 8, alignItems: "stretch" }}>
              <input
                type="text"
                value={aiPrompt}
                onChange={e => setAiPrompt(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter") handleAiDescribe(); }}
                placeholder="e.g. Consulting service, Γé¼120/hour, for IT services"
                className="form-input"
                style={{ flex: 1 }}
                aria-label="Describe item"
              />
              <button
                className="btn-primary"
                onClick={() => handleAiDescribe()}
                disabled={aiLoading || !aiPrompt.trim()}
                style={{ whiteSpace: "nowrap" }}
              >
                {aiLoading ? "Thinking..." : "Γ£¿ Fill fields"}
              </button>
              <button
                className={listening ? "btn-primary" : "btn-secondary"}
                onClick={toggleVoice}
                title={listening ? "Stop listening" : "Voice input"}
                aria-label={listening ? "Stop voice input" : "Start voice input"}
                style={{
                  width: 40, minWidth: 40, padding: 0,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 18,
                  ...(listening ? { animation: "pulse 1.5s ease-in-out infinite" } : {}),
                }}
              >
                ≡ƒÄÖ
              </button>
            </div>
            {listening && (
              <p style={{ fontSize: "var(--text-sm)", color: "var(--accent)", marginTop: 4, marginBottom: 0 }}>
                Listening... speak now
              </p>
            )}
          </div>

          {/* Form fields */}
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))", gap: 12 }}>
            <div style={{ gridColumn: "span 2" }}>
              <label style={labelStyle}>Name</label>
              <input type="text" value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Item name" />
            </div>
            <div style={{ gridColumn: "span 2" }}>
              <label style={labelStyle}>Description</label>
              <input type="text" value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Item description" />
            </div>
            <div>
              <label style={labelStyle}>Type</label>
              <select value={form.type} onChange={e => setForm(f => ({ ...f, type: e.target.value as any }))} className="table-filter-select" aria-label="Item type">
                <option value="product">Product</option>
                <option value="service">Service</option>
              </select>
            </div>
            <div>
              <label style={labelStyle}>Unit of measure</label>
              <input type="text" value={form.unitOfMeasure} onChange={e => setForm(f => ({ ...f, unitOfMeasure: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Unit of measure" />
            </div>
            <div>
              <label style={labelStyle}>Cost price (EUR)</label>
              <input type="number" step="0.01" value={form.costPrice} onChange={e => setForm(f => ({ ...f, costPrice: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Cost price" />
            </div>
            <div>
              <label style={labelStyle}>Selling price (EUR)</label>
              <input type="number" step="0.01" value={form.sellingPrice} onChange={e => setForm(f => ({ ...f, sellingPrice: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Selling price" />
            </div>
            <div>
              <label style={labelStyle}>VAT rate (%)</label>
              <select value={form.vatRate} onChange={e => setForm(f => ({ ...f, vatRate: e.target.value }))} className="table-filter-select" aria-label="VAT rate">
                <option value="21">21% ΓÇö standard</option>
                <option value="12">12% ΓÇö reduced</option>
                <option value="5">5% ΓÇö super-reduced</option>
                <option value="0">0% ΓÇö exempt</option>
              </select>
            </div>
            <div>
              <label style={labelStyle}>Purchase account</label>
              <input type="text" value={form.purchaseAccountCode} onChange={e => setForm(f => ({ ...f, purchaseAccountCode: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Purchase account code" />
            </div>
            <div>
              <label style={labelStyle}>Sales account</label>
              <input type="text" value={form.salesAccountCode} onChange={e => setForm(f => ({ ...f, salesAccountCode: e.target.value }))} className="form-input" style={{ width: "100%" }} aria-label="Sales account code" />
            </div>
          </div>

          <div style={{ marginTop: 16, display: "flex", gap: 8 }}>
            <button className="btn-primary" onClick={handleSave} disabled={saving || !form.name.trim()}>
              {saving ? "Saving..." : "Save item"}
            </button>
            <button className="btn-secondary" onClick={() => { setShowForm(false); setForm(EMPTY_FORM); setAiPrompt(""); }}>
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* ΓöÇΓöÇΓöÇ Filter / Search ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <div className="filter-bar">
        <input
          type="text"
          placeholder="Search items..."
          value={search}
          onChange={e => setSearch(e.target.value)}
          className="table-search-input"
          aria-label="Search items"
        />
        <select
          value={typeFilter}
          onChange={e => setTypeFilter(e.target.value)}
          className="table-filter-select"
          aria-label="Filter by type"
        >
          <option value="">All types</option>
          <option value="service">Service</option>
          <option value="product">Product</option>
        </select>
        {(search || typeFilter) && (
          <span style={{ fontSize: "var(--text-sm)", color: "var(--text-tertiary)" }}>
            {filteredItems.length} result{filteredItems.length !== 1 ? "s" : ""}
          </span>
        )}
      </div>

      {loading ? <p style={{ color: "var(--text-tertiary)" }}>Loading...</p> : filteredItems.length === 0 ? (
        items.length === 0 ? (
          <div className="empty-state">
            <div className="icon">≡ƒôª</div>
            <h3>No items yet</h3>
            <p>Click "+ Add item" to create your first item, or describe it with your voice.</p>
          </div>
        ) : (
          <div className="empty-state">
            <div className="icon">≡ƒöì</div>
            <h3>No matching items</h3>
            <p>Try adjusting your search or filters.</p>
          </div>
        )
      ) : (
        <>
        {/* Desktop table */}
        <table className="data-table desktop-only-table">
          <thead>
            <tr>
              {([
                ["code", "Code"],
                ["name", "Name"],
                ["type", "Type"],
                ["sellingPrice", "Price"],
                ["vatRate", "VAT"],
                ["quantityOnHand", "On hand"],
              ] as [ItemSortKey, string][]).map(([key, label]) => (
                <th
                  key={key}
                  className={`sortable-th ${sortKey === key ? "sorted" : ""}`}
                  onClick={() => handleSort(key)}
                  aria-sort={sortKey === key ? (sortDir === "asc" ? "ascending" : "descending") : "none"}
                >
                  {label}
                  {sortKey === key && (
                    <span className="sort-indicator">{sortDir === "asc" ? " Γåæ" : " Γåô"}</span>
                  )}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filteredItems.map((item: any) => (
              <tr key={item.id} onClick={() => setSelected(item)} style={{ cursor: "pointer" }}>
                <td className="mono">{item.code}</td>
                <td>{item.name}</td>
                <td><span className="badge">{item.type}</span></td>
                <td className="num">{formatMoney(item.sellingPrice, fmt)}</td>
                <td>{item.vatRate}%</td>
                <td className="num">{item.type === "service" ? "ΓÇö" : item.quantityOnHand}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Mobile card view */}
        <div className="mobile-card-list">
          {filteredItems.map((item: any) => (
            <div key={item.id} className="mobile-card" onClick={() => setSelected(item)}>
              <div className="mobile-card-header">
                <span className="mobile-card-title">{item.name}</span>
                <span className="mobile-card-amount">{formatMoney(item.sellingPrice, fmt)}</span>
              </div>
              <div className="mobile-card-meta">
                <span className="mono">{item.code}</span>
                <span className="badge">{item.type}</span>
                <span>{item.vatRate}%</span>
                {item.type !== "service" && <span>Qty: {item.quantityOnHand}</span>}
              </div>
            </div>
          ))}
        </div>
        </>
      )}

      {/* Item detail panel */}
      {selected && (
        <div className="settings-card" style={{ marginTop: 16 }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 12 }}>
            <h3 style={{ fontSize: 14, fontWeight: 600 }}>{selected.name}</h3>
            <button className="btn-secondary" style={{ fontSize: "var(--text-sm)", padding: "2px 10px" }} onClick={() => setSelected(null)}>Γ£ò</button>
          </div>
          <div className="onboarding-details">
            <div className="detail-row"><span className="detail-label">Code</span><span className="mono">{selected.code}</span></div>
            <div className="detail-row"><span className="detail-label">Type</span><span className="badge">{selected.type}</span></div>
            {selected.description && <div className="detail-row"><span className="detail-label">Description</span><span>{selected.description}</span></div>}
            <div className="detail-row"><span className="detail-label">Unit</span><span>{selected.unitOfMeasure}</span></div>
            <div className="detail-row"><span className="detail-label">Cost price</span><span>{formatMoney(selected.costPrice, fmt)}</span></div>
            <div className="detail-row"><span className="detail-label">Selling price</span><span>{formatMoney(selected.sellingPrice, fmt)}</span></div>
            <div className="detail-row"><span className="detail-label">VAT rate</span><span>{selected.vatRate}%</span></div>
            {selected.type !== "service" && <div className="detail-row"><span className="detail-label">On hand</span><span>{selected.quantityOnHand}</span></div>}
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { useApp } from "../utils/context";

const API = "/api";
const TOKEN = "dev-bypass";

interface RegisterResult {
  registrationNumber: string;
  name: string;
  legalForm: string;
  address: string;
  registeredDate: string;
}

export function Onboarding() {
  const { setCompanyId } = useApp();
  const [step, setStep] = useState<"search" | "confirm" | "creating" | "done">("search");
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<RegisterResult[]>([]);
  const [selected, setSelected] = useState<RegisterResult | null>(null);
  const [companyCode, setCompanyCode] = useState("");
  const [searching, setSearching] = useState(false);
  const [creating, setCreating] = useState(false);
  const [error, setError] = useState("");
  const [createdCompany, setCreatedCompany] = useState<any>(null);

  // Generate code from company name (extract quoted part, take first 5 chars)
  function generateCode(name: string): string {
    const quoted = name.match(/[""\u201C\u201D]([^""\u201C\u201D]+)[""\u201C\u201D]/) || name.match(/"([^"]+)"/);
    const clean = (quoted ? quoted[1] : name).replace(/^(SIA|AS)\s+/i, "").trim();
    return clean.replace(/[^a-zA-Z0-9]/g, "").slice(0, 5).toUpperCase();
  }

  function handleSelect(r: RegisterResult) {
    setSelected(r);
    setCompanyCode(generateCode(r.name));
    setStep("confirm");
  }

  async function handleSearch() {
    if (!query.trim() || query.trim().length < 2) return;
    setSearching(true);
    setError("");
    try {
      const res = await fetch(`${API}/register/search?q=${encodeURIComponent(query.trim())}`, {
        headers: { Authorization: `Bearer ${TOKEN}` },
      });
      const json = await res.json();
      const data = json.data;
      if (data?.found && data.results?.length > 0) {
        setResults(data.results);
      } else {
        setResults([]);
        setError("No companies found. Try a different name or registration number.");
      }
    } catch {
      setError("Could not search the register. Try again.");
    } finally {
      setSearching(false);
    }
  }

  async function handleCreate() {
    if (!selected) return;
    setCreating(true);
    setStep("creating");
    try {
      // Parse address into parts
      const addressParts = selected.address.split(",").map((s) => s.trim());
      const city = addressParts.find((p) => /R─½ga|Liep─üja|Daugavpils|Jelgava|J┼½rmala|Ventspils|R─ôzekne/.test(p)) || addressParts[0] || "";
      const postalCode = addressParts.find((p) => /LV-\d{4}/.test(p)) || "";

      const res = await fetch(`${API}/companies`, {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${TOKEN}` },
        body: JSON.stringify({
          name: selected.name,
          code: companyCode || generateCode(selected.name),
          registrationNumber: selected.registrationNumber,
          vatNumber: `LV${selected.registrationNumber}`,
          legalAddress: {
            line1: selected.address,
            city: city || "R─½ga",
            postalCode: postalCode || "LV-1050",
            country: "LV",
          },
        }),
      });
      const json = await res.json();
      if (json.data) {
        setCreatedCompany(json.data);
        setCompanyId(json.data.id);
        setStep("done");
      } else {
        setError(json.error?.message || "Failed to create company");
        setStep("confirm");
      }
    } catch {
      setError("Failed to create company");
      setStep("confirm");
    } finally {
      setCreating(false);
    }
  }

  if (step === "done" && createdCompany) {
    return (
      <div className="onboarding-page">
        <div className="onboarding-card">
          <div className="onboarding-icon">Γ£à</div>
          <h2>Company created</h2>
          <p className="onboarding-subtitle">
            <strong>{createdCompany.name}</strong> is ready with 70+ Latvian chart of accounts pre-populated.
          </p>
          <div className="onboarding-details">
            <div className="detail-row"><span className="detail-label">Registration</span><span>{createdCompany.registrationNumber}</span></div>
            <div className="detail-row"><span className="detail-label">VAT number</span><span>{createdCompany.vatNumber || "ΓÇö"}</span></div>
            <div className="detail-row"><span className="detail-label">Currency</span><span>EUR</span></div>
            <div className="detail-row"><span className="detail-label">Country</span><span>Latvia</span></div>
          </div>
          <button className="btn-primary" style={{ marginTop: 24, width: "100%" }} onClick={() => window.location.href = "/"}>
            Go to dashboard
          </button>
        </div>
      </div>
    );
  }

  if (step === "creating") {
    return (
      <div className="onboarding-page">
        <div className="onboarding-card">
          <div className="onboarding-icon">ΓÅ│</div>
          <h2>Setting up your company...</h2>
          <p className="onboarding-subtitle">Creating chart of accounts, configuring VAT rates, and preparing the ledger.</p>
        </div>
      </div>
    );
  }

  if (step === "confirm" && selected) {
    return (
      <div className="onboarding-page">
        <div className="onboarding-card" style={{ maxWidth: 520 }}>
          <h2>Confirm company details</h2>
          <p className="onboarding-subtitle">This data was retrieved from the Latvian Enterprise Register.</p>
          <div className="onboarding-details">
            <div className="detail-row">
              <span className="detail-label">Company code</span>
              <input
                className="code-input"
                value={companyCode}
                onChange={(e) => setCompanyCode(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 5))}
                maxLength={5}
                placeholder="DAIS"
              />
            </div>
            <div className="detail-row"><span className="detail-label">Name</span><span><strong>{selected.name}</strong></span></div>
            <div className="detail-row"><span className="detail-label">Registration number</span><span className="mono">{selected.registrationNumber}</span></div>
            <div className="detail-row"><span className="detail-label">Legal form</span><span>{selected.legalForm}</span></div>
            <div className="detail-row"><span className="detail-label">Address</span><span>{selected.address}</span></div>
            <div className="detail-row"><span className="detail-label">Registered</span><span>{selected.registeredDate?.split("T")[0]}</span></div>
          </div>
          {error && <p style={{ color: "#FF3B30", fontSize: 13, marginTop: 12 }}>{error}</p>}
          <div className="btn-row" style={{ marginTop: 24 }}>
            <button className="btn-secondary" onClick={() => { setStep("search"); setSelected(null); }}>Back</button>
            <button className="btn-primary" style={{ flex: 1 }} onClick={handleCreate} disabled={creating}>
              {creating ? "Creating..." : "Create this company"}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Search step
  return (
    <div className="onboarding-page">
      <div className="onboarding-card" style={{ maxWidth: 600 }}>
        <div className="onboarding-icon">≡ƒÅó</div>
        <h2>Add a company</h2>
        <p className="onboarding-subtitle">
          Search the Latvian Enterprise Register by company name or registration number.
          We'll auto-fill all the details for you.
        </p>

        <div className="search-bar">
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleSearch()}
            placeholder="e.g. Dais, Microsoft, or 40003290084"
            autoFocus
          />
          <button className="btn-primary" onClick={handleSearch} disabled={searching}>
            {searching ? "Searching..." : "Search"}
          </button>
        </div>

        {error && <p style={{ color: "#FF3B30", fontSize: 13, marginTop: 12 }}>{error}</p>}

        {results.length > 0 && (
          <div className="search-results">
            {results.map((r, i) => (
              <button key={i} className="search-result-card" onClick={() => handleSelect(r)}>
                <div className="result-name">{r.name}</div>
                <div className="result-meta">
                  <span className="mono">{r.registrationNumber}</span>
                  <span className="result-dot">┬╖</span>
                  <span>{r.address}</span>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { formatMoney, formatDate } from "../utils/format";
import { AiInput } from "../components/AiInput";

type RecSortKey = "name" | "frequency" | "amount" | "nextRunDate" | "lastRunDate";
type SortDir = "asc" | "desc";

interface AccountOption {
  code: string;
  name: string;
  isPostable: boolean;
}

function getNextRunDate(frequency: string): string {
  const d = new Date();
  if (frequency === "monthly") d.setMonth(d.getMonth() + 1);
  else if (frequency === "quarterly") d.setMonth(d.getMonth() + 3);
  else if (frequency === "yearly") d.setFullYear(d.getFullYear() + 1);
  return d.toISOString().slice(0, 10);
}

// Match accounts by code prefix or name substring
function findAccounts(accounts: AccountOption[], query: string): AccountOption[] {
  if (!query || query.length < 1) return [];
  const q = query.toLowerCase();
  return accounts
    .filter(a => a.isPostable && (a.code.startsWith(q) || a.name.toLowerCase().includes(q)))
    .slice(0, 8);
}

function findAccountByCode(accounts: AccountOption[], code: string): AccountOption | undefined {
  return accounts.find(a => a.code === code);
}

function findAccountByName(accounts: AccountOption[], name: string): AccountOption | undefined {
  const q = name.toLowerCase();
  return accounts.find(a => a.isPostable && a.name.toLowerCase() === q);
}

// Guess debit/credit accounts from a template name/description
function guessAccounts(text: string, accounts: AccountOption[]): { debitCode: string; debitName: string; creditCode: string; creditName: string } {
  const t = text.toLowerCase();
  let debit = "", credit = "", debitName = "", creditName = "";

  // Common expense patterns
  const patterns: Array<{ keywords: string[]; debitCode: string; creditCode: string }> = [
    { keywords: ["rent", "office rent", "lease"], debitCode: "6330", creditCode: "2420" },
    { keywords: ["salary", "salaries", "wages", "payroll"], debitCode: "6510", creditCode: "2420" },
    { keywords: ["insurance"], debitCode: "6360", creditCode: "2420" },
    { keywords: ["cleaning", "office cleaning"], debitCode: "6330", creditCode: "2420" },
    { keywords: ["internet", "telecom", "phone", "mobile"], debitCode: "6340", creditCode: "2420" },
    { keywords: ["utilities", "electricity", "water", "heating"], debitCode: "6330", creditCode: "2420" },
    { keywords: ["subscription", "software", "saas", "license"], debitCode: "6350", creditCode: "2420" },
    { keywords: ["depreciation"], debitCode: "6380", creditCode: "1240" },
    { keywords: ["loan", "interest"], debitCode: "6610", creditCode: "2420" },
    { keywords: ["tax", "taxes"], debitCode: "6710", creditCode: "2420" },
    { keywords: ["advertising", "marketing", "ads"], debitCode: "6370", creditCode: "2420" },
    { keywords: ["transport", "fuel", "travel"], debitCode: "6340", creditCode: "2420" },
    { keywords: ["accounting", "audit", "legal"], debitCode: "6350", creditCode: "2420" },
  ];

  for (const p of patterns) {
    if (p.keywords.some(k => t.includes(k))) {
      debit = p.debitCode;
      credit = p.creditCode;
      break;
    }
  }

  // Look up names
  if (debit) {
    const acc = findAccountByCode(accounts, debit);
    if (acc) debitName = acc.name;
  }
  if (credit) {
    const acc = findAccountByCode(accounts, credit);
    if (acc) creditName = acc.name;
  }

  return { debitCode: debit, debitName, creditCode: credit, creditName };
}

export function RecurringEntries() {
  const { companyId, numberFormat: fmt, dateFormat: dfmt } = useApp();
  const [templates, setTemplates] = useState<any[]>([]);
  const [accounts, setAccounts] = useState<AccountOption[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({
    name: "", description: "", frequency: "monthly",
    debitCode: "", debitName: "", creditCode: "", creditName: "",
    amount: "", nextRunDate: getNextRunDate("monthly"), quickText: "",
  });
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState<RecSortKey>("name");
  const [sortDir, setSortDir] = useState<SortDir>("asc");
  const [debitSuggestions, setDebitSuggestions] = useState<AccountOption[]>([]);
  const [creditSuggestions, setCreditSuggestions] = useState<AccountOption[]>([]);
  const [focusField, setFocusField] = useState<string>("");
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    if (!companyId) return;
    loadTemplates();
    api.accounts(companyId).then((d: any) => {
      setAccounts((d as any[]).map((a: any) => ({ code: a.code, name: a.name, isPostable: a.isPostable })));
    }).catch(() => {});
  }, [companyId]);

  function loadTemplates() {
    setLoading(true);
    api.recurringTemplates(companyId).then((d: any) => setTemplates(d as any[])).catch(() => {}).finally(() => setLoading(false));
  }

  function updateForm(patch: Partial<typeof form>) {
    setForm(prev => ({ ...prev, ...patch }));
  }

  // Auto-suggest next run date when frequency changes
  function handleFrequencyChange(freq: string) {
    updateForm({ frequency: freq, nextRunDate: getNextRunDate(freq) });
  }

  // When debit code changes, look up the account name
  function handleDebitCodeChange(code: string) {
    updateForm({ debitCode: code });
    const acc = findAccountByCode(accounts, code);
    if (acc) updateForm({ debitCode: code, debitName: acc.name });
    setDebitSuggestions(findAccounts(accounts, code));
  }

  // When debit name changes, search for matching accounts
  function handleDebitNameChange(name: string) {
    updateForm({ debitName: name });
    const acc = findAccountByName(accounts, name);
    if (acc) updateForm({ debitName: name, debitCode: acc.code });
    setDebitSuggestions(findAccounts(accounts, name));
  }

  function handleCreditCodeChange(code: string) {
    updateForm({ creditCode: code });
    const acc = findAccountByCode(accounts, code);
    if (acc) updateForm({ creditCode: code, creditName: acc.name });
    setCreditSuggestions(findAccounts(accounts, code));
  }

  function handleCreditNameChange(name: string) {
    updateForm({ creditName: name });
    const acc = findAccountByName(accounts, name);
    if (acc) updateForm({ creditName: name, creditCode: acc.code });
    setCreditSuggestions(findAccounts(accounts, name));
  }

  function selectDebitAccount(acc: AccountOption) {
    updateForm({ debitCode: acc.code, debitName: acc.name });
    setDebitSuggestions([]);
  }

  function selectCreditAccount(acc: AccountOption) {
    updateForm({ creditCode: acc.code, creditName: acc.name });
    setCreditSuggestions([]);
  }

  async function handleCreate() {
    if (!form.name || !form.debitCode || !form.creditCode || !form.amount || !form.nextRunDate) return;
    const amt = parseFloat(form.amount);
    if (isNaN(amt) || amt <= 0) return;
    setCreating(true);
    try {
      await api.createRecurringTemplate(companyId, {
        name: form.name, description: form.description, frequency: form.frequency,
        nextRunDate: form.nextRunDate,
        lines: [
          { accountCode: form.debitCode, accountName: form.debitName || form.debitCode, debit: amt, credit: 0 },
          { accountCode: form.creditCode, accountName: form.creditName || form.creditCode, debit: 0, credit: amt },
        ],
      });
      setShowForm(false);
      setForm({
        name: "", description: "", frequency: "monthly",
        debitCode: "", debitName: "", creditCode: "", creditName: "",
        amount: "", nextRunDate: getNextRunDate("monthly"), quickText: "",
      });
      loadTemplates();
    } catch {
      // ignore
    } finally {
      setCreating(false);
    }
  }

  async function handleExecute(t: any) {
    await api.executeTemplate(companyId, t.id);
    loadTemplates();
  }

  function handleSort(key: RecSortKey) {
    if (sortKey === key) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  }

  const filteredTemplates = useMemo(() => {
    const q = search.toLowerCase().trim();
    let list = templates;
    if (q) {
      list = list.filter(t => t.name?.toLowerCase().includes(q) || t.description?.toLowerCase().includes(q));
    }
    list = [...list].sort((a, b) => {
      let av: any, bv: any;
      if (sortKey === "amount") {
        av = a.lines?.reduce((s: number, l: any) => s + (l.debit || 0), 0) || 0;
        bv = b.lines?.reduce((s: number, l: any) => s + (l.debit || 0), 0) || 0;
      } else {
        av = a[sortKey] ?? "";
        bv = b[sortKey] ?? "";
      }
      if (typeof av === "number" && typeof bv === "number") {
        return sortDir === "asc" ? av - bv : bv - av;
      }
      av = String(av).toLowerCase();
      bv = String(bv).toLowerCase();
      if (av < bv) return sortDir === "asc" ? -1 : 1;
      if (av > bv) return sortDir === "asc" ? 1 : -1;
      return 0;
    });
    return list;
  }, [templates, search, sortKey, sortDir]);

  if (!companyId) return <div className="empty-state"><div className="icon">≡ƒÅó</div><h3>No company selected</h3></div>;

  const suggestionStyle: React.CSSProperties = {
    position: "absolute", top: "100%", left: 0, right: 0, zIndex: 10,
    background: "#fff", border: "1px solid #E8E8E8", borderRadius: 8,
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)", maxHeight: 200, overflowY: "auto",
  };
  const suggestionItemStyle: React.CSSProperties = {
    padding: "8px 12px", cursor: "pointer", fontSize: 13, display: "flex", justifyContent: "space-between",
  };

  return (
    <div>
      <div className="coa-header">
        <h2 className="page-title">Recurring entries</h2>
        <button className="btn-primary" onClick={() => setShowForm(!showForm)}>{showForm ? "Cancel" : "+ New template"}</button>
      </div>

      {showForm && (
        <div className="settings-card" style={{ marginBottom: 20 }}>
          <h3 style={{ fontSize: 14, fontWeight: 600, marginBottom: 12 }}>New recurring template</h3>

          {/* Quick fill with AI + voice */}
          <div style={{ marginBottom: 16 }}>
            <div className="detail-label">Describe the entry</div>
            <AiInput
              placeholder="e.g. 'Monthly office rent 500 EUR' or 'Quarterly insurance 1200 EUR'"
              buttonLabel="Auto-fill"
              loadingLabel="Filling..."
              onSubmit={async (text) => {
                updateForm({ quickText: text });
                // run quick-fill logic
                const guess = guessAccounts(text, accounts);
                const amtMatch = text.match(/(\d[\d\s]*[.,]?\d*)\s*(eur|Γé¼)/i) || text.match(/(Γé¼|eur)\s*(\d[\d\s]*[.,]?\d*)/i);
                let amount = form.amount;
                if (amtMatch) {
                  const raw = (amtMatch[1] || amtMatch[2]).replace(/\s/g, "").replace(",", ".");
                  const parsed = parseFloat(raw);
                  if (!isNaN(parsed)) amount = String(parsed);
                }
                updateForm({
                  name: form.name || text.slice(0, 60),
                  description: form.description || text,
                  debitCode: guess.debitCode || form.debitCode,
                  debitName: guess.debitName || form.debitName,
                  creditCode: guess.creditCode || form.creditCode,
                  creditName: guess.creditName || form.creditName,
                  amount: amount || form.amount,
                  quickText: "",
                });
              }}
            />
            <span className="field-hint">Describe what you need ΓÇö type or use voice. Fields will be filled automatically.</span>
          </div>

          <div style={{ borderTop: "1px solid #E8E8E8", paddingTop: 16 }}>
            <div className="form-grid-2">
              <div>
                <div className="detail-label required">Name</div>
                <input value={form.name} onChange={e => updateForm({ name: e.target.value })} placeholder="e.g. Monthly office rent" className="settings-input" />
              </div>
              <div>
                <div className="detail-label">Description</div>
                <input value={form.description} onChange={e => updateForm({ description: e.target.value })} placeholder="Optional notes" className="settings-input" />
              </div>
              <div>
                <div className="detail-label">Frequency</div>
                <select value={form.frequency} onChange={e => handleFrequencyChange(e.target.value)} className="settings-input">
                  <option value="monthly">Monthly</option>
                  <option value="quarterly">Quarterly</option>
                  <option value="yearly">Yearly</option>
                </select>
              </div>
              <div>
                <div className="detail-label required">Next run date</div>
                <input type="date" value={form.nextRunDate} onChange={e => updateForm({ nextRunDate: e.target.value })} className="settings-input" />
              </div>

              {/* Debit account with autocomplete */}
              <div style={{ position: "relative" }}>
                <div className="detail-label required">Debit account</div>
                <input
                  value={form.debitCode}
                  onChange={e => handleDebitCodeChange(e.target.value)}
                  onFocus={() => setFocusField("debitCode")}
                  onBlur={() => setTimeout(() => setFocusField(""), 150)}
                  placeholder="e.g. 6330"
                  className="settings-input"
                />
                {focusField === "debitCode" && debitSuggestions.length > 0 && (
                  <div style={suggestionStyle}>
                    {debitSuggestions.map(a => (
                      <div key={a.code} style={suggestionItemStyle} onMouseDown={() => selectDebitAccount(a)}>
