                  className="settings-input"
                />
                {focusField === "creditCode" && creditSuggestions.length > 0 && (
                  <div style={suggestionStyle}>
                    {creditSuggestions.map(a => (
                      <div key={a.code} style={suggestionItemStyle} onMouseDown={() => selectCreditAccount(a)}>
