}

function BudgetVsActual({ data }: { data: any }) {
  const { companyId, numberFormat: fmt } = useApp();
  const items = Array.isArray(data) ? data : [];
  const [showAdd, setShowAdd] = useState(false);
  const [budgetAccountCode, setBudgetAccountCode] = useState("");
  const [budgetAmount, setBudgetAmount] = useState("");
  const [budgetYear, setBudgetYear] = useState(new Date().getFullYear());
  const [saving, setSaving] = useState(false);

  async function handleAddBudget() {
    if (!budgetAccountCode || !budgetAmount || !companyId) return;
    setSaving(true);
    try {
      await api.setBudget(companyId, {
        year: budgetYear,
        entries: [{ accountCode: budgetAccountCode, monthlyAmount: parseFloat(budgetAmount) }],
      });
      setBudgetAccountCode("");
      setBudgetAmount("");
      setShowAdd(false);
      // Trigger re-fetch by brief reload
      window.location.reload();
    } catch (err: any) { alert(err.message); }
    finally { setSaving(false); }
  }

  return (
    <div className="metric-card">
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <h3 style={{ fontSize: 16, fontWeight: 600, margin: 0 }}>Budget vs actual</h3>
        <button className="btn-secondary" style={{ fontSize: "var(--text-sm)" }} onClick={() => setShowAdd(!showAdd)}>
          {showAdd ? "Cancel" : "+ Add budget"}
        </button>
      </div>

      {showAdd && (
        <div style={{ marginBottom: 16, padding: 14, background: "var(--bg-page)", borderRadius: "var(--radius-sm)", border: "1px solid var(--border)" }}>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(140px, 1fr))", gap: 10 }}>
            <div>
              <label style={{ display: "block", fontSize: 11, fontWeight: 500, color: "var(--text-tertiary)", textTransform: "uppercase", letterSpacing: "0.02em", marginBottom: 4 }}>Account code</label>
              <input type="text" value={budgetAccountCode} onChange={e => setBudgetAccountCode(e.target.value)} placeholder="e.g. 6330" className="form-input" style={{ width: "100%" }} aria-label="Budget account code" />
            </div>
            <div>
              <label style={{ display: "block", fontSize: 11, fontWeight: 500, color: "var(--text-tertiary)", textTransform: "uppercase", letterSpacing: "0.02em", marginBottom: 4 }}>Monthly amount (Γé¼)</label>
              <input type="number" step="0.01" value={budgetAmount} onChange={e => setBudgetAmount(e.target.value)} placeholder="1200" className="form-input" style={{ width: "100%" }} aria-label="Monthly budget amount" />
            </div>
            <div>
              <label style={{ display: "block", fontSize: 11, fontWeight: 500, color: "var(--text-tertiary)", textTransform: "uppercase", letterSpacing: "0.02em", marginBottom: 4 }}>Year</label>
              <input type="number" value={budgetYear} onChange={e => setBudgetYear(Number(e.target.value))} className="form-input" style={{ width: "100%" }} aria-label="Budget year" />
            </div>
          </div>
          <button className="btn-primary" style={{ marginTop: 10 }} onClick={handleAddBudget} disabled={saving || !budgetAccountCode || !budgetAmount}>
            {saving ? "Saving..." : "Add budget entry"}
          </button>
        </div>
      )}

      {items.length === 0 ? <p style={{ color: "var(--text-tertiary)" }}>No budget data yet. Click "+ Add budget" to set monthly budgets for expense accounts.</p> : (
        <table className="data-table">
          <thead><tr><th>Code</th><th>Account</th><th style={{ textAlign: "right" }}>Budget</th><th style={{ textAlign: "right" }}>Actual</th><th style={{ textAlign: "right" }}>Variance</th><th style={{ textAlign: "right" }}>%</th></tr></thead>
          <tbody>
            {items.map((i: any) => (
              <tr key={i.accountCode}>
                <td className="mono">{i.accountCode}</td>
                <td>{i.accountName}</td>
                <td className="num">{formatMoney(i.budget, fmt)}</td>
                <td className="num">{formatMoney(i.actual, fmt)}</td>
                <td className="num" style={{ color: i.variance >= 0 ? "#34C759" : "#FF3B30" }}>{formatMoney(i.variance, fmt)}</td>
                <td className="num">{i.variancePercent.toFixed(1)}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { api } from "../utils/api";
import { useApp } from "../utils/context";
import { FORMAT_LABELS, formatSequencePreview, DATE_FORMAT_LABELS, DATETIME_FORMAT_LABELS } from "../utils/format";
import type { NumberFormat, SequenceType, NumberSequence, DateFormat, DateTimeFormat } from "@shared/types";
import { DEFAULT_SEQUENCES, SEQUENCE_LABELS } from "@shared/types";

export function Settings() {
  const { companyId, setCompanyId, refreshCompanies } = useApp();
  const navigate = useNavigate();
  const [company, setCompany] = useState<any>(null);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [deleteStep, setDeleteStep] = useState<"idle" | "confirm" | "confirm-txns" | "deleting">("idle");
  const [txnCount, setTxnCount] = useState(0);
  const [deleteError, setDeleteError] = useState("");

  // Editable fields
  const [code, setCode] = useState("");
  const [name, setName] = useState("");
  const [vatNumber, setVatNumber] = useState("");
  const [paymentTerms, setPaymentTerms] = useState(30);
  const [numberFormat, setNumberFormat] = useState<NumberFormat>("space_comma");
  const [dateFormat, setDateFormat] = useState<DateFormat>("dd.MM.yyyy");
  const [dateTimeFormat, setDateTimeFormat] = useState<DateTimeFormat>("24h");
  const [sequences, setSequences] = useState<Record<string, NumberSequence>>({});

  useEffect(() => {
    if (!companyId) return;
    api.company(companyId).then((data: any) => {
      setCompany(data);
      setCode(data.code || "");
      setName(data.name || "");
      setVatNumber(data.vatNumber || "");
      setPaymentTerms(data.settings?.defaultPaymentTermsDays || 30);
      setNumberFormat(data.settings?.numberFormat || "space_comma");
      setDateFormat(data.settings?.dateFormat || "dd.MM.yyyy");
      setDateTimeFormat(data.settings?.dateTimeFormat || "24h");
      // Merge saved sequences with defaults
      const saved = data.settings?.sequences || {};
      const merged: Record<string, NumberSequence> = {};
      for (const key of Object.keys(DEFAULT_SEQUENCES)) {
        merged[key] = saved[key] || { ...DEFAULT_SEQUENCES[key as SequenceType] };
      }
      setSequences(merged);
    });
  }, [companyId]);

  async function handleSave() {
    if (!companyId) return;
    setSaving(true);
    setSaved(false);
    try {
      const updated = await api.updateCompany(companyId, {
        code: code.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 5),
        name,
        vatNumber: vatNumber || undefined,
        settings: {
          ...company.settings,
          defaultPaymentTermsDays: paymentTerms,
          numberFormat,
          dateFormat,
          dateTimeFormat,
          sequences,
        },
      });
      setCompany(updated);
      setSaved(true);
      await refreshCompanies();
      setTimeout(() => setSaved(false), 2000);
    } catch {
      // ignore
    } finally {
      setSaving(false);
    }
  }

  if (!companyId) return (
    <div className="empty-state">
      <div className="icon">≡ƒÅó</div>
      <h3>No company selected</h3>
    </div>
  );

  if (!company) return <p style={{ color: "#A0A0A0" }}>Loading...</p>;

  return (
    <div>
